import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type EffectId = 'plexus' | 'pixel' | 'halftone' | 'matrix' | 'line';

export type ApplyMode = 'subject' | 'background' | 'both';

export interface GlobalParams {
  effectColor: string;
  subjectColor: string;
  bw: boolean;
  xray: boolean;
  mixMode: boolean;
  applyTo: ApplyMode;
  maskStrength: number;
  maskThreshold: number; // For MVP segmentation logic
}

export interface EffectDef {
  id: EffectId;
  name: string;
  description: string;
  defaultParams: Record<string, number | string | boolean>;
  paramConfig: Record<string, ParamConfig>;
}

export interface ParamConfig {
  type: 'slider' | 'toggle' | 'select' | 'color';
  min?: number;
  max?: number;
  step?: number;
  options?: string[];
  randomRange?: [number, number]; // [min, max] for random generation
}

// Specific Effect Params Types (for type safety in render engine)
export interface PlexusParams {
  pointCount: number;
  linkDistance: number;
  lineWidth: number;
  speed: number;
}

export interface PixelParams {
  pixelSize: number;
  posterize: number;
}

export interface HalftoneParams {
  dotSize: number;
  angle: number;
}

export interface MatrixParams {
  density: number;
  fallSpeed: number;
  fontSize: number;
}

export interface LineParams {
  threshold: number;
  strokeWidth: number;
}

import { EffectDef, GlobalParams } from './types';

