// Convert Hex to RGB object
export const hexToRgb = (hex: string) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : { r: 255, g: 255, b: 255 };
};

export const randomInt = (min: number, max: number) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

export const randomFloat = (min: number, max: number) => {
  return Math.random() * (max - min) + min;
};

// Simple luminance calculation
export const getLuminance = (r: number, g: number, b: number) => {
  return 0.299 * r + 0.587 * g + 0.114 * b;
};

import { EffectId, GlobalParams } from '../types';
import { hexToRgb, getLuminance } from './utils';

// Helper to create a mask buffer based on luminance threshold (MVP segmentation)
export const createLuminanceMask = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  threshold: number
): ImageData => {
  const frame = ctx.getImageData(0, 0, width, height);
  const data = frame.data;
  const maskData = new Uint8ClampedArray(data.length);

  // Create mask: 255 = subject (foreground), 0 = background
  // Assuming subject is darker or lighter than threshold? 
  // For MVP: Let's assume standard "Greenscreen" logic is too specific.
  // We'll use a simple "Difference from average" or just simple luminance keying.
  // Let's go with: High contrast objects are subject.

  for (let i = 0; i < data.length; i += 4) {
    const lum = getLuminance(data[i], data[i + 1], data[i + 2]);
    // Normalized threshold 0-255
    const threshVal = threshold * 255;

    // Invertible logic could be added, but let's assume Subject is Darker than background (sketch mode)
    // or Lighter. Let's make it Lighter = Subject for now.
    const isSubject = lum > threshVal;

    const alpha = isSubject ? 255 : 0;

    maskData[i] = alpha;     // R
    maskData[i + 1] = alpha; // G
    maskData[i + 2] = alpha; // B
    maskData[i + 3] = 255;   // A
  }

  return new ImageData(maskData, width, height);
};

// === EFFECT RENDERERS ===

const drawPixel = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any
) => {
  const size = Math.max(1, params.pixelSize);
  const w = Math.ceil(width / size);
  const h = Math.ceil(height / size);

  // 1. Draw scaled down
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = w;
  tempCanvas.height = h;
  const tempCtx = tempCanvas.getContext('2d');
  if (!tempCtx) return;

  // Turn off smoothing for pixel art look
  tempCtx.imageSmoothingEnabled = false;
  tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

  // 2. Draw back scaled up
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(tempCanvas, 0, 0, width, height);
  ctx.imageSmoothingEnabled = true;
};

const drawHalftone = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any,
  color: string
) => {
  const dotSize = Math.max(2, params.dotSize);
  // Get source data
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;

  // Clear and prepare for drawing dots
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = color;

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (y * width + x) * 4;
      if (i < data.length) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const lum = getLuminance(r, g, b) / 255; // 0 to 1

        const radius = (dotSize / 2) * lum;

        ctx.beginPath();
        ctx.arc(x + dotSize/2, y + dotSize/2, radius, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
};

const drawMatrix = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    params: any,
    color: string,
    time: number
) => {
    // Semi-transparent fade for trails
    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = color;
    ctx.font = `${params.fontSize}px monospace`;

    const cols = Math.floor(width / params.fontSize);

    // We need a pseudo-random determiner based on time and position
    // Since we don't have persistent state here easily without passing it in,
    // we will simulate the rain effect using time and modulo.

    for (let i = 0; i < cols; i++) {
        // Simple distinct drop for each column
        const speed = params.fallSpeed * 10;
        const offset = (i * 123.45) % height; // Random start pos
        const y = (time * speed + offset) % height;

        const charIndex = Math.floor((time + i) % 36);
        const char = charIndex.toString(36); // 0-9, a-z

        // Only draw if within bounds (it always is due to mod)
        // Add some "jitter" or randomness to only draw some characters
        if (Math.random() > (1 - params.density/100)) {
            ctx.fillText(char, i * params.fontSize, y);
        }
    }
}

// Particle system state cache for Plexus to maintain continuity
const plexusParticles: {x: number, y: number, vx: number, vy: number}[] = [];

const drawPlexus = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any,
  color: string,
  maskData: ImageData | null
) => {
  // Init or Resize particles
  const count = params.pointCount;
  if (plexusParticles.length !== count) {
     plexusParticles.length = 0;
     for(let i=0; i<count; i++) {
        plexusParticles.push({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - 0.5) * params.speed,
            vy: (Math.random() - 0.5) * params.speed
        });
     }
  }

  const rgb = hexToRgb(color);
  const linkDistSq = params.linkDistance * params.linkDistance;

  ctx.clearRect(0, 0, width, height);
  ctx.lineWidth = params.lineWidth;

  // Update and Draw
  for(let i=0; i<count; i++) {
      const p = plexusParticles[i];
      p.x += p.vx * params.speed;
      p.y += p.vy * params.speed;

      // Bounce
      if (p.x < 0 || p.x > width) p.vx *= -1;
      if (p.y < 0 || p.y > height) p.vy *= -1;

      // Mask Check (if mask exists, repulse or attract could be implemented, 
      // but for MVP let's just only draw if inside mask?)
      // For visual clarity, let's draw regardless but alpha depends on mask if provided?
      // Actually, Plexus usually looks cool everywhere. Let's just draw.

      // Draw Connections
      for(let j=i+1; j<count; j++) {
          const p2 = plexusParticles[j];
          const dx = p.x - p2.x;
          const dy = p.y - p2.y;
          const distSq = dx*dx + dy*dy;

          if (distSq < linkDistSq) {
              const alpha = 1 - (distSq / linkDistSq);
              ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
              ctx.beginPath();
              ctx.moveTo(p.x, p.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.stroke();
          }
      }

      ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 1)`;
      ctx.fillRect(p.x - 1, p.y - 1, 2, 2);
  }
};

const drawLine = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    params: any,
    color: string
) => {
    // Sobel-ish edge detection simulation or just threshold contour
    // For performance in JS: Random strokes that follow gradient is hard.
    // Simple approach: Horizontal scan, if brightness change > threshold, draw line.

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    ctx.clearRect(0, 0, width, height);
    ctx.strokeStyle = color;
    ctx.lineWidth = params.strokeWidth;
    ctx.beginPath();

    const threshold = params.threshold;

    // Scan every 3rd pixel for speed
    for (let y = 0; y < height; y+=2) {
        for (let x = 0; x < width - 1; x+=2) {
            const i = (y * width + x) * 4;
            const iNext = (y * width + (x+1)) * 4;

            if (iNext < data.length) {
                const lum1 = getLuminance(data[i], data[i+1], data[i+2]);
                const lum2 = getLuminance(data[iNext], data[iNext+1], data[iNext+2]);

                if (Math.abs(lum1 - lum2) > threshold) {
                    ctx.moveTo(x, y);
                    ctx.lineTo(x+2, y+2); // Tiny hatch
                }
            }
        }
    }
    ctx.stroke();
}


// === MAIN RENDER PIPELINE ===

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  source: HTMLImageElement | HTMLVideoElement,
  effectId: EffectId,
  params: any,
  global: GlobalParams,
  time: number
) => {
  const width = ctx.canvas.width;
  const height = ctx.canvas.height;

  // 1. Draw Source to Canvas (Reset)
  ctx.globalCompositeOperation = 'source-over';
  ctx.drawImage(source, 0, 0, width, height);

  // 2. Generate/Update Mask (This creates the alpha map for subject)
  // Optimization: Only do this if we actually need separation
  let maskData: ImageData | null = null;
  if (global.applyTo !== 'both') {
     // Store current frame data
     maskData = createLuminanceMask(ctx, width, height, global.maskThreshold);
  }

  // 3. Pre-Effect Filters (B/W, XRAY) on the source pixels
  const rawImage = ctx.getImageData(0, 0, width, height);
  const rawData = rawImage.data;

  if (global.bw || global.xray) {
      for(let i=0; i < rawData.length; i+=4) {
          let r = rawData[i];
          let g = rawData[i+1];
          let b = rawData[i+2];

          if (global.bw) {
              const lum = getLuminance(r, g, b);
              r = g = b = lum;
          }

          if (global.xray) {
              r = 255 - r;
              g = 255 - g;
              b = 255 - b;
              // High contrast push
              r = (r - 128) * 2 + 128;
              g = (g - 128) * 2 + 128;
              b = (b - 128) * 2 + 128;
          }

          // Apply subject tint if enabled
          // (Simplified for MVP: global.subjectColor tints everything before effect)
          // Ideally check mask here.

          rawData[i] = Math.min(255, Math.max(0, r));
          rawData[i+1] = Math.min(255, Math.max(0, g));
          rawData[i+2] = Math.min(255, Math.max(0, b));
      }
      ctx.putImageData(rawImage, 0, 0);
  }

  // 4. Apply Effect
  // We need to isolate the area to apply the effect if masking is on.
  // Strategy:
  // A. Save current canvas (Pre-Effect State)
  // B. Apply Effect to entire canvas
  // C. Save Effect canvas
  // D. Composite using Mask

  // Step A: Save Background (Original or Filtered)
  const bgCanvas = document.createElement('canvas');
  bgCanvas.width = width;
  bgCanvas.height = height;
  bgCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

  // Step B: Run Effect Renderer (mutates ctx)
  switch (effectId) {
    case 'pixel':
      drawPixel(ctx, width, height, params);
      break;
    case 'halftone':
      drawHalftone(ctx, width, height, params, global.effectColor);
      break;
    case 'plexus':
       // For Plexus, we usually want it ON TOP of the image, not replacing it entirely
       // unless it's a fill effect.
       // Let's draw the image again first if plexus is additive
       ctx.drawImage(bgCanvas, 0, 0); 
       drawPlexus(ctx, width, height, params, global.effectColor, maskData);
       break;
    case 'matrix':
       // Matrix replaces content usually
       drawMatrix(ctx, width, height, params, global.effectColor, time);
       break;
    case 'line':
       drawLine(ctx, width, height, params, global.effectColor);
       break;
  }

  // Step C: Composite (Masking)
  if (global.applyTo !== 'both' && maskData) {
      // 1. Get the Effect Result
      const effectCanvas = document.createElement('canvas');
      effectCanvas.width = width;
      effectCanvas.height = height;
      effectCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

      // 2. Clear Main Context
      ctx.clearRect(0, 0, width, height);

      // 3. Draw Background Layer
      // If applyTo is 'subject', background is the Original (bgCanvas).
      // If applyTo is 'background', background is the Effect (effectCanvas).
      const baseLayer = global.applyTo === 'subject' ? bgCanvas : effectCanvas;
      const topLayer = global.applyTo === 'subject' ? effectCanvas : bgCanvas;

      ctx.drawImage(baseLayer, 0, 0);

      // 4. Mask the Top Layer
      // We need to cut out the top layer using the mask
      const scratchCtx = document.createElement('canvas');
      scratchCtx.width = width;
      scratchCtx.height = height;
      const sCtx = scratchCtx.getContext('2d');
      if (sCtx) {
          sCtx.drawImage(topLayer, 0, 0);
          // Apply mask alpha
          const topData = sCtx.getImageData(0, 0, width, height);
          const tData = topData.data;
          const mData = maskData.data;

          for(let i=3; i<tData.length; i+=4) {
              // mData[i] is 255 if subject, 0 if background
              // If we want to show 'subject', we need alpha 255 where mData is 255.
              // If applyTo is 'subject', TopLayer is Effect. We want Effect on Subject.
              // So alpha = mData[i] * global.maskStrength.

              let maskVal = mData[i-3]; // R channel of mask contains 0 or 255

              if (global.applyTo === 'background') {
                  // Invert mask logic: We want TopLayer (Original) on Subject.
                  // So we show TopLayer where mask is 255.
                  // Wait, if applyTo Background: Base is Effect. Top is Original.
                  // We want Original to show where Subject is.
                  // So maskVal is correct.
              } 

              // Blending mask strength
              const alphaFactor = maskVal > 128 ? global.maskStrength : 0;
              tData[i] = tData[i] * alphaFactor; 
          }
          sCtx.putImageData(topData, 0, 0);

          // Draw masked top layer
          ctx.drawImage(scratchCtx, 0, 0);
      }
  }
};

import React from 'react';
import { Upload, Download, Save, Image as ImageIcon, Video } from 'lucide-react';

interface HeaderProps {
  onUpload: (file: File) => void;
  onExport: () => void;
  isVideo: boolean;
}

const Header: React.FC<HeaderProps> = ({ onUpload, onExport, isVideo }) => {
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onUpload(e.target.files[0]);
    }
  };

  return (
    <header className="flex items-center justify-between px-6 py-4 bg-zinc-900 border-b border-zinc-800 z-10 relative">
      <div className="flex items-center gap-2">
        <div className="w-8 h-8 bg-indigo-500 rounded-lg flex items-center justify-center">
            <span className="font-bold text-white text-lg">V</span>
        </div>
        <h1 className="text-xl font-bold tracking-tight text-white hidden sm:block">
          Visual<span className="text-indigo-400">Parameter</span>
        </h1>
      </div>

      <div className="flex items-center gap-4">
        <label className="flex items-center gap-2 cursor-pointer bg-zinc-800 hover:bg-zinc-700 text-sm px-4 py-2 rounded-md transition-colors border border-zinc-700">
          <Upload size={16} />
          <span>Upload</span>
          <input 
            type="file" 
            accept="image/*,video/mp4" 
            className="hidden" 
            onChange={handleFileChange} 
          />
        </label>

        <button 
            onClick={onExport}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white text-sm px-4 py-2 rounded-md transition-colors"
        >
          <Download size={16} />
          <span>Export {isVideo ? 'Frame' : 'Image'}</span>
        </button>
      </div>
    </header>
  );
};

export default Header;

import React from 'react';
import { GlobalParams, EffectDef, ParamConfig } from '../types';
import { Sliders, Zap, Layers, Eye, Droplet, Shuffle } from 'lucide-react';

interface ControlPanelProps {
  globalParams: GlobalParams;
  setGlobalParams: (p: GlobalParams) => void;
  activeEffect: EffectDef;
  effectParams: any;
  setEffectParams: (p: any) => void;
}

const ControlPanel: React.FC<ControlPanelProps> = ({
  globalParams,
  setGlobalParams,
  activeEffect,
  effectParams,
  setEffectParams,
}) => {

  const updateGlobal = (key: keyof GlobalParams, value: any) => {
    setGlobalParams({ ...globalParams, [key]: value });
  };

  const updateEffect = (key: string, value: any) => {
    setEffectParams({ ...effectParams, [key]: value });
  };

  return (
    <div className="w-full md:w-80 bg-zinc-900 border-l border-zinc-800 h-full flex flex-col overflow-y-auto">

      {/* --- Global Controls --- */}
      <div className="p-6 border-b border-zinc-800">
        <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-4 flex items-center gap-2">
          <Sliders size={14} /> Global Settings
        </h3>

        {/* Colors */}
        <div className="grid grid-cols-2 gap-4 mb-6">
          <div>
            <label className="text-xs text-zinc-400 mb-2 block">Effect Color</label>
            <div className="flex items-center gap-2">
                <input 
                    type="color" 
                    value={globalParams.effectColor} 
                    onChange={(e) => updateGlobal('effectColor', e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer bg-transparent border-none p-0"
                />
                <span className="text-xs text-zinc-500 font-mono">{globalParams.effectColor}</span>
            </div>
          </div>
          <div>
            <label className="text-xs text-zinc-400 mb-2 block">Subject Color</label>
             <div className="flex items-center gap-2">
                <input 
                    type="color" 
                    value={globalParams.subjectColor} // Note: This isn't fully implemented in renderer yet for MVP simplicity
                    onChange={(e) => updateGlobal('subjectColor', e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer bg-transparent border-none p-0"
                />
                 <span className="text-xs text-zinc-500 font-mono">{globalParams.subjectColor}</span>
             </div>
          </div>
        </div>

        {/* Toggles */}
        <div className="grid grid-cols-2 gap-3 mb-6">
           <button 
             onClick={() => updateGlobal('bw', !globalParams.bw)}
             className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${globalParams.bw ? 'bg-zinc-100 text-black border-white' : 'bg-zinc-800 text-zinc-400 border-zinc-700 hover:bg-zinc-700'}`}
           >
              <Eye size={18} className="mb-1" />
              <span className="text-xs font-medium">B/W</span>
           </button>
           <button 
             onClick={() => updateGlobal('xray', !globalParams.xray)}
             className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${globalParams.xray ? 'bg-indigo-500 text-white border-indigo-400' : 'bg-zinc-800 text-zinc-400 border-zinc-700 hover:bg-zinc-700'}`}
           >
              <Zap size={18} className="mb-1" />
              <span className="text-xs font-medium">X-RAY</span>
           </button>
        </div>

        {/* Mix Mode */}
