import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const [dimensions, setDimensions] = useState({ w: 800, h: 600 });
  const [mediaLoaded, setMediaLoaded] = useState(false);

  // Handle Resize
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const { clientWidth, clientHeight } = containerRef.current;
        // Keep aspect ratio of source if loaded, otherwise fit container
        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && videoRef.current) {
                 srcW = videoRef.current.videoWidth;
                 srcH = videoRef.current.videoHeight;
             } else if (imageRef.current) {
                 srcW = imageRef.current.naturalWidth;
                 srcH = imageRef.current.naturalHeight;
             }

             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 setDimensions({ w: srcW * scale, h: srcH * scale });
                 return;
             }
        }
        setDimensions({ w: clientWidth, h: clientHeight });
      }
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, [mediaSrc, isVideo, mediaLoaded]);

  // Load Media
  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;

      if (isVideo) {
          if (videoRef.current) {
              videoRef.current.src = mediaSrc;
              videoRef.current.load();
              videoRef.current.onloadedmetadata = () => {
                  setMediaLoaded(true);
                  videoRef.current?.play();
                  // Trigger resize calculation
                  window.dispatchEvent(new Event('resize'));
              };
          }
      } else {
          const img = new Image();
          img.src = mediaSrc;
          img.onload = () => {
              imageRef.current = img;
              setMediaLoaded(true);
              window.dispatchEvent(new Event('resize'));
          }
      }
  }, [mediaSrc, isVideo]);


  // Render Loop
  const animate = (time: number) => {
    if (canvasRef.current && mediaLoaded) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? videoRef.current : imageRef.current;

      if (ctx && source) {
          // Normalize time for effects
          const elapsed = (Date.now() - startTimeRef.current) / 1000;

          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeEffect, effectParams, globalParams, mediaLoaded]); // Re-bind animate if these change, or use ref for params to avoid re-bind

  return (
    <div ref={containerRef} className="flex-1 bg-zinc-950 flex items-center justify-center relative overflow-hidden">
      {!mediaSrc && (
          <div className="text-zinc-600 text-center">
              <p className="text-lg font-medium mb-2">No Media Loaded</p>
              <p className="text-sm">Upload an image or video to begin</p>
          </div>
      )}

      {/* Hidden Source Elements */}
      <video 
        ref={videoRef} 
        className="hidden" 
        muted 
        loop 
        playsInline 
        crossOrigin="anonymous" 
      />
      {/* Image ref is handled in memory via new Image() usually, but keeping ref if needed */}

      <canvas
        ref={canvasRef}
        width={dimensions.w}
        height={dimensions.h}
        className="max-w-full max-h-full shadow-2xl shadow-black"
        style={{ imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto' }}
      />
    </div>
  );
};

export default CanvasRenderer;

import React, { useState, useEffect, useCallback } from 'react';
import Header from './components/Header';
import CanvasRenderer from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import EffectSelector from './components/EffectSelector';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  // Handle Upload
  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  // Handle Export
  const handleExport = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = `visual-parameter-${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  // Handle Effect Selection
  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    // When switching, load defaults for that effect
    // In a real app, we might want to preserve adjusted params per effect id
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic
  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (globalParams.mixMode) {
      const mix = () => {
        // 1. Pick random effect
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);

        // 2. Randomize Params
        const newParams: any = {};
        Object.entries(randomEffect.paramConfig).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);

        // 3. Randomize Global (Optional, maybe keep colors steady?)
        // Let's randomize Xray/BW occasionally
        if (Math.random() > 0.7) setGlobalParams(p => ({ ...p, bw: !p.bw }));
        if (Math.random() > 0.8) setGlobalParams(p => ({ ...p, xray: !p.xray }));
      };

      // Initial Mix
      mix();
      // Loop
      interval = setInterval(mix, 2000); // Change every 2 seconds
    }

    return () => clearInterval(interval);
  }, [globalParams.mixMode]);

  return (
    <div className="flex flex-col h-screen w-full bg-zinc-950 text-white overflow-hidden">
      <Header 
        onUpload={handleUpload} 
        onExport={handleExport}
        isVideo={isVideo}
      />

      <div className="flex flex-1 overflow-hidden">
        <CanvasRenderer 
          mediaSrc={mediaSrc || "https://picsum.photos/800/600"} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
        />

        <ControlPanel 
          globalParams={globalParams}
          setGlobalParams={setGlobalParams}
          activeEffect={activeEffect}
          effectParams={effectParams}
          setEffectParams={setEffectParams}
        />
      </div>

      <EffectSelector 
        activeEffectId={activeEffect.id}
        onSelect={handleEffectSelect}
      />
    </div>
  );
};

export default App;

