import { EffectId, GlobalParams } from '../types';
import { hexToRgb, getLuminance } from './utils';

// Helper to create a mask buffer based on luminance threshold (MVP segmentation)
export const createLuminanceMask = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  threshold: number
): ImageData => {
  const frame = ctx.getImageData(0, 0, width, height);
  const data = frame.data;
  const maskData = new Uint8ClampedArray(data.length);

  // Create mask: 255 = subject (foreground), 0 = background
  // High contrast objects are subject.

  for (let i = 0; i < data.length; i += 4) {
    const lum = getLuminance(data[i], data[i + 1], data[i + 2]);
    const threshVal = threshold * 255;

    // Simple luminance keying
    const isSubject = lum > threshVal;

    const alpha = isSubject ? 255 : 0;

    maskData[i] = alpha;     // R
    maskData[i + 1] = alpha; // G
    maskData[i + 2] = alpha; // B
    maskData[i + 3] = 255;   // A
  }

  return new ImageData(maskData, width, height);
};

// === EFFECT RENDERERS ===

const drawPixel = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any
) => {
  const size = Math.max(1, params.pixelSize);
  const w = Math.ceil(width / size);
  const h = Math.ceil(height / size);

  // 1. Draw scaled down
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = w;
  tempCanvas.height = h;
  const tempCtx = tempCanvas.getContext('2d');
  if (!tempCtx) return;

  tempCtx.imageSmoothingEnabled = false;
  tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

  // 2. Draw back scaled up
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(tempCanvas, 0, 0, width, height);
  ctx.imageSmoothingEnabled = true;
};

const drawHalftone = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any,
  color: string
) => {
  const dotSize = Math.max(2, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;

  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = color;

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (y * width + x) * 4;
      if (i < data.length) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const lum = getLuminance(r, g, b) / 255;

        const radius = (dotSize / 2) * lum;

        ctx.beginPath();
        ctx.arc(x + dotSize/2, y + dotSize/2, radius, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
};

const drawMatrix = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    params: any,
    color: string,
    time: number
) => {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = color;
    ctx.font = `${params.fontSize}px monospace`;

    const cols = Math.floor(width / params.fontSize);

    for (let i = 0; i < cols; i++) {
        const speed = params.fallSpeed * 10;
        const offset = (i * 123.45) % height; 
        const y = (time * speed + offset) % height;

        const charIndex = Math.floor((time + i) % 36);
        const char = charIndex.toString(36); 

        if (Math.random() > (1 - params.density/100)) {
            ctx.fillText(char, i * params.fontSize, y);
        }
    }
}

// Particle system state cache for Plexus to maintain continuity
const plexusParticles: {x: number, y: number, vx: number, vy: number}[] = [];

const drawPlexus = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any,
  color: string,
  maskData: ImageData | null,
  sourceData: Uint8ClampedArray
) => {
  // Init or Resize particles
  const count = params.pointCount;

  // Helper to find a valid position on the mask (if mask exists)
  const getSpawnPos = () => {
    // Try to find a spot on the mask (subject)
    if (maskData) {
        for(let k=0; k<20; k++) { // limit retries for performance
            const rx = Math.random() * width;
            const ry = Math.random() * height;
            // Safe index calculation
            const lx = Math.floor(rx);
            const ly = Math.floor(ry);
            const idx = (ly * width + lx) * 4;

            // maskData R channel is 255 for subject
            if (idx >= 0 && idx < maskData.data.length && maskData.data[idx] > 128) {
                return { x: rx, y: ry };
            }
        }
    }
    // Fallback: random anywhere
    return { x: Math.random() * width, y: Math.random() * height };
  };

  if (plexusParticles.length !== count) {
     plexusParticles.length = 0;
     for(let i=0; i<count; i++) {
        const pos = getSpawnPos();
        plexusParticles.push({
            x: pos.x,
            y: pos.y,
            vx: (Math.random() - 0.5) * params.speed,
            vy: (Math.random() - 0.5) * params.speed
        });
     }
  }

  const rgb = hexToRgb(color);
  const linkDistSq = params.linkDistance * params.linkDistance;

  // Draw on top (no clear rect)
  ctx.lineWidth = params.lineWidth;

  // Update and Draw
  for(let i=0; i<count; i++) {
      const p = plexusParticles[i];
      p.x += p.vx * params.speed;
      p.y += p.vy * params.speed;

      // Behavior: Subject Tracking
      // If we have a mask, and the particle leaves the mask area, respawn it inside.
      if (maskData) {
          const lx = Math.floor(Math.max(0, Math.min(width - 1, p.x)));
          const ly = Math.floor(Math.max(0, Math.min(height - 1, p.y)));
          const idx = (ly * width + lx) * 4;

          const outOfBounds = p.x < 0 || p.x >= width || p.y < 0 || p.y >= height;

          if (outOfBounds || (idx < maskData.data.length && maskData.data[idx] < 128)) {
              // Respawn
              const newPos = getSpawnPos();
              p.x = newPos.x;
              p.y = newPos.y;
              p.vx = (Math.random() - 0.5) * params.speed;
              p.vy = (Math.random() - 0.5) * params.speed;
          }
      } else {
          // Standard bounce if no mask
          // Fix: Ensure particle stays within new bounds if resized
          if (p.x < 0) { p.x = 0; p.vx *= -1; }
          if (p.x > width) { p.x = width; p.vx *= -1; }
          if (p.y < 0) { p.y = 0; p.vy *= -1; }
          if (p.y > height) { p.y = height; p.vy *= -1; }
      }

      // Calculate Depth-based Size (Luminance)
      let radius = params.pointSize || 3;
      const lx = Math.floor(Math.max(0, Math.min(width - 1, p.x)));
      const ly = Math.floor(Math.max(0, Math.min(height - 1, p.y)));
      const pIdx = (ly * width + lx) * 4;

      if (pIdx >= 0 && pIdx < sourceData.length) {
          const lum = getLuminance(sourceData[pIdx], sourceData[pIdx+1], sourceData[pIdx+2]);
          // Expanded dynamic range: 0.3x to 1.8x based on brightness
          // Dark areas = small points, Bright areas = large points
          const depthScale = 0.3 + (lum / 255) * 1.5; 
          radius = radius * depthScale;
      }

      // Draw Connections
      for(let j=i+1; j<count; j++) {
          const p2 = plexusParticles[j];
          const dx = p.x - p2.x;
          const dy = p.y - p2.y;
          const distSq = dx*dx + dy*dy;

          if (distSq < linkDistSq) {
              const alpha = 1 - (distSq / linkDistSq);
              ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
              ctx.beginPath();
              ctx.moveTo(p.x, p.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.stroke();
          }
      }

      ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 1)`;
      ctx.beginPath();
      ctx.arc(p.x, p.y, Math.max(0.5, radius), 0, Math.PI * 2);
      ctx.fill();
  }
};

const drawLine = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    params: any,
    color: string
) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    ctx.clearRect(0, 0, width, height);
    ctx.strokeStyle = color;
    ctx.lineWidth = params.strokeWidth;
    ctx.beginPath();

    const threshold = params.threshold;

    for (let y = 0; y < height; y+=2) {
        for (let x = 0; x < width - 1; x+=2) {
            const i = (y * width + x) * 4;
            const iNext = (y * width + (x+1)) * 4;

            if (iNext < data.length) {
                const lum1 = getLuminance(data[i], data[i+1], data[i+2]);
                const lum2 = getLuminance(data[iNext], data[iNext+1], data[iNext+2]);

                if (Math.abs(lum1 - lum2) > threshold) {
                    ctx.moveTo(x, y);
                    ctx.lineTo(x+2, y+2); 
                }
            }
        }
    }
    ctx.stroke();
}


// === MAIN RENDER PIPELINE ===

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  source: HTMLImageElement | HTMLVideoElement,
  effectId: EffectId,
  params: any,
  global: GlobalParams,
  time: number
) => {
  const width = ctx.canvas.width;
  const height = ctx.canvas.height;

  // 1. Draw Source to Canvas (Reset)
  ctx.globalCompositeOperation = 'source-over';
  ctx.drawImage(source, 0, 0, width, height);

  // 2. Generate/Update Mask
  let maskData: ImageData | null = null;
  if (global.applyTo !== 'both' || effectId === 'plexus') {
     maskData = createLuminanceMask(ctx, width, height, global.maskThreshold);
  }

  // 3. Pre-Effect Filters (B/W, XRAY)
  const rawImage = ctx.getImageData(0, 0, width, height);
  const rawData = rawImage.data;

  if (global.bw || global.xray) {
      for(let i=0; i < rawData.length; i+=4) {
          let r = rawData[i];
          let g = rawData[i+1];
          let b = rawData[i+2];

          if (global.bw) {
              const lum = getLuminance(r, g, b);
              r = g = b = lum;
          }

          if (global.xray) {
              r = 255 - r;
              g = 255 - g;
              b = 255 - b;
              r = (r - 128) * 2 + 128;
              g = (g - 128) * 2 + 128;
              b = (b - 128) * 2 + 128;
          }

          rawData[i] = Math.min(255, Math.max(0, r));
          rawData[i+1] = Math.min(255, Math.max(0, g));
          rawData[i+2] = Math.min(255, Math.max(0, b));
      }
      ctx.putImageData(rawImage, 0, 0);
  }

  const processedSourceData = rawData; 

  // 4. Apply Effect
  const bgCanvas = document.createElement('canvas');
  bgCanvas.width = width;
  bgCanvas.height = height;
  bgCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

  switch (effectId) {
    case 'pixel':
      drawPixel(ctx, width, height, params);
      break;
    case 'halftone':
      drawHalftone(ctx, width, height, params, global.effectColor);
      break;
    case 'plexus':
       ctx.drawImage(bgCanvas, 0, 0); 
       drawPlexus(ctx, width, height, params, global.effectColor, maskData, processedSourceData);
       break;
    case 'matrix':
       drawMatrix(ctx, width, height, params, global.effectColor, time);
       break;
    case 'line':
       drawLine(ctx, width, height, params, global.effectColor);
       break;
  }

  // Step C: Composite (Masking)
  if (global.applyTo !== 'both' && maskData) {
      const effectCanvas = document.createElement('canvas');
      effectCanvas.width = width;
      effectCanvas.height = height;
      effectCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

      ctx.clearRect(0, 0, width, height);

      const baseLayer = global.applyTo === 'subject' ? bgCanvas : effectCanvas;
      const topLayer = global.applyTo === 'subject' ? effectCanvas : bgCanvas;

      ctx.drawImage(baseLayer, 0, 0);

      const scratchCtx = document.createElement('canvas');
      scratchCtx.width = width;
      scratchCtx.height = height;
      const sCtx = scratchCtx.getContext('2d');
      if (sCtx) {
          sCtx.drawImage(topLayer, 0, 0);
          const topData = sCtx.getImageData(0, 0, width, height);
          const tData = topData.data;
          const mData = maskData.data;

          for(let i=3; i<tData.length; i+=4) {
              let maskVal = mData[i-3];
              const alphaFactor = maskVal > 128 ? global.maskStrength : 0;
              tData[i] = tData[i] * alphaFactor; 
          }
          sCtx.putImageData(topData, 0, 0);
          ctx.drawImage(scratchCtx, 0, 0);
      }
  }
};

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import CanvasRenderer from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import EffectSelector from './components/EffectSelector';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  // Handle Upload
  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  // Handle Export
  const handleExport = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = `visual-parameter-${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  // Handle Effect Selection
  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;

    if (globalParams.mixMode) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);

        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);

        if (Math.random() > 0.7) setGlobalParams(p => ({ ...p, bw: !p.bw }));
        if (Math.random() > 0.8) setGlobalParams(p => ({ ...p, xray: !p.xray }));
      };

      mix();
      interval = setInterval(mix, 2000);
    }

    return () => clearInterval(interval);
  }, [globalParams.mixMode]);

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      {/* Background / Main Content (Split Screen) */}
      <div className="absolute inset-0 z-0">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
        />
      </div>

      {/* Top Overlay: Title & Actions */}
      <div className="absolute top-0 left-0 w-full z-20 pointer-events-none">
        <Header 
          onUpload={handleUpload} 
          onExport={handleExport}
          isVideo={isVideo}
        />
      </div>

      {/* Left Overlay: Effect Menu */}
      <div className="absolute left-4 top-1/2 transform -translate-y-1/2 z-20 pointer-events-auto">
        <EffectSelector 
          activeEffectId={activeEffect.id}
          onSelect={handleEffectSelect}
        />
      </div>

      {/* Bottom Overlay: Controls */}
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-4xl z-20 px-4 pointer-events-auto">
        <ControlPanel 
          globalParams={globalParams}
          setGlobalParams={setGlobalParams}
          activeEffect={activeEffect}
          effectParams={effectParams}
          setEffectParams={setEffectParams}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Independent refs for Source display and Canvas processing
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);

  // Ref to hold the actual source object used by renderEngine (can be same as display or offscreen)
  // For split view, we use the visible source elements directly

  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const [dimensions, setDimensions] = useState({ w: 800, h: 600 });
  const [mediaLoaded, setMediaLoaded] = useState(false);

  // Handle Resize of the Canvas side
  // In split view, we want the canvas to fit the Right Half.
  // But actually, for 1:1 pixel mapping, usually we want canvas resolution = source resolution,
  // and CSS scales it down.
  // For this app, let's keep the canvas internal resolution matching the container size for crisp rendering,
  // or match source resolution. Matching source is better for effects like Pixel art.

  // Let's make the canvas match the Display Size of the Right Panel.

  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        // The container is the Right Panel in the split view
        const { clientWidth, clientHeight } = containerRef.current;

        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && sourceVideoRef.current) {
                 srcW = sourceVideoRef.current.videoWidth;
                 srcH = sourceVideoRef.current.videoHeight;
             } else if (sourceImageRef.current) {
                 srcW = sourceImageRef.current.naturalWidth;
                 srcH = sourceImageRef.current.naturalHeight;
             }

             // Maintain aspect ratio inside the right panel
             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 setDimensions({ w: srcW * scale, h: srcH * scale });
                 return;
             }
        }
        setDimensions({ w: clientWidth, h: clientHeight });
      }
    };

    window.addEventListener('resize', handleResize);
    // Slight delay to allow flexbox to settle
    setTimeout(handleResize, 100);
    return () => window.removeEventListener('resize', handleResize);
  }, [mediaSrc, isVideo, mediaLoaded]);

  // Load Media
  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;

      // We rely on the DOM elements (img/video) firing onload events naturally
      // But for the state tracking `mediaLoaded`, we attach listeners here or inline
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      window.dispatchEvent(new Event('resize'));
  };

  // Render Loop
  const animate = (time: number) => {
    if (canvasRef.current && mediaLoaded) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      // Use the visible elements as source
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded]);

  return (
    <div className="flex w-full h-full bg-zinc-950">

      {/* Left: Input Source */}
      <div className="flex-1 border-r border-zinc-800 bg-black/50 flex items-center justify-center relative overflow-hidden">
        <span className="absolute top-4 left-4 text-[10px] font-bold text-zinc-500 tracking-widest bg-black/80 px-2 py-1 rounded border border-zinc-800 z-10">SOURCE</span>

        {!mediaSrc && (
          <div className="text-zinc-600 text-center px-4">
             <p className="text-sm font-medium">No Input</p>
          </div>
        )}

        {mediaSrc && isVideo && (
            <video 
                ref={sourceVideoRef}
                src={mediaSrc}
                className="max-w-full max-h-full object-contain"
                muted 
                loop 
                playsInline 
                autoPlay
                crossOrigin="anonymous"
                onLoadedMetadata={handleMediaLoad}
            />
        )}

        {mediaSrc && !isVideo && (
            <img 
                ref={sourceImageRef}
                src={mediaSrc}
                alt="Source"
                className="max-w-full max-h-full object-contain"
                onLoad={handleMediaLoad}
            />
        )}
      </div>

      {/* Right: Output Canvas */}
      <div className="flex-1 bg-black flex items-center justify-center relative overflow-hidden">
        <span className="absolute top-4 left-4 text-[10px] font-bold text-indigo-500 tracking-widest bg-black/80 px-2 py-1 rounded border border-indigo-900/30 z-10">PROCESSED</span>

        {/* Container for canvas sizing */}
        <div ref={containerRef} className="w-full h-full flex items-center justify-center">
            <canvas
                ref={canvasRef}
                width={dimensions.w}
                height={dimensions.h}
                className="shadow-2xl shadow-black max-w-full max-h-full"
                style={{ imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto' }}
            />
        </div>
      </div>

    </div>
  );
};

export default CanvasRenderer;

