import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import CanvasRenderer from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import EffectSelector from './components/EffectSelector';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  // Handle Upload
  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  // Handle Export
  const handleExport = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = `visual-parameter-${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  // Handle Effect Selection
  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;

    if (globalParams.mixMode) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);

        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);

        if (Math.random() > 0.7) setGlobalParams(p => ({ ...p, bw: !p.bw }));
        if (Math.random() > 0.8) setGlobalParams(p => ({ ...p, xray: !p.xray }));
      };

      mix();
      interval = setInterval(mix, 2000);
    }

    return () => clearInterval(interval);
  }, [globalParams.mixMode]);

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden font-sans">
      {/* Background / Main Content (Split Screen) */}
      <div className="absolute inset-0 z-0">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
        />
      </div>

      {/* Top Overlay: Title & Actions */}
      <div className="absolute top-0 left-0 w-full z-20 pointer-events-none">
        <Header 
          onUpload={handleUpload} 
          onExport={handleExport}
          isVideo={isVideo}
        />
      </div>

      {/* Left Overlay: Effect Menu */}
      <div className="absolute left-4 top-1/2 transform -translate-y-1/2 z-20 pointer-events-auto">
        <EffectSelector 
          activeEffectId={activeEffect.id}
          onSelect={handleEffectSelect}
        />
      </div>

      {/* Bottom Overlay: Controls - Wide Layout */}
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-[95%] max-w-7xl z-20 px-4 pointer-events-auto">
        <ControlPanel 
          globalParams={globalParams}
          setGlobalParams={setGlobalParams}
          activeEffect={activeEffect}
          effectParams={effectParams}
          setEffectParams={setEffectParams}
        />
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { UploadCloud } from 'lucide-react';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);

  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const [dimensions, setDimensions] = useState({ w: 800, h: 600 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  // Resize Handler
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const { clientWidth, clientHeight } = containerRef.current;

        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && sourceVideoRef.current) {
                 srcW = sourceVideoRef.current.videoWidth;
                 srcH = sourceVideoRef.current.videoHeight;
             } else if (sourceImageRef.current) {
                 srcW = sourceImageRef.current.naturalWidth;
                 srcH = sourceImageRef.current.naturalHeight;
             }

             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 setDimensions({ w: srcW * scale, h: srcH * scale });
                 return;
             }
        }
        setDimensions({ w: clientWidth, h: clientHeight });
      }
    };

    window.addEventListener('resize', handleResize);
    setTimeout(handleResize, 100);
    return () => window.removeEventListener('resize', handleResize);
  }, [mediaSrc, isVideo, mediaLoaded]);

  // Load Media
  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      window.dispatchEvent(new Event('resize'));
  };

  // Drag & Drop Handlers
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/') || file.type.startsWith('video/')) {
        onUpload(file);
      }
    }
  };

  // Render Loop
  const animate = (time: number) => {
    if (canvasRef.current && mediaLoaded) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded]);

  return (
    <div className="flex w-full h-full bg-zinc-950">

      {/* Left: Input Source with Drag & Drop */}
      <div 
        className={`flex-1 border-r border-zinc-800 flex items-center justify-center relative overflow-hidden transition-colors duration-300 ${
          isDragging ? 'bg-indigo-900/30 border-indigo-500 border-2 border-dashed' : 'bg-black/50'
        }`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        {!mediaSrc && (
          <div className="text-zinc-500 text-center px-4 flex flex-col items-center gap-4 pointer-events-none">
             <div className="p-4 rounded-full bg-zinc-900/80 border border-zinc-800">
                <UploadCloud size={32} className="text-zinc-400" />
             </div>
             <div className="space-y-1">
                <p className="text-sm font-semibold text-zinc-300">Drag & Drop Media</p>
                <p className="text-xs text-zinc-500">Supports PNG, JPG, MP4</p>
             </div>
          </div>
        )}

        {mediaSrc && isVideo && (
            <video 
                ref={sourceVideoRef}
                src={mediaSrc}
                className="max-w-full max-h-full object-contain pointer-events-none"
                muted 
                loop 
                playsInline 
                autoPlay
                crossOrigin="anonymous"
                onLoadedMetadata={handleMediaLoad}
            />
        )}

        {mediaSrc && !isVideo && (
            <img 
                ref={sourceImageRef}
                src={mediaSrc}
                alt="Source"
                className="max-w-full max-h-full object-contain pointer-events-none"
                onLoad={handleMediaLoad}
            />
        )}

        {/* Drag Overlay Hint */}
        {isDragging && mediaSrc && (
             <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-20 pointer-events-none">
                 <p className="text-white font-bold text-lg">Drop to Replace</p>
             </div>
        )}
      </div>

      {/* Right: Output Canvas */}
      <div className="flex-1 bg-black flex items-center justify-center relative overflow-hidden">
        <div ref={containerRef} className="w-full h-full flex items-center justify-center">
            <canvas
                ref={canvasRef}
                width={dimensions.w}
                height={dimensions.h}
                className="shadow-2xl shadow-black max-w-full max-h-full"
                style={{ imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto' }}
            />
        </div>
      </div>

    </div>
  );
};

export default CanvasRenderer;

