                                    onChange={(e) => updateEffect(key, parseFloat(e.target.value))}
                                    className="absolute w-full h-1.5 bg-zinc-800 rounded-full appearance-none cursor-pointer accent-indigo-500 hover:accent-indigo-400 transition-all z-10 opacity-0 hover:opacity-100"
                                />
                                {/* Custom Track Style */}
                                <div className="absolute inset-0 rounded-full bg-zinc-800 overflow-hidden pointer-events-none">
                                    <div 
                                        className="h-full bg-indigo-900/50 group-hover:bg-indigo-600/30 transition-all" 
                                        style={{ width: `${((effectParams[key] - (config.min || 0)) / ((config.max || 100) - (config.min || 0))) * 100}%` }}
                                    />
                                </div>
                                <div 
                                    className="absolute top-0 h-1.5 w-1.5 bg-indigo-500 rounded-full shadow-[0_0_10px_rgba(99,102,241,0.8)] pointer-events-none transition-all"
                                    style={{ left: `calc(${((effectParams[key] - (config.min || 0)) / ((config.max || 100) - (config.min || 0))) * 100}% - 3px)` }}
                                />
                            </div>
                        </div>
                    )
                }
                return null;
            })}
        </div>
      </div>

    </div>
  );
};

