export default ControlPanel;

import { EffectId, GlobalParams } from '../types';
import { hexToRgb, getLuminance } from './utils';

// Helper to create a mask buffer based on luminance threshold (MVP segmentation)
export const createLuminanceMask = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  threshold: number
): ImageData => {
  const frame = ctx.getImageData(0, 0, width, height);
  const data = frame.data;
  const maskData = new Uint8ClampedArray(data.length);

  // Create mask: 255 = subject (foreground), 0 = background
  // High contrast objects are subject.

  for (let i = 0; i < data.length; i += 4) {
    const lum = getLuminance(data[i], data[i + 1], data[i + 2]);
    const threshVal = threshold * 255;

    // Simple luminance keying
    const isSubject = lum > threshVal;

    const alpha = isSubject ? 255 : 0;

    maskData[i] = alpha;     // R
    maskData[i + 1] = alpha; // G
    maskData[i + 2] = alpha; // B
    maskData[i + 3] = 255;   // A
  }

  return new ImageData(maskData, width, height);
};

// === EFFECT RENDERERS ===

const drawPixel = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any
) => {
  const size = Math.max(1, params.pixelSize);
  const w = Math.ceil(width / size);
  const h = Math.ceil(height / size);

  // 1. Draw scaled down
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = w;
  tempCanvas.height = h;
  const tempCtx = tempCanvas.getContext('2d');
  if (!tempCtx) return;

  tempCtx.imageSmoothingEnabled = false;
  tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

  // 2. Draw back scaled up
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(tempCanvas, 0, 0, width, height);
  ctx.imageSmoothingEnabled = true;
};

const drawHalftone = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any,
  color: string
) => {
  const dotSize = Math.max(2, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;

  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = color;

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (y * width + x) * 4;
      if (i < data.length) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const lum = getLuminance(r, g, b) / 255;

        const radius = (dotSize / 2) * lum;

        ctx.beginPath();
        ctx.arc(x + dotSize/2, y + dotSize/2, radius, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
};

const drawMatrix = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    params: any,
    color: string,
    time: number
) => {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = color;
    ctx.font = `${params.fontSize}px monospace`;

    const cols = Math.floor(width / params.fontSize);

    for (let i = 0; i < cols; i++) {
        const speed = params.fallSpeed * 10;
        const offset = (i * 123.45) % height; 
        const y = (time * speed + offset) % height;

        const charIndex = Math.floor((time + i) % 36);
        const char = charIndex.toString(36); 

        if (Math.random() > (1 - params.density/100)) {
            ctx.fillText(char, i * params.fontSize, y);
        }
    }
}

// Particle system state cache for Plexus to maintain continuity
const plexusParticles: {
    x: number, 
    y: number, 
    vx: number, 
    vy: number,
    sizeOffset: number // 0 to 1 random factor for size variance
}[] = [];

const drawPlexus = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: any,
  color: string,
  maskData: ImageData | null,
  sourceData: Uint8ClampedArray
) => {
  // Init or Resize particles
  const count = params.pointCount;

  // Helper to find a valid position Strictly inside the mask
  const getSpawnPos = () => {
    if (maskData) {
        // Try up to 50 times to find a valid spot on the subject
        for(let k=0; k<50; k++) { 
            const rx = Math.random() * width;
            const ry = Math.random() * height;

            const lx = Math.floor(rx);
            const ly = Math.floor(ry);
            const idx = (ly * width + lx) * 4;

            // maskData R channel is 255 for subject. Strictly > 128.
            if (idx >= 0 && idx < maskData.data.length && maskData.data[idx] > 128) {
                return { x: rx, y: ry };
            }
        }
        // If failed to find mask (e.g. empty mask), hide particle
        return { x: -100, y: -100 };
    }
    // Fallback: random anywhere if no mask logic is active
    return { x: Math.random() * width, y: Math.random() * height };
  };

  if (plexusParticles.length !== count) {
     plexusParticles.length = 0;
     for(let i=0; i<count; i++) {
        const pos = getSpawnPos();
        plexusParticles.push({
            x: pos.x,
            y: pos.y,
            vx: (Math.random() - 0.5) * params.speed,
            vy: (Math.random() - 0.5) * params.speed,
            sizeOffset: Math.random() // Unique size factor
        });
     }
  }

  const rgb = hexToRgb(color);
  const linkDistSq = params.linkDistance * params.linkDistance;

  // Draw on top (no clear rect)
  ctx.lineWidth = params.lineWidth;

  // Font for numbers
  if (params.showNumbers) {
      ctx.font = '9px monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
  }

  // Update and Draw
  for(let i=0; i<count; i++) {
      const p = plexusParticles[i];

      // If particle is "hidden" (offscreen), try to respawn it
      if (p.x === -100 && p.y === -100) {
          const newPos = getSpawnPos();
          p.x = newPos.x;
          p.y = newPos.y;
          // If still hidden, skip
          if (p.x === -100) continue;
      }

      p.x += p.vx * params.speed;
      p.y += p.vy * params.speed;

      // Strict Containment Check
      let isValid = true;
      if (maskData) {
          const lx = Math.floor(p.x);
          const ly = Math.floor(p.y);
          const idx = (ly * width + lx) * 4;

          const outOfBounds = p.x < 0 || p.x >= width || p.y < 0 || p.y >= height;

          // If outside canvas OR outside Subject Mask
          if (outOfBounds || (idx < maskData.data.length && maskData.data[idx] < 128)) {
              isValid = false;
          }
      } else {
          // Standard bounds
          if (p.x < 0 || p.x > width) { p.vx *= -1; p.x = Math.max(0, Math.min(width, p.x)); }
          if (p.y < 0 || p.y > height) { p.vy *= -1; p.y = Math.max(0, Math.min(height, p.y)); }
      }

      if (!isValid) {
          // Respawn immediately
          const newPos = getSpawnPos();
          p.x = newPos.x;
          p.y = newPos.y;
          p.vx = (Math.random() - 0.5) * params.speed;
          p.vy = (Math.random() - 0.5) * params.speed;

          // If respawn failed (no mask), keep hidden
          if (p.x === -100) continue;
      }

      // Calculate Depth/Size
      let radius = params.pointSize || 3;

      // 1. Depth scaling from luminance
      const lx = Math.floor(Math.max(0, Math.min(width - 1, p.x)));
      const ly = Math.floor(Math.max(0, Math.min(height - 1, p.y)));
      const pIdx = (ly * width + lx) * 4;

      if (pIdx >= 0 && pIdx < sourceData.length) {
          const lum = getLuminance(sourceData[pIdx], sourceData[pIdx+1], sourceData[pIdx+2]);
          const depthScale = 0.3 + (lum / 255) * 1.5; 
          radius = radius * depthScale;
      }

      // 2. Apply Random Variance
      if (params.sizeVariance > 0) {
          const varianceMult = 1 + (p.sizeOffset - 0.5) * 2 * params.sizeVariance;
          radius = radius * Math.max(0.1, varianceMult);
      }

      // Draw Connections (Only if both points are valid, implied by loop)
      for(let j=i+1; j<count; j++) {
          const p2 = plexusParticles[j];
          if (p2.x === -100) continue; // skip hidden

          const dx = p.x - p2.x;
          const dy = p.y - p2.y;
          const distSq = dx*dx + dy*dy;

          if (distSq < linkDistSq) {
              const alpha = 1 - (distSq / linkDistSq);
              ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
              ctx.beginPath();
              ctx.moveTo(p.x, p.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.stroke();
          }
      }

      ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 1)`;

      if (params.showNumbers) {
          ctx.beginPath();
          ctx.arc(p.x, p.y, Math.max(0.5, radius), 0, Math.PI * 2);
          ctx.fill();

          // Render Number with FX Color (uses current fillStyle)
          ctx.fillText(i.toString(), p.x + radius + 4, p.y - radius - 2);
      } else {
          ctx.beginPath();
          ctx.arc(p.x, p.y, Math.max(0.5, radius), 0, Math.PI * 2);
          ctx.fill();
      }
  }
};

const drawLine = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    params: any,
    color: string
) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    ctx.clearRect(0, 0, width, height);
    ctx.strokeStyle = color;
    ctx.lineWidth = params.strokeWidth;
    ctx.beginPath();

    const threshold = params.threshold;

    for (let y = 0; y < height; y+=2) {
        for (let x = 0; x < width - 1; x+=2) {
            const i = (y * width + x) * 4;
            const iNext = (y * width + (x+1)) * 4;

            if (iNext < data.length) {
                const lum1 = getLuminance(data[i], data[i+1], data[i+2]);
                const lum2 = getLuminance(data[iNext], data[iNext+1], data[iNext+2]);

                if (Math.abs(lum1 - lum2) > threshold) {
                    ctx.moveTo(x, y);
                    ctx.lineTo(x+2, y+2); 
                }
            }
        }
    }
    ctx.stroke();
}


// === MAIN RENDER PIPELINE ===

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  source: HTMLImageElement | HTMLVideoElement,
  effectId: EffectId,
  params: any,
  global: GlobalParams,
  time: number
) => {
  const width = ctx.canvas.width;
  const height = ctx.canvas.height;

  // 1. Draw Source to Canvas (Reset)
  ctx.globalCompositeOperation = 'source-over';
  ctx.drawImage(source, 0, 0, width, height);

  // 2. Generate/Update Mask
  // Plexus NOW requires mask regardless of applyTo mode to enforce "Subject Internal Only" logic
  let maskData: ImageData | null = null;
  maskData = createLuminanceMask(ctx, width, height, global.maskThreshold);

  // 3. Pre-Effect Filters (B/W, XRAY)
  const rawImage = ctx.getImageData(0, 0, width, height);
  const rawData = rawImage.data;

  if (global.bw || global.xray) {
      for(let i=0; i < rawData.length; i+=4) {
          let r = rawData[i];
          let g = rawData[i+1];
          let b = rawData[i+2];

          if (global.bw) {
              const lum = getLuminance(r, g, b);
              r = g = b = lum;
          }

          if (global.xray) {
              r = 255 - r;
              g = 255 - g;
              b = 255 - b;
              r = (r - 128) * 2 + 128;
              g = (g - 128) * 2 + 128;
              b = (b - 128) * 2 + 128;
          }

          rawData[i] = Math.min(255, Math.max(0, r));
          rawData[i+1] = Math.min(255, Math.max(0, g));
          rawData[i+2] = Math.min(255, Math.max(0, b));
      }
      ctx.putImageData(rawImage, 0, 0);
  }

  const processedSourceData = rawData; 

  // 4. Apply Effect
  const bgCanvas = document.createElement('canvas');
  bgCanvas.width = width;
  bgCanvas.height = height;
  bgCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

  switch (effectId) {
    case 'pixel':
      drawPixel(ctx, width, height, params);
      break;
    case 'halftone':
      drawHalftone(ctx, width, height, params, global.effectColor);
      break;
    case 'plexus':
       ctx.drawImage(bgCanvas, 0, 0); 
       // Pass maskData to drawPlexus for strict containment
       drawPlexus(ctx, width, height, params, global.effectColor, maskData, processedSourceData);
       break;
    case 'matrix':
       drawMatrix(ctx, width, height, params, global.effectColor, time);
       break;
    case 'line':
       drawLine(ctx, width, height, params, global.effectColor);
       break;
  }

  // Step C: Composite (Masking)
  // Logic: For Plexus, we might want to respect applyTo, but the dots are already constrained. 
  // If ApplyTo is 'Subject', standard composite works.
  // If ApplyTo is 'Background', dots on subject are masked OUT? 
  // Let's stick to standard composite logic. 

  if (global.applyTo !== 'both' && maskData) {
      const effectCanvas = document.createElement('canvas');
      effectCanvas.width = width;
      effectCanvas.height = height;
      effectCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

      ctx.clearRect(0, 0, width, height);

      const baseLayer = global.applyTo === 'subject' ? bgCanvas : effectCanvas;
      const topLayer = global.applyTo === 'subject' ? effectCanvas : bgCanvas;

      ctx.drawImage(baseLayer, 0, 0);

      const scratchCtx = document.createElement('canvas');
      scratchCtx.width = width;
      scratchCtx.height = height;
      const sCtx = scratchCtx.getContext('2d');
      if (sCtx) {
          sCtx.drawImage(topLayer, 0, 0);
          const topData = sCtx.getImageData(0, 0, width, height);
          const tData = topData.data;
          const mData = maskData.data;

          for(let i=3; i<tData.length; i+=4) {
              let maskVal = mData[i-3];
              const alphaFactor = maskVal > 128 ? global.maskStrength : 0;
              tData[i] = tData[i] * alphaFactor; 
          }
          sCtx.putImageData(topData, 0, 0);
          ctx.drawImage(scratchCtx, 0, 0);
      }
  }
};

