import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { UploadCloud } from 'lucide-react';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onCanvasResize?: (width: number, height: number) => void;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onCanvasResize
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);

  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  // Initial Dimension Set & Resize Handler
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        // Use a safe margin for the canvas (e.g. 32px on sides/top/bottom)
        // Note: Header is top overlay, ControlPanel is bottom overlay. 
        // We let the canvas take available space, but maybe add some padding.
        const paddingX = 48; // 24px each side
        const paddingY = 160; // Space for Header and Footer

        const clientWidth = containerRef.current.clientWidth - paddingX;
        const clientHeight = containerRef.current.clientHeight - paddingY;

        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && sourceVideoRef.current) {
                 srcW = sourceVideoRef.current.videoWidth;
                 srcH = sourceVideoRef.current.videoHeight;
             } else if (sourceImageRef.current) {
                 srcW = sourceImageRef.current.naturalWidth;
                 srcH = sourceImageRef.current.naturalHeight;
             }

             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 const finalW = srcW * scale;
                 const finalH = srcH * scale;
                 setDimensions({ w: finalW, h: finalH });
                 return;
             }
        }
        // Fallback for empty state or loading
        setDimensions({ w: Math.min(800, clientWidth), h: Math.min(600, clientHeight) });
      }
    };

    window.addEventListener('resize', handleResize);
    // Delay slightly to ensure container is ready
    const timer = setTimeout(handleResize, 50);
    return () => {
        window.removeEventListener('resize', handleResize);
        clearTimeout(timer);
    };
  }, [mediaSrc, isVideo, mediaLoaded]);

  // Notify parent of resize
  useEffect(() => {
    if (onCanvasResize && dimensions.w > 0) {
        onCanvasResize(dimensions.w, dimensions.h);
    }
  }, [dimensions, onCanvasResize]);

  // Load Media Reset
  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      // Trigger resize calc once media is ready
      window.dispatchEvent(new Event('resize'));
  };

  // Drag & Drop Handlers
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/') || file.type.startsWith('video/')) {
        onUpload(file);
      }
    }
  };

  // Render Loop
  const animate = (time: number) => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions]);

  return (
    <div 
      ref={containerRef}
      className="w-full h-full bg-zinc-950 relative flex items-center justify-center overflow-hidden"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* Source Elements (Hidden but Active) */}
      {mediaSrc && isVideo && (
            <video 
                ref={sourceVideoRef}
                src={mediaSrc}
                className="hidden"
                muted 
                loop 
                playsInline 
                autoPlay
                crossOrigin="anonymous"
                onLoadedMetadata={handleMediaLoad}
            />
      )}

