      <div className="absolute top-0 left-0 w-full z-20 pointer-events-none">
        <Header 
          onUpload={handleUpload} 
          onExport={handleExport}
          isVideo={isVideo}
        />
      </div>

      {/* Bottom Unified HUD (ControlPanel) - Synced with Canvas Width */}
      <div 
        className="absolute bottom-6 z-30 pointer-events-auto flex justify-center transition-all duration-300 ease-out"
        style={{ 
            width: canvasDimensions ? canvasDimensions.w : '600px',
            maxWidth: '94vw' 
        }}
      >
        <ControlPanel 
          globalParams={globalParams}
          setGlobalParams={setGlobalParams}
          activeEffect={activeEffect}
          effectParams={effectParams}
          setEffectParams={setEffectParams}
          allEffects={EFFECTS}
          onSelectEffect={handleEffectSelect}
