import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { UploadCloud } from 'lucide-react';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onCanvasResize?: (width: number, height: number) => void;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onCanvasResize
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);

  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  // Initial Dimension Set & Resize Handler
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        // Calculate available space in the container
        // We add some padding for aesthetics
        const padding = 32; 

        const clientWidth = containerRef.current.clientWidth - padding;
        const clientHeight = containerRef.current.clientHeight - padding;

        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && sourceVideoRef.current) {
                 srcW = sourceVideoRef.current.videoWidth;
                 srcH = sourceVideoRef.current.videoHeight;
             } else if (sourceImageRef.current) {
                 srcW = sourceImageRef.current.naturalWidth;
                 srcH = sourceImageRef.current.naturalHeight;
             }

             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 const finalW = srcW * scale;
                 const finalH = srcH * scale;
                 setDimensions({ w: finalW, h: finalH });
                 return;
             }
        }
        // Fallback for empty state or loading (center placeholder)
        setDimensions({ w: Math.min(600, clientWidth), h: Math.min(400, clientHeight) });
      }
    };

    window.addEventListener('resize', handleResize);
    // Delay slightly to ensure container is ready
    const timer = setTimeout(handleResize, 50);
    return () => {
        window.removeEventListener('resize', handleResize);
        clearTimeout(timer);
    };
  }, [mediaSrc, isVideo, mediaLoaded]);

  // Notify parent of resize
  useEffect(() => {
    if (onCanvasResize && dimensions.w > 0) {
        onCanvasResize(dimensions.w, dimensions.h);
    }
  }, [dimensions, onCanvasResize]);

  // Load Media Reset
  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      // Trigger resize calc once media is ready
      window.dispatchEvent(new Event('resize'));
  };

  // Drag & Drop Handlers
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/') || file.type.startsWith('video/')) {
        onUpload(file);
      }
    }
  };

  // Render Loop
  const animate = (time: number) => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions]);

  return (
    <div 
      ref={containerRef}
      className="w-full h-full relative flex items-center justify-center overflow-hidden"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* Source Elements (Hidden but Active) */}
      {mediaSrc && isVideo && (
            <video 
                ref={sourceVideoRef}
                src={mediaSrc}
                className="hidden"
                muted 
                loop 
                playsInline 
                autoPlay
                crossOrigin="anonymous"
                onLoadedMetadata={handleMediaLoad}
            />
      )}

      {mediaSrc && !isVideo && (
            <img 
                ref={sourceImageRef}
                src={mediaSrc}
                alt="Source"
                className="hidden"
                onLoad={handleMediaLoad}
            />
      )}

      {/* Empty State / Drag Overlay */}
      {(!mediaSrc || isDragging) && (
          <div className={`absolute inset-0 z-20 flex items-center justify-center transition-all duration-300 ${isDragging ? 'bg-black/80 backdrop-blur-sm' : 'bg-transparent pointer-events-none'}`}>
             <div className={`p-8 rounded-3xl border-2 border-dashed flex flex-col items-center gap-4 transition-all ${isDragging ? 'border-indigo-500 bg-indigo-500/10 scale-105' : 'border-zinc-800 bg-zinc-900/50'}`}>
                <div className="p-4 rounded-full bg-zinc-800">
                    <UploadCloud size={32} className={isDragging ? 'text-indigo-400' : 'text-zinc-500'} />
                </div>
                <div className="text-center">
                    <p className={`text-sm font-bold ${isDragging ? 'text-indigo-300' : 'text-zinc-300'}`}>
                        {isDragging ? 'Drop to Upload' : 'Drag & Drop Media'}
                    </p>
                    {!isDragging && <p className="text-xs text-zinc-500 mt-1">PNG, JPG, MP4</p>}
                </div>
             </div>
          </div>
      )}

      {/* Output Canvas */}
      <canvas
        ref={canvasRef}
        width={dimensions.w}
        height={dimensions.h}
        className="shadow-2xl shadow-black max-w-full max-h-full transition-opacity duration-500"
        style={{ 
            imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto',
            opacity: mediaLoaded ? 1 : 0 
        }}
      />
    </div>
  );
};

