import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import CanvasRenderer from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  // Canvas dimensions are now only used internally by renderer, 
  // removed from app state driving control panel width.

  // Handle Upload
  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  // Handle Export
  const handleExport = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = `visual-parameter-${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  // Handle Effect Selection
  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;

    if (globalParams.mixMode) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);

        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);

        if (Math.random() > 0.7) setGlobalParams(p => ({ ...p, bw: !p.bw }));
        if (Math.random() > 0.8) setGlobalParams(p => ({ ...p, xray: !p.xray }));
      };

      mix();
      interval = setInterval(mix, 2000);
    }

    return () => clearInterval(interval);
  }, [globalParams.mixMode]);

  return (
    <div className="flex flex-col h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">

      {/* 1. Top Header Area */}
      <div className="shrink-0 z-20 bg-white/90 backdrop-blur-sm border-b border-zinc-200">
        <Header 
          onUpload={handleUpload} 
          onExport={handleExport}
          isVideo={isVideo}
        />
      </div>

      {/* 2. Main Canvas Area (Flex Grow) */}
      <div className="flex-1 relative flex items-center justify-center bg-zinc-50 overflow-hidden">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          // Removed resize handler prop as we don't sync width anymore
        />
      </div>

      {/* 3. Bottom Controls Area */}
      <div className="shrink-0 z-30 bg-white border-t border-zinc-200 p-6 flex justify-center w-full">
         <div className="w-full transition-all duration-300 ease-out">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { UploadCloud, Loader2 } from 'lucide-react';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onCanvasResize?: (width: number, height: number) => void;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onCanvasResize
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());

  const [dimensions, setDimensions] = useState({ w: 800, h: 600 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);

  // Initialize MediaPipe Segmenter
  useEffect(() => {
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks(
          "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
        );
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true,
          outputConfidenceMasks: false
        });
        segmenterRef.current = segmenter;
        setAiReady(true);
      } catch (err) {
        console.error("MediaPipe Init Error:", err);
      }
    }
    initAI();
  }, [isVideo]);

  // Resize Handler
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const padding = 48; 
        const clientWidth = containerRef.current.clientWidth - padding;
        const clientHeight = containerRef.current.clientHeight - padding;

        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && sourceVideoRef.current) {
                 srcW = sourceVideoRef.current.videoWidth;
                 srcH = sourceVideoRef.current.videoHeight;
             } else if (sourceImageRef.current) {
                 srcW = sourceImageRef.current.naturalWidth;
                 srcH = sourceImageRef.current.naturalHeight;
             }

             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 const finalW = srcW * scale;
                 const finalH = srcH * scale;
                 setDimensions({ w: finalW, h: finalH });
                 return;
             }
        }
        setDimensions({ w: Math.min(600, clientWidth), h: Math.min(400, clientHeight) });
      }
    };

    window.addEventListener('resize', handleResize);
    const timer = setTimeout(handleResize, 50);
    return () => {
        window.removeEventListener('resize', handleResize);
        clearTimeout(timer);
    };
  }, [mediaSrc, isVideo, mediaLoaded]);

  useEffect(() => {
    if (onCanvasResize && dimensions.w > 0) {
        onCanvasResize(dimensions.w, dimensions.h);
    }
  }, [dimensions, onCanvasResize]);

  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      window.dispatchEvent(new Event('resize'));
  };

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;

          // 1. Get AI Mask from Segmenter
          let aiMaskImageData: ImageData | null = null;
          try {
            const result = isVideo 
              ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now())
              : segmenterRef.current.segment(source as HTMLImageElement);

            if (result && result.categoryMask) {
               // The mask contains values where 255 is subject (usually)
               const maskData = result.categoryMask.getAsUint8Array();
               const maskWidth = result.categoryMask.width;
               const maskHeight = result.categoryMask.height;

               // Create standard RGBA ImageData from category mask (single channel)
               const rgbaData = new Uint8ClampedArray(maskWidth * maskHeight * 4);
               for (let i = 0; i < maskData.length; i++) {
                  const val = maskData[i] > 0 ? 255 : 0; // Binary mask
                  rgbaData[i * 4] = val;     // R
                  rgbaData[i * 4 + 1] = val; // G
                  rgbaData[i * 4 + 2] = val; // B
                  rgbaData[i * 4 + 3] = 255; // A
               }
               aiMaskImageData = new ImageData(rgbaData, maskWidth, maskHeight);
            }
          } catch (e) {
            console.warn("Segmentation failed this frame", e);
          }

          // 2. Render frame with AI Mask
          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed,
            aiMaskImageData // Pass the AI mask to engine
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  // Drag & Drop
  const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/') || file.type.startsWith('video/')) onUpload(file);
    }
  };

  return (
    <div className="flex w-full h-full bg-zinc-50">
      <div 
        className={`flex-1 border-r border-zinc-200 flex items-center justify-center relative overflow-hidden transition-colors duration-300 ${
          isDragging ? 'bg-indigo-50 border-indigo-300 border-2 border-dashed' : 'bg-zinc-100'
        }`}
        onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
      >
        {!mediaSrc && (
          <div className="text-zinc-500 text-center px-4 flex flex-col items-center gap-4 pointer-events-none">
             <div className="p-4 rounded-full bg-white border border-zinc-200 shadow-sm">
                <UploadCloud size={32} className="text-zinc-400" />
             </div>
             <div className="space-y-1">
                <p className="text-sm font-semibold text-zinc-600">Drag & Drop Media</p>
                <p className="text-xs text-zinc-400">Supports PNG, JPG, MP4</p>
             </div>
          </div>
        )}

        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="max-w-[90%] max-h-[90%] object-contain pointer-events-none shadow-lg rounded-lg" muted loop playsInline autoPlay crossOrigin="anonymous" onLoadedMetadata={handleMediaLoad} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} alt="Source" className="max-w-[90%] max-h-[90%] object-contain pointer-events-none shadow-lg rounded-lg" onLoad={handleMediaLoad} />
        )}

        {!aiReady && mediaSrc && (
           <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-3 py-1.5 rounded-full border border-zinc-200 flex items-center gap-2 text-[10px] font-bold text-zinc-600">
               <Loader2 size={12} className="animate-spin" />
               <span>LOADING AI MODEL...</span>
           </div>
        )}
      </div>

      <div className="flex-1 bg-zinc-50 flex items-center justify-center relative overflow-hidden">
        <div ref={containerRef} className="w-full h-full flex items-center justify-center">
            <canvas
                ref={canvasRef}
                width={dimensions.w}
                height={dimensions.h}
                className="shadow-2xl shadow-zinc-300 max-w-full max-h-full bg-white transition-opacity duration-500"
                style={{ imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto', opacity: mediaLoaded ? 1 : 0 }}
            />
        </div>
      </div>
    </div>
  );
};

export default CanvasRenderer;

import { EffectId, GlobalParams } from '../types';
import { hexToRgb, getLuminance } from './utils';

// Helper to create a fallback mask buffer if AI mask is not available
export const createLuminanceMask = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  threshold: number
): ImageData => {
  const frame = ctx.getImageData(0, 0, width, height);
  const data = frame.data;
  const maskData = new Uint8ClampedArray(data.length);

  for (let i = 0; i < data.length; i += 4) {
    const lum = getLuminance(data[i], data[i + 1], data[i + 2]);
    const threshVal = threshold * 255;
    const isSubject = lum > threshVal;
    const alpha = isSubject ? 255 : 0;
    maskData[i] = maskData[i + 1] = maskData[i + 2] = alpha;
    maskData[i + 3] = 255;
  }
  return new ImageData(maskData, width, height);
};

const getSaturation = (r: number, g: number, b: number) => {
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    if (max === 0) return 0;
    return (max - min) / max;
};

// === EFFECT RENDERERS ===

const drawPixel = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any) => {
  const size = Math.max(1, params.pixelSize);
  const w = Math.ceil(width / size);
  const h = Math.ceil(height / size);
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = w;
  tempCanvas.height = h;
  const tempCtx = tempCanvas.getContext('2d');
  if (!tempCtx) return;
  tempCtx.imageSmoothingEnabled = false;
  tempCtx.drawImage(ctx.canvas, 0, 0, w, h);
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(tempCanvas, 0, 0, width, height);
  ctx.imageSmoothingEnabled = true;
};

const drawHalftone = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, color: string) => {
  const dotSize = Math.max(2, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = color;
  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (Math.floor(y) * width + Math.floor(x)) * 4;
      if (i < data.length) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const lum = getLuminance(r, g, b) / 255;
        const radius = (dotSize / 2) * lum;
        ctx.beginPath();
        ctx.arc(x + dotSize/2, y + dotSize/2, radius, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
};

const drawMatrix = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, color: string, time: number) => {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = color;
    ctx.font = `${params.fontSize}px monospace`;
    const cols = Math.floor(width / params.fontSize);
    for (let i = 0; i < cols; i++) {
        const speed = params.fallSpeed * 10;
        const offset = (i * 123.45) % height; 
        const y = (time * speed + offset) % height;
        const char = Math.floor((time + i) % 36).toString(36); 
        if (Math.random() > (1 - params.density/100)) ctx.fillText(char, i * params.fontSize, y);
    }
}

const plexusParticles: {x: number, y: number, vx: number, vy: number, sizeOffset: number, noiseOffset: number}[] = [];

const drawPlexus = (
  ctx: CanvasRenderingContext2D, width: number, height: number, params: any, 
  color: string, maskData: ImageData | null, sourceData: Uint8ClampedArray, time: number
) => {
  const count = params.pointCount;
  const getSpawnPos = () => {
    if (maskData) {
        for(let k=0; k<50; k++) { 
            const rx = Math.random() * width;
            const ry = Math.random() * height;
            // AI masks are often scaled, we need to map RX/RY back to mask space
            const mx = Math.floor((rx / width) * maskData.width);
            const my = Math.floor((ry / height) * maskData.height);
            const idx = (my * maskData.width + mx) * 4;
            if (idx >= 0 && idx < maskData.data.length && maskData.data[idx] > 128) {
                return { x: rx, y: ry };
            }
        }
        return { x: -100, y: -100 };
    }
    return { x: Math.random() * width, y: Math.random() * height };
  };

  if (plexusParticles.length !== count) {
     plexusParticles.length = 0;
     for(let i=0; i<count; i++) {
        const pos = getSpawnPos();
        plexusParticles.push({
            x: pos.x, y: pos.y,
            vx: (Math.random() - 0.5) * params.speed,
            vy: (Math.random() - 0.5) * params.speed,
            sizeOffset: Math.random(), noiseOffset: Math.random() * 100
        });
     }
  }

  const rgb = hexToRgb(color);
  const linkDistSq = params.linkDistance * params.linkDistance;
  const jitterStrength = params.jitter || 0;
  ctx.lineWidth = params.lineWidth;

  if (params.showNumbers) {
      ctx.font = '9px monospace'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  }

  for(let i=0; i<count; i++) {
      const p = plexusParticles[i];
      if (p.x === -100) {
          const pos = getSpawnPos();
          p.x = pos.x; p.y = pos.y;
          if (p.x === -100) continue;
      }

      p.x += p.vx * params.speed;
      p.y += p.vy * params.speed;
      const renderX = p.x + Math.sin(time * 3 + p.noiseOffset) * jitterStrength;
      const renderY = p.y + Math.cos(time * 4 + p.noiseOffset) * jitterStrength;

      let isValid = true;
      if (maskData) {
          const mx = Math.floor((p.x / width) * maskData.width);
          const my = Math.floor((p.y / height) * maskData.height);
          const idx = (my * maskData.width + mx) * 4;
          if (p.x < 0 || p.x >= width || p.y < 0 || p.y >= height || (idx >= 0 && idx < maskData.data.length && maskData.data[idx] < 128)) {
              isValid = false;
          }
      } else {
          if (p.x < 0 || p.x > width) { p.vx *= -1; p.x = Math.max(0, Math.min(width, p.x)); }
          if (p.y < 0 || p.y > height) { p.vy *= -1; p.y = Math.max(0, Math.min(height, p.y)); }
      }

      if (!isValid) {
          const newPos = getSpawnPos();
          p.x = newPos.x; p.y = newPos.y;
          p.vx = (Math.random() - 0.5) * params.speed; p.vy = (Math.random() - 0.5) * params.speed;
          if (p.x === -100) continue;
      }

      let radius = params.pointSize || 3;
      const sx = Math.floor(Math.max(0, Math.min(width - 1, renderX)));
      const sy = Math.floor(Math.max(0, Math.min(height - 1, renderY)));
      const pIdx = (sy * width + sx) * 4;
      if (pIdx >= 0 && pIdx < sourceData.length) radius *= (0.3 + (getLuminance(sourceData[pIdx], sourceData[pIdx+1], sourceData[pIdx+2]) / 255) * 1.5);
      if (params.sizeVariance > 0) radius *= (1 + (p.sizeOffset - 0.5) * 2 * params.sizeVariance);

      for(let j=i+1; j<count; j++) {
          const p2 = plexusParticles[j];
          if (p2.x === -100) continue;
          const rX2 = p2.x + Math.sin(time * 3 + p2.noiseOffset) * jitterStrength;
          const rY2 = p2.y + Math.cos(time * 4 + p2.noiseOffset) * jitterStrength;
          const dx = renderX - rX2; const dy = renderY - rY2;
          const distSq = dx*dx + dy*dy;
          if (distSq < linkDistSq) {
              const alpha = 1 - (distSq / linkDistSq);
              ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
              ctx.beginPath(); ctx.moveTo(renderX, renderY); ctx.lineTo(rX2, rY2); ctx.stroke();
          }
      }

      ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 1)`;
      ctx.beginPath(); ctx.arc(renderX, renderY, Math.max(0.5, radius), 0, Math.PI * 2); ctx.fill();
      if (params.showNumbers) ctx.fillText(i.toString(), renderX + radius + 4, renderY - radius - 2);
  }
};

const drawLine = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, color: string) => {
    const data = ctx.getImageData(0, 0, width, height).data;
    ctx.clearRect(0, 0, width, height);
    ctx.strokeStyle = color; ctx.lineWidth = params.strokeWidth;
    ctx.beginPath();
    for (let y = 0; y < height; y+=2) {
        for (let x = 0; x < width - 1; x+=2) {
            const i = (y * width + x) * 4;
            const iNext = (y * width + (x+1)) * 4;
            if (iNext < data.length) {
                if (Math.abs(getLuminance(data[i], data[i+1], data[i+2]) - getLuminance(data[iNext], data[iNext+1], data[iNext+2])) > params.threshold) {
                    ctx.moveTo(x, y); ctx.lineTo(x+2, y+2); 
                }
            }
        }
    }
    ctx.stroke();
}

// === MAIN RENDER PIPELINE ===

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  source: HTMLImageElement | HTMLVideoElement,
  effectId: EffectId,
  params: any,
  global: GlobalParams,
  time: number,
  aiMask?: ImageData | null // New parameter for AI-generated mask
) => {
  const width = ctx.canvas.width;
  const height = ctx.canvas.height;

  // 1. Draw Source to Canvas
  ctx.globalCompositeOperation = 'source-over';
  ctx.drawImage(source, 0, 0, width, height);

  // 2. Prepare Mask (Prefer AI mask, fallback to luminance)
  let activeMask: ImageData | null = null;
  if (aiMask) {
    activeMask = aiMask;
  } else {
    activeMask = createLuminanceMask(ctx, width, height, global.maskThreshold);
  }

  // 3. Pre-Effect Filters
  const rawImage = ctx.getImageData(0, 0, width, height);
  const rawData = rawImage.data;
  if (global.bw || global.xray) {
      for(let i=0; i < rawData.length; i+=4) {
          let r = rawData[i], g = rawData[i+1], b = rawData[i+2];
          if (global.bw) { const lum = getLuminance(r, g, b); r = g = b = lum; }
          if (global.xray) { r = 255 - r; g = 255 - g; b = 255 - b; r = (r - 128) * 2 + 128; g = (g - 128) * 2 + 128; b = (b - 128) * 2 + 128; }
          rawData[i] = Math.min(255, Math.max(0, r)); rawData[i+1] = Math.min(255, Math.max(0, g)); rawData[i+2] = Math.min(255, Math.max(0, b));
      }
      ctx.putImageData(rawImage, 0, 0);
  }

  const processedSourceData = rawData; 

  // 4. Apply Effect
  const bgCanvas = document.createElement('canvas');
  bgCanvas.width = width; bgCanvas.height = height;
  bgCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);

  switch (effectId) {
    case 'pixel': drawPixel(ctx, width, height, params); break;
    case 'halftone': drawHalftone(ctx, width, height, params, global.effectColor); break;
    case 'plexus': ctx.drawImage(bgCanvas, 0, 0); drawPlexus(ctx, width, height, params, global.effectColor, activeMask, processedSourceData, time); break;
    case 'matrix': drawMatrix(ctx, width, height, params, global.effectColor, time); break;
    case 'line': drawLine(ctx, width, height, params, global.effectColor); break;
  }

  // 5. Composite (AI Masking)
  if (global.applyTo !== 'both' && activeMask) {
      const effectCanvas = document.createElement('canvas');
      effectCanvas.width = width; effectCanvas.height = height;
      effectCanvas.getContext('2d')?.drawImage(ctx.canvas, 0, 0);
      ctx.clearRect(0, 0, width, height);

      const baseLayer = global.applyTo === 'subject' ? bgCanvas : effectCanvas;
      const topLayer = global.applyTo === 'subject' ? effectCanvas : bgCanvas;
      ctx.drawImage(baseLayer, 0, 0);

      const scratchCanvas = document.createElement('canvas');
      scratchCanvas.width = width; scratchCanvas.height = height;
      const sCtx = scratchCanvas.getContext('2d');
      if (sCtx) {
          sCtx.drawImage(topLayer, 0, 0);
          const topData = sCtx.getImageData(0, 0, width, height);
          const tData = topData.data;

          for(let y=0; y<height; y++) {
            for(let x=0; x<width; x++) {
              const i = (y * width + x) * 4;
              const mx = Math.floor((x / width) * activeMask.width);
              const my = Math.floor((y / height) * activeMask.height);
              const mIdx = (my * activeMask.width + mx) * 4;

              const maskVal = activeMask.data[mIdx];
              const alphaFactor = maskVal > 128 ? global.maskStrength : 0;
              tData[i + 3] = tData[i + 3] * alphaFactor; 
            }
          }
          sCtx.putImageData(topData, 0, 0);
          ctx.drawImage(scratchCanvas, 0, 0);
      }
  }
};

import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { UploadCloud, Loader2 } from 'lucide-react';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onCanvasResize?: (width: number, height: number) => void;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onCanvasResize
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());

  const [dimensions, setDimensions] = useState({ w: 800, h: 600 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);

  // Initialize MediaPipe Segmenter
  useEffect(() => {
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks(
          "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
        );
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true,
          outputConfidenceMasks: false
        });
        segmenterRef.current = segmenter;
        setAiReady(true);
      } catch (err) {
        console.error("MediaPipe Init Error:", err);
      }
    }
    initAI();

    return () => {
      if (segmenterRef.current) {
        segmenterRef.current.close();
        segmenterRef.current = null;
      }
    };
  }, [isVideo]);

  // Resize Handler
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const padding = 48; 
        const clientWidth = containerRef.current.clientWidth - padding;
        const clientHeight = containerRef.current.clientHeight - padding;

        if (mediaLoaded) {
             let srcW = 0, srcH = 0;
             if (isVideo && sourceVideoRef.current) {
                 srcW = sourceVideoRef.current.videoWidth;
                 srcH = sourceVideoRef.current.videoHeight;
             } else if (sourceImageRef.current) {
                 srcW = sourceImageRef.current.naturalWidth;
                 srcH = sourceImageRef.current.naturalHeight;
             }

             if (srcW > 0 && srcH > 0) {
                 const scale = Math.min(clientWidth / srcW, clientHeight / srcH);
                 const finalW = srcW * scale;
                 const finalH = srcH * scale;
                 setDimensions({ w: finalW, h: finalH });
                 return;
             }
        }
        setDimensions({ w: Math.min(600, clientWidth), h: Math.min(400, clientHeight) });
      }
    };

    window.addEventListener('resize', handleResize);
    const timer = setTimeout(handleResize, 50);
    return () => {
        window.removeEventListener('resize', handleResize);
        clearTimeout(timer);
    };
  }, [mediaSrc, isVideo, mediaLoaded]);

  useEffect(() => {
    if (onCanvasResize && dimensions.w > 0) {
        onCanvasResize(dimensions.w, dimensions.h);
    }
  }, [dimensions, onCanvasResize]);

  useEffect(() => {
      setMediaLoaded(false);
      if (!mediaSrc) return;
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      window.dispatchEvent(new Event('resize'));
  };

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;

          // 1. Get AI Mask from Segmenter
          let aiMaskImageData: ImageData | null = null;
          try {
            const result = isVideo 
              ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now())
              : segmenterRef.current.segment(source as HTMLImageElement);

            if (result && result.categoryMask) {
               // The mask contains values where 255 is subject (usually)
               const maskData = result.categoryMask.getAsUint8Array();
               const maskWidth = result.categoryMask.width;
               const maskHeight = result.categoryMask.height;

               // Create standard RGBA ImageData from category mask (single channel)
               const rgbaData = new Uint8ClampedArray(maskWidth * maskHeight * 4);
               for (let i = 0; i < maskData.length; i++) {
                  const val = maskData[i] > 0 ? 255 : 0; // Binary mask
                  rgbaData[i * 4] = val;     // R
                  rgbaData[i * 4 + 1] = val; // G
                  rgbaData[i * 4 + 2] = val; // B
                  rgbaData[i * 4 + 3] = 255; // A
               }
               aiMaskImageData = new ImageData(rgbaData, maskWidth, maskHeight);

               // CRITICAL: Close mask instance to prevent memory leaks
               result.categoryMask.close();
               if (result.confidenceMasks) {
                 result.confidenceMasks.forEach(m => m.close());
               }
            }
          } catch (e) {
            console.warn("Segmentation failed this frame", e);
          }

          // 2. Render frame with AI Mask
          renderFrame(
            ctx,
            source,
            activeEffect.id,
            effectParams,
            globalParams,
            elapsed,
            aiMaskImageData // Pass the AI mask to engine
          );
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  // Drag & Drop
  const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/') || file.type.startsWith('video/')) onUpload(file);
    }
  };

  return (
    <div className="flex w-full h-full bg-zinc-50">
      <div 
        className={`flex-1 border-r border-zinc-200 flex items-center justify-center relative overflow-hidden transition-colors duration-300 ${
          isDragging ? 'bg-indigo-50 border-indigo-300 border-2 border-dashed' : 'bg-zinc-100'
        }`}
        onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
      >
        {!mediaSrc && (
          <div className="text-zinc-500 text-center px-4 flex flex-col items-center gap-4 pointer-events-none">
             <div className="p-4 rounded-full bg-white border border-zinc-200 shadow-sm">
                <UploadCloud size={32} className="text-zinc-400" />
             </div>
             <div className="space-y-1">
                <p className="text-sm font-semibold text-zinc-600">Drag & Drop Media</p>
                <p className="text-xs text-zinc-400">Supports PNG, JPG, MP4</p>
             </div>
          </div>
        )}

        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="max-w-[90%] max-h-[90%] object-contain pointer-events-none shadow-lg rounded-lg" muted loop playsInline autoPlay crossOrigin="anonymous" onLoadedMetadata={handleMediaLoad} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} alt="Source" className="max-w-[90%] max-h-[90%] object-contain pointer-events-none shadow-lg rounded-lg" onLoad={handleMediaLoad} />
        )}

        {!aiReady && mediaSrc && (
           <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-3 py-1.5 rounded-full border border-zinc-200 flex items-center gap-2 text-[10px] font-bold text-zinc-600">
               <Loader2 size={12} className="animate-spin" />
               <span>LOADING AI MODEL...</span>
           </div>
        )}
      </div>

      <div className="flex-1 bg-zinc-50 flex items-center justify-center relative overflow-hidden">
        <div ref={containerRef} className="w-full h-full flex items-center justify-center">
            <canvas
                ref={canvasRef}
                width={dimensions.w}
                height={dimensions.h}
                className="shadow-2xl shadow-zinc-300 max-w-full max-h-full bg-white transition-opacity duration-500"
                style={{ imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto', opacity: mediaLoaded ? 1 : 0 }}
            />
        </div>
      </div>
    </div>
  );
};

export default CanvasRenderer;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import CanvasRenderer from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  // Handle Upload
  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  // Handle Export
  const handleExport = () => {
    const canvas = document.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = `visual-parameter-${Date.now()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  // Handle Effect Selection
  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;

    if (globalParams.mixMode) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);

        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);

        if (Math.random() > 0.7) setGlobalParams(p => ({ ...p, bw: !p.bw }));
        if (Math.random() > 0.8) setGlobalParams(p => ({ ...p, xray: !p.xray }));
      };

      mix();
      interval = setInterval(mix, 2000);
    }

    return () => clearInterval(interval);
  }, [globalParams.mixMode]);

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">

      {/* Floating Header */}
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header 
          onUpload={handleUpload} 
          onExport={handleExport}
          isVideo={isVideo}
        />
      </div>

      {/* Main Split Content Area - Fills entire screen */}
      <main className="w-full h-full">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
        />
      </main>

      {/* Floating Bottom Controls */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-7xl pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

export default App;

