      try {
        const vision = await FilesetResolver.forVisionTasks(
          "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
        );
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true,
          outputConfidenceMasks: false
        });
        segmenterRef.current = segmenter;
        setAiReady(true);
      } catch (err) {
        console.error("MediaPipe Init Error:", err);
      }
    }
    initAI();

    return () => {
      if (segmenterRef.current) {
        segmenterRef.current.close();
        segmenterRef.current = null;
      }
    };
  }, [isVideo]);

  // Unified Resize Handler for Split View
  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;

      // Each pane takes half the width
      const paneWidth = window.innerWidth / 2;
      const paneHeight = window.innerHeight;

      // Padding for aesthetic fit
      const padding = 80;
      const maxW = paneWidth - padding;
      const maxH = paneHeight - padding;

      if (mediaLoaded) {
          let srcW = 0, srcH = 0;
          if (isVideo && sourceVideoRef.current) {
              srcW = sourceVideoRef.current.videoWidth;
              srcH = sourceVideoRef.current.videoHeight;
          } else if (sourceImageRef.current) {
              srcW = sourceImageRef.current.naturalWidth;
              srcH = sourceImageRef.current.naturalHeight;
          }

          if (srcW > 0 && srcH > 0) {
              const scale = Math.min(maxW / srcW, maxH / srcH);
              setDimensions({ w: srcW * scale, h: srcH * scale });
              return;
          }
      }

      // Default placeholder dimensions
      setDimensions({ w: 400, h: 300 });
    };

    window.addEventListener('resize', handleResize);
    handleResize(); // Initial
    return () => window.removeEventListener('resize', handleResize);
  }, [mediaSrc, isVideo, mediaLoaded]);

  useEffect(() => {
    if (onCanvasResize && dimensions.w > 0) {
        onCanvasResize(dimensions.w, dimensions.h);
    }
  }, [dimensions, onCanvasResize]);

  useEffect(() => {
      setMediaLoaded(false);
  }, [mediaSrc]);

  const handleMediaLoad = () => {
      setMediaLoaded(true);
      // Small delay to ensure browser layout update
      setTimeout(() => window.dispatchEvent(new Event('resize')), 50);
  };

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          let aiMaskImageData: ImageData | null = null;

          try {
            const result = isVideo 
              ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now())
              : segmenterRef.current.segment(source as HTMLImageElement);

            if (result && result.categoryMask) {
               const maskData = result.categoryMask.getAsUint8Array();
               const maskWidth = result.categoryMask.width;
               const maskHeight = result.categoryMask.height;
               const rgbaData = new Uint8ClampedArray(maskWidth * maskHeight * 4);
               for (let i = 0; i < maskData.length; i++) {
                  const val = maskData[i] > 0 ? 255 : 0;
                  rgbaData[i * 4] = val; rgbaData[i * 4 + 1] = val; rgbaData[i * 4 + 2] = val; rgbaData[i * 4 + 3] = 255;
               }
               aiMaskImageData = new ImageData(rgbaData, maskWidth, maskHeight);
               result.categoryMask.close();
               if (result.confidenceMasks) result.confidenceMasks.forEach(m => m.close());
            }
          } catch (e) { /* silent fail */ }

          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, aiMaskImageData);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  // Drag & Drop
  const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/') || file.type.startsWith('video/')) onUpload(file);
    }
  };

  return (
    <div className="flex w-full h-full bg-zinc-100" ref={containerRef}>

      {/* Left Pane: Source Input */}
      <div 
        className={`relative flex-1 flex items-center justify-center transition-colors duration-500 overflow-hidden ${
          isDragging ? 'bg-zinc-200' : 'bg-white'
        }`}
        onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-6 pointer-events-none">
             <div className="p-8 rounded-[2.5rem] bg-zinc-50 border border-zinc-200 shadow-2xl shadow-zinc-200/50">
                <UploadCloud size={48} className="text-zinc-300" />
             </div>
             <div className="text-center">
                <p className="text-sm font-bold text-zinc-800 uppercase tracking-widest">Source Module</p>
                <p className="text-[10px] text-zinc-400 mt-2">Drop media to initialize</p>
             </div>
          </div>
        )}

        {mediaSrc && isVideo && (
            <video 
                ref={sourceVideoRef} 
                src={mediaSrc} 
                className="object-contain shadow-2xl rounded-2xl bg-black" 
                style={{ width: dimensions.w, height: dimensions.h }}
                muted loop playsInline autoPlay crossOrigin="anonymous" onLoadedMetadata={handleMediaLoad} 
            />
        )}
        {mediaSrc && !isVideo && (
            <img 
                ref={sourceImageRef} 
                src={mediaSrc} 
                className="object-contain shadow-2xl rounded-2xl bg-white" 
                style={{ width: dimensions.w, height: dimensions.h }}
                onLoad={handleMediaLoad} 
            />
        )}

        {/* Input Label Overlay */}
        {mediaSrc && (
            <div className="absolute top-12 left-12 bg-white/50 backdrop-blur-md border border-zinc-200/50 px-4 py-1.5 rounded-full text-[9px] font-black text-zinc-500 uppercase tracking-widest">
                Raw Input
            </div>
        )}
      </div>

      {/* Right Pane: Effect Output */}
      <div className="relative flex-1 flex items-center justify-center bg-zinc-50 overflow-hidden">
        {/* Decorative Grid Background */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#000 1px, transparent 0)', backgroundSize: '24px 24px' }} />

        <canvas
            ref={canvasRef}
            width={dimensions.w}
            height={dimensions.h}
            className={`shadow-2xl shadow-zinc-400/30 transition-all duration-1000 bg-white ${mediaLoaded ? 'scale-100 opacity-100' : 'scale-95 opacity-0'}`}
            style={{ 
                imageRendering: activeEffect.id === 'pixel' ? 'pixelated' : 'auto',
                borderRadius: '1rem'
            }}
        />

        {/* Output Label Overlay */}
        {mediaSrc && (
            <div className="absolute top-12 right-12 bg-zinc-900/10 backdrop-blur-md border border-black/5 px-4 py-1.5 rounded-full text-[9px] font-black text-zinc-800 uppercase tracking-widest flex items-center gap-2">
                <Sparkles size={10} />
                Processed Output
            </div>
        )}

        {/* AI Loading Status */}
        {!aiReady && mediaSrc && (
           <div className="absolute bottom-12 bg-white/90 backdrop-blur-xl px-4 py-2 rounded-2xl border border-zinc-200 shadow-xl flex items-center gap-3 text-[10px] font-bold text-zinc-600">
               <Loader2 size={14} className="animate-spin text-orange-500" />
               <span className="tracking-wide">AI CORE INITIALIZING...</span>
           </div>
        )}
      </div>

    </div>
  );
};

