import React, { useRef, useEffect, useState } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { UploadCloud, Loader2, Sparkles } from 'lucide-react';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onCanvasResize?: (width: number, height: number) => void;
}

const CanvasRenderer: React.FC<CanvasRendererProps> = ({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());

  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) {
            segmenterRef.current = segmenter;
            setAiReady(true);
        } else {
            segmenter.close();
        }
      } catch (err) { 
        // Silent catch to handle WebGL status reports or minor init glitches
        console.debug("System Engine Info:", err); 
      }
    }
    initAI();
    return () => { 
        active = false;
        segmenterRef.current?.close(); 
    };
  }, [isVideo]);

  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;
      setDimensions({ w: window.innerWidth / 2, h: window.innerHeight });
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
      if (ctx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          let aiMask: ImageData | null = null;
          try {
            const result = isVideo 
              ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now())
              : segmenterRef.current.segment(source as HTMLImageElement);
            if (result?.categoryMask) {
               const maskData = result.categoryMask.getAsUint8Array();
               const rgba = new Uint8ClampedArray(result.categoryMask.width * result.categoryMask.height * 4);
               for (let i = 0; i < maskData.length; i++) {
                  const val = maskData[i] > 0 ? 255 : 0;
                  rgba[i*4]=rgba[i*4+1]=rgba[i*4+2]=val; rgba[i*4+3]=255;
               }
               aiMask = new ImageData(rgba, result.categoryMask.width, result.categoryMask.height);
               result.categoryMask.close();
               result.confidenceMasks?.forEach(m => m.close());
            }
          } catch (e) {}
          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, aiMask);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  return (
    <div className="flex w-full h-screen overflow-hidden bg-white shadow-none" ref={containerRef}>
      {/* Left: Raw Input */}
      <div 
        className={`relative w-1/2 h-full flex items-center justify-center transition-opacity duration-700 ${isDragging ? 'opacity-50' : 'opacity-100'} border-r border-zinc-100`}
        onDragOver={(e) => {e.preventDefault(); setIsDragging(true);}}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]);}}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-4 text-zinc-100 pointer-events-none">
             <UploadCloud size={48} strokeWidth={1.5} />
             <span className="text-[9px] font-black uppercase tracking-[0.4em]">Initialize_Input</span>
          </div>
        )}
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="w-full h-full object-cover" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="w-full h-full object-cover" onLoad={() => setMediaLoaded(true)} />
        )}
        <div className="absolute top-10 left-10 bg-white border border-zinc-200 px-4 py-2 rounded-sm text-[8px] font-black text-zinc-900 uppercase tracking-[0.4em] shadow-none">Input</div>
      </div>

      {/* Right: Processed Output */}
      <div className="relative w-1/2 h-full bg-zinc-50 flex items-center justify-center shadow-none">
        <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className={`w-full h-full transition-all duration-1000 ${mediaLoaded ? 'opacity-100' : 'opacity-0'}`} />
        <div className="absolute top-10 right-10 bg-zinc-900 border border-zinc-900 px-4 py-2 rounded-sm text-[8px] font-black text-white uppercase tracking-[0.4em] flex items-center gap-3 shadow-none">
            <Sparkles size={10} className="text-zinc-400" />
            Process_Render
        </div>
        {!aiReady && mediaSrc && (
            <div className="absolute bottom-10 bg-zinc-900 text-white px-6 py-2 rounded-sm text-[9px] font-black tracking-widest flex items-center gap-3 animate-pulse shadow-none">
                <Loader2 size={12} className="animate-spin" /> Neural_Sync_Active
            </div>
        )}
      </div>
    </div>
  );
};

export default CanvasRenderer;

