                      >
                        {f.label}
                      </button>
                    ))}
                </div>
            </div>

            <div className="flex items-center gap-8">
                <div className="flex bg-white/30 rounded-full p-1 border border-white/50">
                    {['subject', 'background', 'both'].map(m => (
                        <button key={m} onClick={() => updateGlobal('applyTo', m)} className={`px-6 py-2 rounded-full text-[8px] font-black uppercase transition-all ${globalParams.applyTo === m ? 'bg-white text-zinc-900 border border-zinc-100' : 'text-zinc-400 hover:text-zinc-500'}`}>{m}</button>
                    ))}
                </div>
                <button 
                  onClick={() => updateGlobal('mixMode', !globalParams.mixMode)} 
                  className={`flex items-center gap-3 px-6 py-2.5 rounded-full text-[9px] font-black uppercase transition-all ${globalParams.mixMode ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white/50 text-zinc-400 border border-zinc-200 hover:bg-white hover:text-zinc-600'}`}
                >
                  <Zap size={14} className={globalParams.mixMode ? 'animate-pulse text-yellow-400 fill-yellow-400' : ''}/>
                  Mix
                </button>
            </div>
      </div>
    </div>
  );
};

