import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const internalCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const lastMaskRef = useRef<ImageData | null>(null);
  const frameCountRef = useRef<number>(0);

  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const trackingOffsetRef = useRef({ x: 0, y: 0, scale: 1.0 });
  const PROC_WIDTH = 800; 

  useImperativeHandle(ref, () => ({
    startExport: async () => {
      if (!canvasRef.current || !mediaSrc) return;

      const canvas = canvasRef.current;
      const chunks: Blob[] = [];
      const stream = canvas.captureStream(60); 

      // Attempt to find a supported video type
      const mimeType = MediaRecorder.isTypeSupported('video/mp4') 
        ? 'video/mp4' 
        : MediaRecorder.isTypeSupported('video/webm;codecs=h264') 
          ? 'video/webm;codecs=h264' 
          : 'video/webm';

      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 8000000 });

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
        a.download = `visual-parameter-render-${Date.now()}.${extension}`;
        a.click();

        setIsExporting(false);
        onExportStateChange?.(false);
        // Reset video state
        if (sourceVideoRef.current) {
          sourceVideoRef.current.muted = true;
          sourceVideoRef.current.play();
        }
      };

      setIsExporting(true);
      onExportStateChange?.(true);

      if (isVideo && sourceVideoRef.current) {
        const video = sourceVideoRef.current;
        video.currentTime = 0;
        video.play();
        recorder.start();

        const handleVideoEnd = () => {
          recorder.stop();
          video.removeEventListener('ended', handleVideoEnd);
        };
        video.addEventListener('ended', handleVideoEnd);
      } else {
        // For images, record a 3 second loop of the generative effect
        recorder.start();
        setTimeout(() => recorder.stop(), 3000);
      }
    }
  }));

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) {
            segmenterRef.current = segmenter;
            setAiReady(true);
        } else {
            segmenter.close();
        }
      } catch (err) {}
    }
    initAI();
    return () => { 
        active = false;
        segmenterRef.current?.close(); 
    };
  }, [isVideo]);

  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;
      setDimensions({ w: Math.floor(window.innerWidth / 2), h: window.innerHeight });
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const displayCtx = canvasRef.current.getContext('2d');
      const internalCanvas = internalCanvasRef.current;

      const scale = PROC_WIDTH / dimensions.w;
      const procW = PROC_WIDTH;
      const procH = Math.floor(dimensions.h * scale);

      if (internalCanvas.width !== procW) {
          internalCanvas.width = procW;
          internalCanvas.height = procH;
      }

      const ctx = internalCanvas.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && displayCtx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          frameCountRef.current++;
          const shouldUpdateMask = !isVideo || (frameCountRef.current % 3 === 0);

          if (shouldUpdateMask || !lastMaskRef.current) {
              try {
                const result = isVideo 
                  ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now())
                  : segmenterRef.current.segment(source as HTMLImageElement);

                if (result?.categoryMask) {
                   const maskData = result.categoryMask.getAsUint8Array();
                   const mw = result.categoryMask.width;
                   const mh = result.categoryMask.height;
                   const rgba = new Uint8ClampedArray(mw * mh * 4);

                   let sumX = 0; let sumY = 0; let count = 0;

                   for (let i = 0; i < maskData.length; i++) {
                      const val = maskData[i] > 0 ? 255 : 0;
                      const idx = i * 4;
                      rgba[idx] = rgba[idx+1] = rgba[idx+2] = val; rgba[idx+3] = 255;

                      if (val > 0) {
                          sumX += i % mw;
                          sumY += Math.floor(i / mw);
                          count++;
                      }
                   }

                   if (count > 100 && globalParams.autoTracking) {
                       const centerX = (sumX / count) / mw;
                       const centerY = (sumY / count) / mh;
                       const targetX = (0.5 - centerX) * procW * 0.5;
                       const targetY = (0.5 - centerY) * procH * 0.5;
                       const areaFraction = count / (mw * mh);
                       const targetScale = 1.1 + Math.max(0, (0.25 - areaFraction) * 1.5);

                       trackingOffsetRef.current.x += (targetX - trackingOffsetRef.current.x) * 0.08;
                       trackingOffsetRef.current.y += (targetY - trackingOffsetRef.current.y) * 0.08;
                       trackingOffsetRef.current.scale += (targetScale - trackingOffsetRef.current.scale) * 0.05;
                   } else if (!globalParams.autoTracking) {
                       trackingOffsetRef.current.x *= 0.9;
                       trackingOffsetRef.current.y *= 0.9;
                       trackingOffsetRef.current.scale += (1.0 - trackingOffsetRef.current.scale) * 0.1;
                   }

                   lastMaskRef.current = new ImageData(rgba, mw, mh);
                   result.categoryMask.close();
                   result.confidenceMasks?.forEach(m => m.close());
                }
              } catch (e) {}
          }

          ctx.save();
          if (globalParams.autoTracking || trackingOffsetRef.current.scale > 1.01) {
            ctx.translate(trackingOffsetRef.current.x, trackingOffsetRef.current.y);
            ctx.translate(procW/2, procH/2);
            ctx.scale(trackingOffsetRef.current.scale, trackingOffsetRef.current.scale);
            ctx.translate(-procW/2, -procH/2);
          }

          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, lastMaskRef.current);
          ctx.restore();

          displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, 0, 0, dimensions.w, dimensions.h);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  return (
    <div className="flex w-full h-screen overflow-hidden bg-white" ref={containerRef}>
      {isExporting && (
        <div className="absolute inset-0 z-[100] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin mb-6"></div>
          <span className="text-[12px] font-black uppercase tracking-[0.5em] animate-pulse">Rendering Video...</span>
          <span className="text-[10px] opacity-60 mt-2 font-bold">Please wait while we process the duration.</span>
        </div>
      )}

      <div 
        className={`relative w-1/2 h-full flex items-center justify-center transition-opacity duration-700 ${isDragging ? 'opacity-50' : 'opacity-100'}`}
        onDragOver={(e) => {e.preventDefault(); setIsDragging(true);}}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]);}}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-4 text-zinc-100 pointer-events-none">
             <span className="text-[9px] font-black uppercase tracking-[0.4em]">Initialize_Input</span>
          </div>
        )}
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="w-full h-full object-cover" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="w-full h-full object-cover" onLoad={() => setMediaLoaded(true)} />
        )}
      </div>

      <div className="relative w-1/2 h-full bg-white flex items-center justify-center">
        <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className={`w-full h-full transition-all duration-1000 ${mediaLoaded ? 'opacity-100' : 'opacity-0'}`} />
      </div>
    </div>
  );
});

