import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);

  // Handle Upload
  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  // Handle Export (Now triggers video render)
  const handleExport = () => {
    if (rendererRef.current) {
      rendererRef.current.startExport();
    }
  };

  // Handle Effect Selection
  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;

    if (globalParams.mixMode) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);

        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);
      };

      mix();
      interval = setInterval(mix, 2500);
    }

    return () => clearInterval(interval);
  }, [globalParams.mixMode]);

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">

      {/* Floating Header */}
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header 
          onUpload={handleUpload} 
          onExport={handleExport}
          isVideo={isVideo}
          isExporting={isExporting}
        />
      </div>

      {/* Main Split Content Area */}
      <main className="w-full h-full">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onExportStateChange={setIsExporting}
        />
      </main>

      {/* Floating Bottom Controls */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-[1440px] pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

