import React, { useState, useEffect, useRef, useMemo } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const syncChannel = useMemo(() => new BroadcastChannel('visual-parameter-sync'), []);

  // Detect ON AIR mode from URL
  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  // Sync state to ON AIR windows
  useEffect(() => {
    if (!isOnAirView) {
      syncChannel.postMessage({
        mediaSrc,
        isVideo,
        globalParams,
        activeEffectId: activeEffect.id,
        effectParams
      });
    }
  }, [mediaSrc, isVideo, globalParams, activeEffect, effectParams, isOnAirView, syncChannel]);

  // Listen for sync in ON AIR window
  useEffect(() => {
    if (isOnAirView) {
      const handleSync = (e: MessageEvent) => {
        const { mediaSrc, isVideo, globalParams, activeEffectId, effectParams } = e.data;
        if (mediaSrc !== undefined) setMediaSrc(mediaSrc);
        if (isVideo !== undefined) setIsVideo(isVideo);
        if (globalParams !== undefined) setGlobalParams(globalParams);
        if (activeEffectId !== undefined) {
          const effect = EFFECTS.find(eff => eff.id === activeEffectId);
          if (effect) setActiveEffect(effect);
        }
        if (effectParams !== undefined) setEffectParams(effectParams);
      };
      syncChannel.onmessage = handleSync;
      return () => { syncChannel.onmessage = null; };
    }
  }, [isOnAirView, syncChannel]);

  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  const handleExport = () => {
    if (rendererRef.current) {
      rendererRef.current.startExport();
    }
  };

  const handleOnAir = () => {
    const url = new URL(window.location.href);
    url.searchParams.set('view', 'onair');
    window.open(url.toString(), 'VisualParameterOnAir', 'width=1280,height=720');
  };

  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (globalParams.mixMode && !isOnAirView) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);
        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);
      };
      mix();
      interval = setInterval(mix, 2500);
    }
    return () => clearInterval(interval);
  }, [globalParams.mixMode, isOnAirView]);

  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black overflow-hidden">
        {/* Patterned Grid View */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 w-full h-full gap-0">
          {[...Array(12)].map((_, i) => (
            <div key={i} className="relative w-full h-full overflow-hidden border border-white/5">
              <CanvasRenderer 
                mediaSrc={mediaSrc} 
                isVideo={isVideo}
                activeEffect={activeEffect}
                effectParams={effectParams}
                globalParams={globalParams}
                onUpload={() => {}} // No upload in OnAir
                isPatternMode={true}
              />
            </div>
          ))}
        </div>
        {!mediaSrc && (
          <div className="absolute inset-0 flex items-center justify-center text-white/20">
            <span className="text-[10px] font-black tracking-[1em] uppercase">Waiting for Source...</span>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header 
          onExport={handleExport}
          onAir={handleOnAir}
          isExporting={isExporting}
        />
      </div>

      <main className="w-full h-full">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onExportStateChange={setIsExporting}
        />
      </main>

      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-[1440px] pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  isPatternMode?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  isPatternMode = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const internalCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const lastMaskRef = useRef<ImageData | null>(null);
  const frameCountRef = useRef<number>(0);

  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [exportEta, setExportEta] = useState(0);

  const trackingOffsetRef = useRef({ x: 0, y: 0, scale: 1.0 });
  const PROC_WIDTH = 800; 

  useImperativeHandle(ref, () => ({
    startExport: async () => {
      if (!canvasRef.current || !mediaSrc) return;
      const canvas = canvasRef.current;
      const chunks: Blob[] = [];
      const stream = canvas.captureStream(60); 
      const mimeTypes = ['video/mp4;codecs=h264', 'video/mp4', 'video/webm;codecs=h264', 'video/webm'];
      const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || 'video/webm';
      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 12000000 });
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
        a.download = `visual-parameter-h264-${Date.now()}.${extension}`;
        a.click();
        setIsExporting(false); setExportProgress(0); setExportEta(0); onExportStateChange?.(false);
        if (sourceVideoRef.current) { sourceVideoRef.current.muted = true; sourceVideoRef.current.play(); }
      };
      setIsExporting(true); onExportStateChange?.(true);
      if (isVideo && sourceVideoRef.current) {
        const video = sourceVideoRef.current;
        video.currentTime = 0; video.play(); recorder.start();
        const progressInterval = setInterval(() => {
          if (!video.duration) return;
          setExportProgress((video.currentTime / video.duration) * 100);
          setExportEta(Math.max(0, video.duration - video.currentTime));
        }, 100);
        const handleVideoEnd = () => { recorder.stop(); clearInterval(progressInterval); video.removeEventListener('ended', handleVideoEnd); };
        video.addEventListener('ended', handleVideoEnd);
      } else {
        const duration = 3; recorder.start(); const start = Date.now();
        const progressInterval = setInterval(() => {
          const elapsed = (Date.now() - start) / 1000;
          setExportProgress((elapsed / duration) * 100);
          setExportEta(Math.max(0, duration - elapsed));
          if (elapsed >= duration) { recorder.stop(); clearInterval(progressInterval); }
        }, 100);
      }
    }
  }));

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) { segmenterRef.current = segmenter; setAiReady(true); } else { segmenter.close(); }
      } catch (err) {}
    }
    initAI();
    return () => { active = false; segmenterRef.current?.close(); };
  }, [isVideo]);

  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;
      const w = isPatternMode ? containerRef.current.clientWidth : Math.floor(window.innerWidth / 2);
      const h = isPatternMode ? containerRef.current.clientHeight : window.innerHeight;
      setDimensions({ w, h });
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, [isPatternMode]);

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const displayCtx = canvasRef.current.getContext('2d');
      const internalCanvas = internalCanvasRef.current;
      const scale = PROC_WIDTH / dimensions.w;
      const procW = PROC_WIDTH;
      const procH = Math.floor(dimensions.h * scale);
      if (internalCanvas.width !== procW) { internalCanvas.width = procW; internalCanvas.height = procH; }
      const ctx = internalCanvas.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
      if (ctx && displayCtx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          frameCountRef.current++;
          const shouldUpdateMask = !isVideo || (frameCountRef.current % 3 === 0);
          if (shouldUpdateMask || !lastMaskRef.current) {
              try {
                const result = isVideo ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now()) : segmenterRef.current.segment(source as HTMLImageElement);
                if (result?.categoryMask) {
                   const maskData = result.categoryMask.getAsUint8Array();
                   const mw = result.categoryMask.width; const mh = result.categoryMask.height;
                   const rgba = new Uint8ClampedArray(mw * mh * 4);
                   let sumX = 0; let sumY = 0; let count = 0;
                   for (let i = 0; i < maskData.length; i++) {
                      const val = maskData[i] > 0 ? 255 : 0; const idx = i * 4;
                      rgba[idx] = rgba[idx+1] = rgba[idx+2] = val; rgba[idx+3] = 255;
                      if (val > 0) { sumX += i % mw; sumY += Math.floor(i / mw); count++; }
                   }
                   if (count > 100 && globalParams.autoTracking) {
                       const centerX = (sumX / count) / mw; const centerY = (sumY / count) / mh;
                       const targetX = (0.5 - centerX) * procW * 0.5; const targetY = (0.5 - centerY) * procH * 0.5;
                       const areaFraction = count / (mw * mh);
                       const targetScale = 1.1 + Math.max(0, (0.25 - areaFraction) * 1.5);
                       trackingOffsetRef.current.x += (targetX - trackingOffsetRef.current.x) * 0.08;
                       trackingOffsetRef.current.y += (targetY - trackingOffsetRef.current.y) * 0.08;
                       trackingOffsetRef.current.scale += (targetScale - trackingOffsetRef.current.scale) * 0.05;
                   } else if (!globalParams.autoTracking) {
                       trackingOffsetRef.current.x *= 0.9; trackingOffsetRef.current.y *= 0.9;
                       trackingOffsetRef.current.scale += (1.0 - trackingOffsetRef.current.scale) * 0.1;
                   }
                   lastMaskRef.current = new ImageData(rgba, mw, mh);
                   result.categoryMask.close();
                   result.confidenceMasks?.forEach(m => m.close());
                }
              } catch (e) {}
          }
          ctx.save();
          if (globalParams.autoTracking || trackingOffsetRef.current.scale > 1.01) {
            ctx.translate(trackingOffsetRef.current.x, trackingOffsetRef.current.y); ctx.translate(procW/2, procH/2);
            ctx.scale(trackingOffsetRef.current.scale, trackingOffsetRef.current.scale); ctx.translate(-procW/2, -procH/2);
          }
          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, lastMaskRef.current);
          ctx.restore();
          displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, 0, 0, dimensions.w, dimensions.h);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  if (isPatternMode) {
    return (
      <div className="w-full h-full bg-black overflow-hidden" ref={containerRef}>
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={() => setMediaLoaded(true)} />
        )}
        <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className="w-full h-full object-cover" />
      </div>
    );
  }

  return (
    <div className="flex w-full h-screen overflow-hidden bg-white" ref={containerRef}>
      {isExporting && (
        <div className="absolute inset-0 z-[100] bg-black/80 backdrop-blur-xl flex flex-col items-center justify-center text-white p-10">
          <div className="relative w-24 h-24 mb-10 flex items-center justify-center">
            <div className="absolute inset-0 border-4 border-white/10 rounded-full"></div>
            <svg className="absolute inset-0 w-full h-full -rotate-90">
              <circle cx="48" cy="48" r="44" stroke="white" strokeWidth="4" fill="transparent" strokeDasharray={276} strokeDashoffset={276 - (276 * exportProgress) / 100} strokeLinecap="round" className="transition-all duration-300" />
            </svg>
            <span className="text-[14px] font-black">{Math.floor(exportProgress)}%</span>
          </div>
          <div className="flex flex-col items-center gap-2">
            <span className="text-[14px] font-black uppercase tracking-[0.5em] animate-pulse">Encoding H264 Video</span>
            <span className="text-[10px] font-bold text-white/60 tracking-widest uppercase">
              Estimated Remaining: <span className="text-white">{exportEta.toFixed(1)}s</span>
            </span>
          </div>
          <div className="mt-12 w-64 h-1 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-white transition-all duration-300" style={{ width: `${exportProgress}%` }}></div>
          </div>
          <p className="mt-6 text-[9px] font-bold text-white/40 uppercase tracking-[0.2em]">Do not close this tab until rendering is complete.</p>
        </div>
      )}

      <div 
        className={`relative w-1/2 h-full flex items-center justify-center transition-opacity duration-700 ${isDragging ? 'opacity-50' : 'opacity-100'}`}
        onDragOver={(e) => {e.preventDefault(); setIsDragging(true);}}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]);}}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-4 text-zinc-100 pointer-events-none">
             <span className="text-[9px] font-black uppercase tracking-[0.4em]">Initialize_Input (Drop File)</span>
          </div>
        )}
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="w-full h-full object-cover" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="w-full h-full object-cover" onLoad={() => setMediaLoaded(true)} />
