import { EffectId, GlobalParams, TrajectoryPoint } from '../types';
import { hexToRgb } from './utils';

const CHAR_SETS = {
    en: 'abcdefghijklmnopqrstuvwxyz0123456789',
    jp: 'あいうえおかきくけ코サシスセソ12345',
    kr: '가나다라마바사아자차카타파하12345',
    cn: '你好世界数字代码计算机数据',
    ar: 'ابجديةعربية١٢٣٤٥',
    numbers: '0123456789'
};

const getChar = (lang: string, onlyNumbers: boolean = false) => {
    let charset = CHAR_SETS.en;
    if (onlyNumbers) {
        charset = CHAR_SETS.numbers;
    } else if (lang === 'random') {
        const keys = Object.keys(CHAR_SETS).filter(k => k !== 'numbers');
        charset = CHAR_SETS[keys[Math.floor(Math.random() * keys.length)] as keyof typeof CHAR_SETS];
    } else {
        charset = CHAR_SETS[lang as keyof typeof CHAR_SETS] || CHAR_SETS.en;
    }
    return charset[Math.floor(Math.random() * charset.length)];
};

const getEffectStyle = (ctx: CanvasRenderingContext2D, width: number, height: number, color: string, presetIdx: number) => {
    if (presetIdx === 0) return color;
    const presets = [
        null,
        ['#ff00ff', '#00ffff'],
        ['#ff5f6d', '#ffc371'],
        ['#11998e', '#38ef7d'],
        ['#2193b0', '#6dd5ed'],
        ['#6441A5', '#2a0845']
    ];
    const colors = presets[presetIdx];
    if (!colors) return color;
    const grad = ctx.createLinearGradient(0, 0, width, height);
    grad.addColorStop(0, colors[0]);
    grad.addColorStop(1, colors[1]);
    return grad;
};

const drawPixel = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, trajectories: TrajectoryPoint[]) => {
  const baseSize = params.pixelSize || 12;
  const w = Math.ceil(width / baseSize);
  const h = Math.ceil(height / baseSize);

  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(ctx.canvas, 0, 0, width, height, 0, 0, w, h);
  ctx.drawImage(ctx.canvas, 0, 0, w, h, 0, 0, width, height);

  // If we have movement, sharpen the pixels around tracked joints
  if (trajectories.length > 0) {
      ctx.save();
      trajectories.slice(-10).forEach(p => {
          const px = p.x * width;
          const py = p.y * height;
          const r = 60;
          ctx.beginPath();
          ctx.arc(px, py, r, 0, Math.PI * 2);
          ctx.clip();
          // Draw a smaller pixelation area or even the original image to "reveal" detail
          ctx.drawImage(ctx.canvas, px-r, py-r, r*2, r*2, px-r, py-r, r*2, r*2);
      });
      ctx.restore();
  }
};

const drawHalftone = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, trajectories: TrajectoryPoint[]) => {
  const dotSize = Math.max(4, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = style;

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (Math.floor(y) * width + Math.floor(x)) * 4;
      if (i < data.length) {
        const lum = (0.299 * data[i] + 0.587 * data[i+1] + 0.114 * data[i+2]) / 255;

        // Influence dot size by proximity to current joint positions
        let movementBoost = 0;
        trajectories.slice(-5).forEach(p => {
            const dx = x - p.x * width;
            const dy = y - p.y * height;
            const d = dx*dx + dy*dy;
            if (d < 5000) movementBoost += (1 - d/5000) * 0.4;
        });

        const radius = (dotSize * 0.45) * (lum + movementBoost);
        if (radius > 0.3) {
          ctx.beginPath();
          ctx.arc(x + dotSize * 0.5, y + dotSize * 0.5, radius, 0, 6.28);
          ctx.fill();
        }
      }
    }
  }
};

const drawMatrix = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number, trajectories: TrajectoryPoint[]) => {
    ctx.fillStyle = style;
    const fSize = params.fontSize || 12;
    ctx.font = `bold ${fSize}px monospace`;
    const speed = params.fallSpeed * 15;

    // Matrix characters follow the "aura" of body parts
    const cols = Math.floor(width / (fSize * 0.8));
    for (let i = 0; i < cols; i++) {
        const cx = i * fSize * 0.8;
        let isInfluenced = false;

        trajectories.slice(-15).forEach(p => {
            if (Math.abs(cx - p.x * width) < 100) isInfluenced = true;
        });

        if (!isInfluenced && Math.random() > 0.05) continue;

        const offset = (i * 133.7) % height;
        const headY = (time * speed + offset) % height;

        for (let j = 0; j < 10; j++) {
            const y = (headY - j * fSize + height) % height;
            ctx.globalAlpha = Math.pow(0.8, j);
            ctx.fillText(getChar(params.language, params.showNumbers), cx, y);
        }
    }
    ctx.globalAlpha = 1;
};

const drawLine = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, trajectories: TrajectoryPoint[]) => {
    // Background trace
    ctx.save();
    ctx.globalAlpha = 0.1;
    ctx.drawImage(ctx.canvas, 0, 0);
    ctx.restore();

    ctx.strokeStyle = style;
    ctx.lineWidth = params.dotSize || 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Group trajectories by label (joint name)
    const paths: Record<string, TrajectoryPoint[]> = {};
    trajectories.forEach(p => {
        if (!paths[p.label]) paths[p.label] = [];
        paths[p.label].push(p);
    });

    Object.values(paths).forEach(points => {
        if (points.length < 2) return;
        ctx.beginPath();
        ctx.moveTo(points[0].x * width, points[0].y * height);

        for (let i = 1; i < points.length; i++) {
            const p = points[i];
            // Fade older points
            const age = Date.now() - p.timestamp;
            const opacity = Math.max(0, 1 - age / 3000); // 3-second trail
            ctx.globalAlpha = opacity;
            ctx.lineTo(p.x * width, p.y * height);

            // If it's the tip of the joint, draw a glowing circle
            if (i === points.length - 1) {
                ctx.save();
                ctx.shadowBlur = 15;
                ctx.shadowColor = style as string;
                ctx.fillStyle = '#fff';
                ctx.stroke();
                ctx.beginPath();
                ctx.arc(p.x * width, p.y * height, (params.dotSize || 3) * 1.5, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }
        ctx.stroke();
    });
    ctx.globalAlpha = 1;
};

// ... keep existing plexus logic ...
const plexusParticles: any[] = [];
const drawPlexus = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, mask: ImageData | null, time: number) => {
    const count = params.pointCount;
    if (plexusParticles.length !== count) {
        plexusParticles.length = 0;
        for(let i=0; i<count; i++) plexusParticles.push({ x: Math.random()*width, y: Math.random()*height, vx: (Math.random()-0.5)*params.speed, vy: (Math.random()-0.5)*params.speed, noise: Math.random()*100 });
    }
    ctx.fillStyle = style; ctx.strokeStyle = style;
    for(let i=0; i<count; i++) {
        const p = plexusParticles[i];
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > width) p.vx *= -1; if (p.y < 0 || p.y > height) p.vy *= -1;
        ctx.beginPath(); ctx.arc(p.x, p.y, params.pointSize/2, 0, Math.PI*2); ctx.fill();
    }
};

export const renderFrame = (
    ctx: CanvasRenderingContext2D, 
    source: HTMLImageElement | HTMLVideoElement, 
    effectId: EffectId, 
    params: any, 
    global: GlobalParams, 
    time: number, 
    aiMask?: ImageData | null,
    trajectories: TrajectoryPoint[] = []
) => {
    const width = ctx.canvas.width; const height = ctx.canvas.height;
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, width, height);

    // Draw Source
    ctx.drawImage(source, 0, 0, width, height);

    // Apply Global Filter (B&W, Invert, etc)
    const style = getEffectStyle(ctx, width, height, global.effectColor, global.gradientPreset);

    // Run Generative Effect
    switch(effectId) {
        case 'pixel': drawPixel(ctx, width, height, params, trajectories); break;
        case 'halftone': drawHalftone(ctx, width, height, params, style, trajectories); break;
        case 'matrix': drawMatrix(ctx, width, height, params, style, time, trajectories); break;
        case 'line': drawLine(ctx, width, height, params, style, trajectories); break;
        case 'plexus': drawPlexus(ctx, width, height, params, style, aiMask || null, time); break;
    }
};

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef, TrajectoryPoint } from '../types';
import { renderFrame } from '../services/renderEngine';
import { PoseLandmarker, FilesetResolver } from '@mediapipe/tasks-vision';
import { GoogleGenAI, Type } from '@google/genai';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  onAiAnalyze?: (analysis: any) => void;
  isCleanFeed?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  onAiAnalyze,
  isCleanFeed = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const landmarkerRef = useRef<PoseLandmarker | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const trajectoriesRef = useRef<TrajectoryPoint[]>([]);

  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [dimensions, setDimensions] = useState({ w: 800, h: 600 });

  // 1. Initialize Gemini & MediaPipe
  useEffect(() => {
    async function initMediaPipe() {
      const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
      const landmarker = await PoseLandmarker.createFromOptions(vision, {
        baseOptions: {
          modelAssetPath: `https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/latest/pose_landmarker_lite.task`,
          delegate: "GPU"
        },
        runningMode: isVideo ? "VIDEO" : "IMAGE",
        numPoses: 1
      });
      landmarkerRef.current = landmarker;
    }
    initMediaPipe();
    return () => landmarkerRef.current?.close();
  }, [isVideo]);

  // 2. Gemini 3 Pro Intelligent Media Analysis
  const performGeminiAnalysis = async (source: HTMLImageElement | HTMLVideoElement) => {
    if (!process.env.API_KEY) return;
    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Capture a frame for analysis
      const canvas = document.createElement('canvas');
      canvas.width = 400; canvas.height = 400;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        if (source instanceof HTMLVideoElement) ctx.drawImage(source, 0, 0, 400, 400);
        else ctx.drawImage(source, 0, 0, 400, 400);
      }
      const base64Image = canvas.toDataURL('image/jpeg').split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [
            { parts: [{ text: "Analyze this image and return a JSON configuration for a generative art app. Mood should be one of 'cyberpunk', 'organic', 'minimalist', 'high-energy'. Provide hue (0-360), saturation (0-100), and a recommended effect name from ['PLEXUS', 'PIXEL', 'HALFTONE', 'MATRIX', 'LINE']." }, { inlineData: { mimeType: 'image/jpeg', data: base64Image } }] }
        ],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              hue: { type: Type.INTEGER },
              saturation: { type: Type.INTEGER },
              effect: { type: Type.STRING },
              mood: { type: Type.STRING }
            }
          }
        }
      });

      if (response.text) {
        const config = JSON.parse(response.text);
        onAiAnalyze?.(config);
      }
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleMediaLoad = (e: any) => {
    setMediaLoaded(true);
    const source = e.target;
    const aspect = (source.videoWidth || source.naturalWidth) / (source.videoHeight || source.naturalHeight);
    const w = 1280;
    const h = 1280 / aspect;
    setDimensions({ w, h });
    performGeminiAnalysis(source);
  };

  // 3. Main Render Loop
  const animate = () => {
    if (canvasRef.current && mediaLoaded && landmarkerRef.current) {
      const ctx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && source) {
        // Run MediaPipe Tracking
        let result;
        if (isVideo) result = landmarkerRef.current.detectForVideo(source as HTMLVideoElement, performance.now());
        else result = landmarkerRef.current.detect(source as HTMLImageElement);

        if (result && result.landmarks && result.landmarks[0]) {
            const now = Date.now();
            // Track critical joints: Wrists (15, 16), Ankles (27, 28), Nose (0)
            const joints = [0, 15, 16, 27, 28];
            joints.forEach(idx => {
                const lm = result.landmarks[0][idx];
                if (lm.visibility > 0.5) {
                    trajectoriesRef.current.push({ x: lm.x, y: lm.y, label: `joint_${idx}`, timestamp: now });
                }
            });
            // Keep history lean (last 200 points)
            if (trajectoriesRef.current.length > 200) trajectoriesRef.current.splice(0, trajectoriesRef.current.length - 200);
        }

        const elapsed = (now() - startTimeRef.current) / 1000;
        renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, null, trajectoriesRef.current);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [mediaLoaded, activeEffect, effectParams, globalParams]);

  const now = () => Date.now();

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-black overflow-hidden" ref={containerRef}>
      {isAnalyzing && (
        <div className="absolute inset-0 z-50 bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
            <div className="w-16 h-16 border-4 border-t-white border-white/10 rounded-full animate-spin mb-4"></div>
            <span className="text-[10px] font-black uppercase tracking-[0.5em] animate-pulse">Gemini 3 Pro Analyzing Scene...</span>
        </div>
      )}

      {mediaSrc && (
          isVideo ? 
          <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={handleMediaLoad} /> :
          <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={handleMediaLoad} />
      )}

      <canvas 
        ref={canvasRef} 
        width={dimensions.w} 
        height={dimensions.h} 
        className="max-w-full max-h-full shadow-2xl transition-opacity duration-1000" 
        style={{ opacity: mediaLoaded ? 1 : 0 }}
      />

      {!mediaSrc && !isCleanFeed && (
        <div 
          className="absolute inset-0 flex flex-col items-center justify-center border-4 border-dashed border-zinc-200/50 m-20 rounded-3xl"
          onDragOver={e => e.preventDefault()}
          onDrop={e => { e.preventDefault(); if (e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]); }}
        >
          <span className="text-[12px] font-black text-zinc-400 uppercase tracking-widest">Drop Media to Trace Reality</span>
        </div>
      )}
    </div>
  );
});

export default CanvasRenderer;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt, hslToHex } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const syncChannel = useMemo(() => new BroadcastChannel('visual-parameter-sync'), []);
  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  // AI Analysis Handler
  const handleAiAnalysis = (analysis: any) => {
    const newGlobal = { 
      ...globalParams, 
      hue: analysis.hue, 
      saturation: analysis.saturation,
      effectColor: hslToHex(analysis.hue, analysis.saturation, 50)
    };
    setGlobalParams(newGlobal);
    const targetEffect = EFFECTS.find(e => e.name === analysis.effect) || EFFECTS[0];
    setActiveEffect(targetEffect);
    setEffectParams(targetEffect.defaultParams);
  };

  // Sync Logic... (Keep existing BroadcastChannel logic from provided code)
  useEffect(() => {
    if (!isOnAirView) {
      syncChannel.postMessage({ type: 'STATE_UPDATE', mediaSrc, isVideo, globalParams, activeEffectId: activeEffect.id, effectParams });
    }
  }, [mediaSrc, isVideo, globalParams, activeEffect, effectParams, isOnAirView, syncChannel]);

  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black flex items-center justify-center overflow-hidden">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={() => {}} 
          isCleanFeed={true}
        />
      </div>
    );
  }

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header onExport={() => rendererRef.current?.startExport()} onAir={() => window.open(window.location.href + '?view=onair', '_blank')} isExporting={isExporting} />
      </div>

      <main className="w-full h-full">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onAiAnalyze={handleAiAnalysis}
          onExportStateChange={setIsExporting}
        />
      </main>

      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-[1440px] pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel globalParams={globalParams} setGlobalParams={setGlobalParams} activeEffect={activeEffect} effectParams={effectParams} setEffectParams={setEffectParams} allEffects={EFFECTS} onSelectEffect={(eff) => { setActiveEffect(eff); setEffectParams(eff.defaultParams); }} isVideo={isVideo} />
         </div>
      </div>
    </div>
  );
};

export default App;

