    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const canvas = document.createElement('canvas');
      canvas.width = 400; canvas.height = 400;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(source, 0, 0, 400, 400);
      }
      const base64Image = canvas.toDataURL('image/jpeg').split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [
            { parts: [{ text: "Analyze this image and return a JSON configuration for a generative art app. Mood should be one of 'cyberpunk', 'organic', 'minimalist', 'high-energy'. Provide hue (0-360), saturation (0-100), and a recommended effect name from ['PLEXUS', 'PIXEL', 'HALFTONE', 'MATRIX', 'LINE']." }, { inlineData: { mimeType: 'image/jpeg', data: base64Image } }] }
        ],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              hue: { type: Type.INTEGER },
              saturation: { type: Type.INTEGER },
              effect: { type: Type.STRING },
              mood: { type: Type.STRING }
            }
          }
        }
      });

      if (response.text) {
        const config = JSON.parse(response.text);
        onAiAnalyze?.(config);
      }
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleMediaLoad = (e: any) => {
    setMediaLoaded(true);
    const source = e.target;
    const aspect = (source.videoWidth || source.naturalWidth) / (source.videoHeight || source.naturalHeight);
    const h = 720;
    const w = h * aspect;
    // Set for split screen (double width)
    setDimensions({ w: w * 2, h: h });
    performGeminiAnalysis(source);
  };

  // 3. Main Render Loop
  const animate = () => {
    if (canvasRef.current && mediaLoaded && landmarkerRef.current) {
      const mainCtx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (mainCtx && source) {
        const halfW = dimensions.w / 2;
        const h = dimensions.h;

        // Run MediaPipe Tracking
        let result;
        if (isVideo) result = landmarkerRef.current.detectForVideo(source as HTMLVideoElement, performance.now());
        else result = landmarkerRef.current.detect(source as HTMLImageElement);

        if (result && result.landmarks && result.landmarks[0]) {
            const now = Date.now();
            const joints = [0, 15, 16, 27, 28]; // Nose, Wrists, Ankles
            joints.forEach(idx => {
                const lm = result.landmarks[0][idx];
                if (lm.visibility > 0.5) {
                    trajectoriesRef.current.push({ x: lm.x, y: lm.y, label: `joint_${idx}`, timestamp: now });
                }
            });
            if (trajectoriesRef.current.length > 300) trajectoriesRef.current.splice(0, trajectoriesRef.current.length - 300);
        }

        // Draw Left: Original
        mainCtx.drawImage(source, 0, 0, halfW, h);

        // Draw Divider
        mainCtx.strokeStyle = 'white';
        mainCtx.lineWidth = 2;
        mainCtx.beginPath();
        mainCtx.moveTo(halfW, 0);
        mainCtx.lineTo(halfW, h);
        mainCtx.stroke();

        // Create temporary canvas for effect rendering (to use the existing renderFrame logic easily)
        const offCanvas = document.createElement('canvas');
        offCanvas.width = halfW;
        offCanvas.height = h;
        const offCtx = offCanvas.getContext('2d');
        if (offCtx) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          renderFrame(offCtx, source, activeEffect.id, effectParams, globalParams, elapsed, null, trajectoriesRef.current);

          // Draw Right: Effect
          mainCtx.drawImage(offCanvas, halfW, 0);
        }

        // Overlay skeleton on original if tracking is on
        if (globalParams.autoTracking && result?.landmarks?.[0]) {
          mainCtx.fillStyle = '#fff';
          result.landmarks[0].forEach(lm => {
            if (lm.visibility > 0.5) {
              mainCtx.beginPath();
              mainCtx.arc(lm.x * halfW, lm.y * h, 3, 0, Math.PI * 2);
              mainCtx.fill();
            }
          });
        }
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [mediaLoaded, activeEffect, effectParams, globalParams, dimensions]);

  useImperativeHandle(ref, () => ({
    startExport: () => {
      if (!canvasRef.current) return;
      const link = document.createElement('a');
      link.download = `visual-parameter-${Date.now()}.png`;
      link.href = canvasRef.current.toDataURL();
      link.click();
    }
  }));

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-white overflow-hidden p-12" ref={containerRef}>
      {isAnalyzing && (
        <div className="absolute inset-0 z-50 bg-white/40 backdrop-blur-xl flex flex-col items-center justify-center text-zinc-900">
            <div className="w-12 h-12 border-2 border-t-zinc-900 border-zinc-200 rounded-full animate-spin mb-6"></div>
            <span className="text-[10px] font-black uppercase tracking-[0.5em] animate-pulse">Analyzing Scene...</span>
        </div>
      )}

      {mediaSrc && (
          isVideo ? 
          <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={handleMediaLoad} /> :
          <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={handleMediaLoad} />
      )}

      <div className="relative shadow-2xl rounded-2xl overflow-hidden bg-black flex items-center justify-center">
        <canvas 
            ref={canvasRef} 
            width={dimensions.w} 
            height={dimensions.h} 
            className="max-w-full max-h-[70vh] transition-opacity duration-1000" 
            style={{ opacity: mediaLoaded ? 1 : 0 }}
        />
      </div>

      {!mediaSrc && !isCleanFeed && (
        <div 
          className="absolute inset-0 flex flex-col items-center justify-center border-2 border-dashed border-zinc-200 m-20 rounded-[40px] bg-zinc-50/50"
          onDragOver={e => e.preventDefault()}
          onDrop={e => { e.preventDefault(); if (e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]); }}
        >
          <div className="bg-white p-8 rounded-full shadow-sm mb-6">
             <div className="w-10 h-10 border-2 border-zinc-900 rounded-lg flex items-center justify-center">
                <div className="w-4 h-4 bg-zinc-900 rounded-sm"></div>
             </div>
          </div>
          <span className="text-[12px] font-black text-zinc-400 uppercase tracking-widest">Drop Image or Video to Begin</span>
          <span className="text-[9px] font-bold text-zinc-300 uppercase tracking-widest mt-2">AI Motion Tracing Interface</span>
        </div>
      )}
    </div>
  );
});

export default CanvasRenderer;

import React from 'react';
import { GlobalParams, EffectDef, ParamConfig } from '../types';
import { hslToHex } from '../services/utils';
import { CheckSquare, Square, Zap, Target, SlidersHorizontal } from 'lucide-react';

interface ControlPanelProps {
  globalParams: GlobalParams;
  setGlobalParams: (p: GlobalParams) => void;
  activeEffect: EffectDef;
  effectParams: any;
  setEffectParams: (p: any) => void;
  allEffects: EffectDef[];
  onSelectEffect: (e: EffectDef) => void;
  isVideo: boolean;
}

const ControlPanel: React.FC<ControlPanelProps> = ({
  globalParams, setGlobalParams, activeEffect, effectParams, setEffectParams, allEffects, onSelectEffect
}) => {
  const updateGlobal = (key: keyof GlobalParams, val: any) => setGlobalParams({ ...globalParams, [key]: val });
  const updateEffect = (key: string, val: any) => setEffectParams({ ...effectParams, [key]: val });

  const handleHSLChange = (key: 'hue' | 'saturation' | 'lightness', val: number) => {
      const nextParams = { ...globalParams, [key]: val };
      const hex = hslToHex(nextParams.hue, nextParams.saturation, nextParams.lightness);
      setGlobalParams({ ...nextParams, effectColor: hex, gradientPreset: 0 });
  };

  return (
    <div className="flex flex-col gap-4 w-full animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Parameters Panel */}
      <div className="bg-white/80 backdrop-blur-2xl border border-zinc-200/50 rounded-[40px] p-8 px-10 flex flex-col gap-6 shadow-2xl shadow-zinc-200/50">
         <div className="flex items-center gap-3 overflow-x-auto no-scrollbar pb-1">
            {allEffects.map((eff) => (
                <button
                    key={eff.id} onClick={() => onSelectEffect(eff)}
                    className={`px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeEffect.id === eff.id ? 'bg-zinc-900 text-white' : 'bg-zinc-100 text-zinc-500 hover:bg-zinc-200'}`}
                >
                    {eff.name}
                </button>
            ))}
         </div>

         <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-x-12 gap-y-6">
             {(Object.entries(activeEffect.paramConfig) as [string, ParamConfig][]).map(([key, config]) => (
                 <div key={key} className="flex flex-col gap-2 min-w-[120px]">
                     <div className="flex justify-between text-[8px] font-black text-zinc-400 uppercase tracking-widest">
                         <span>{key}</span>
                         <span className="text-zinc-900">{effectParams[key]}</span>
                     </div>
                     {config.type === 'slider' ? (
                         <input type="range" min={config.min} max={config.max} step={config.step} value={effectParams[key]} onChange={(e) => updateEffect(key, parseFloat(e.target.value))} className="w-full h-1 bg-zinc-200 rounded-full appearance-none accent-zinc-900 cursor-pointer" />
                     ) : config.type === 'select' ? (
                         <select value={effectParams[key]} onChange={(e) => updateEffect(key, e.target.value)} className="bg-zinc-50 text-zinc-900 text-[10px] font-bold p-1.5 px-3 rounded-xl border border-zinc-200 uppercase outline-none cursor-pointer hover:bg-zinc-100">
                             {config.options?.map(o => <option key={o} value={o}>{o}</option>)}
                         </select>
                     ) : (
                         <button onClick={() => updateEffect(key, !effectParams[key])} className={`flex items-center gap-2 text-[9px] font-bold uppercase transition-all ${effectParams[key] ? 'text-zinc-900' : 'text-zinc-300 hover:text-zinc-500'}`}>
                             {effectParams[key] ? <CheckSquare size={14} className="fill-zinc-900 text-white" /> : <Square size={14}/>} {key}
                         </button>
                     )}
                 </div>
             ))}
         </div>
      </div>

      {/* Global Toolbar */}
      <div className="bg-white/90 backdrop-blur-2xl border border-zinc-200/50 rounded-full p-3 px-10 flex items-center justify-between gap-8 shadow-2xl shadow-zinc-200/50">
            <div className="flex items-center gap-12">
                <div className="flex items-center gap-8">
                    <SlidersHorizontal size={14} className="text-zinc-300" />

                    {/* Hue */}
                    <div className="flex flex-col gap-1 w-40">
                        <div className="flex justify-between text-[7px] font-black text-zinc-400 uppercase tracking-widest">
                            <span>Hue</span>
                            <span className="text-zinc-900">{Math.round(globalParams.hue)}°</span>
                        </div>
                        <input 
                            type="range" min="0" max="360" value={globalParams.hue} 
                            onChange={(e) => handleHSLChange('hue', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer"
                            style={{ background: 'linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)' }}
                        />
                    </div>

                    {/* Saturation */}
                    <div className="flex flex-col gap-1 w-28">
                        <div className="flex justify-between text-[7px] font-black text-zinc-400 uppercase tracking-widest">
                            <span>Saturation</span>
                            <span className="text-zinc-900">{Math.round(globalParams.saturation)}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" value={globalParams.saturation} 
                            onChange={(e) => handleHSLChange('saturation', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer bg-zinc-100"
                        />
                    </div>
                </div>

                <div className="h-8 w-px bg-zinc-100" />

                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2 border-r border-zinc-100 pr-4">
                        {[
                          { key: 'bw', label: 'B&W' },
                          { key: 'xray', label: 'X-Ray' },
                          { key: 'dramaticWarm', label: 'Warm' },
                          { key: 'dramaticCool', label: 'Cool' }
                        ].map((f) => (
                          <button 
                            key={f.key}
                            onClick={() => updateGlobal(f.key as keyof GlobalParams, !globalParams[f.key as keyof GlobalParams])} 
                            className={`px-6 py-2.5 rounded-full text-[9px] font-black transition-all border ${globalParams[f.key as keyof GlobalParams] ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-zinc-50 text-zinc-400 border-zinc-200 hover:border-zinc-400 hover:text-zinc-600'}`}
                          >
                            {f.label}
                          </button>
                        ))}
                    </div>

                    <button 
                      onClick={() => updateGlobal('invert', !globalParams.invert)} 
                      className={`flex items-center gap-3 px-4 py-2 text-[9px] font-black uppercase transition-all ${globalParams.invert ? 'text-zinc-900' : 'text-zinc-300 hover:text-zinc-500'}`}
                    >
                      {globalParams.invert ? <CheckSquare size={16} className="fill-zinc-900 text-white" /> : <Square size={16}/>}
                      Invert
                    </button>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <button 
                  onClick={() => updateGlobal('autoTracking', !globalParams.autoTracking)} 
                  className={`flex items-center gap-3 px-8 py-3 rounded-full text-[9px] font-black uppercase transition-all border ${globalParams.autoTracking ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-zinc-50 text-zinc-400 border border-zinc-200 hover:bg-zinc-100'}`}
                >
                  <Target size={14} className={globalParams.autoTracking ? 'text-indigo-500 animate-pulse' : ''}/>
                  Tracking
                </button>

                <div className="flex bg-zinc-50 rounded-full p-1 border border-zinc-200">
                    {['subject', 'background', 'both'].map(m => (
                        <button key={m} onClick={() => updateGlobal('applyTo', m)} className={`px-6 py-2.5 rounded-full text-[8px] font-black uppercase transition-all ${globalParams.applyTo === m ? 'bg-white text-zinc-900 shadow-sm border border-zinc-100' : 'text-zinc-400 hover:text-zinc-600'}`}>{m}</button>
                    ))}
                </div>

                <button 
                  onClick={() => updateGlobal('mixMode', !globalParams.mixMode)} 
                  className={`flex items-center gap-3 px-8 py-3 rounded-full text-[9px] font-black uppercase transition-all ${globalParams.mixMode ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-zinc-50 text-zinc-400 border border-zinc-200 hover:bg-zinc-100'}`}
                >
                  <Zap size={14} className={globalParams.mixMode ? 'animate-pulse text-yellow-500 fill-yellow-500' : ''}/>
                  Mix
                </button>
            </div>
      </div>
    </div>
  );
};

export default ControlPanel;

