  }

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden">
      {/* Immersive Background Canvas */}
      <div className="absolute inset-0 z-0">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
