    }
    ctx.fillStyle = style; ctx.strokeStyle = style;
    for(let i=0; i<count; i++) {
        const p = plexusParticles[i];
        let fx = 0, fy = 0;
        trajectories.slice(-5).forEach(tp => {
            const dx = tp.x * width - p.x; const dy = tp.y * height - p.y;
            const d = Math.sqrt(dx*dx + dy*dy);
            if (d < 150) { fx += dx/50; fy += dy/50; }
        });
        p.x += p.vx + fx; p.y += p.vy + fy;
        if (p.x < 0 || p.x > width) p.vx *= -1; if (p.y < 0 || p.y > height) p.vy *= -1;
        ctx.beginPath(); ctx.arc(p.x, p.y, params.pointSize/2, 0, Math.PI*2); ctx.fill();
        for(let j=i+1; j<Math.min(i+20, count); j++) {
            const p2 = plexusParticles[j];
            const d = Math.hypot(p.x - p2.x, p.y - p2.y);
            if (d < params.linkDistance) {
                ctx.globalAlpha = 1 - d/params.linkDistance;
                ctx.lineWidth = params.lineWidth;
                ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
            }
        }
    }
    ctx.globalAlpha = 1;
};

export const renderFrame = (
    ctx: CanvasRenderingContext2D, 
    source: HTMLImageElement | HTMLVideoElement, 
    effectId: EffectId, 
    params: any, 
    global: GlobalParams, 
    time: number, 
    trajectories: TrajectoryPoint[] = []
) => {
    const width = ctx.canvas.width; const height = ctx.canvas.height;
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, width, height);

    const sAspect = (source instanceof HTMLVideoElement ? source.videoWidth : source.naturalWidth) / (source instanceof HTMLVideoElement ? source.videoHeight : source.naturalHeight);
    const targetW = height * sAspect;
    const offsetX = (width - targetW) / 2;
    ctx.drawImage(source, offsetX, 0, targetW, height);

    const style = getEffectStyle(ctx, width, height, global.effectColor, global.gradientPreset);

    switch(effectId) {
        case 'pixel': drawPixel(ctx, width, height, params, trajectories); break;
        case 'halftone': drawHalftone(ctx, width, height, params, style, trajectories); break;
        case 'matrix': drawMatrix(ctx, width, height, params, style, time, trajectories); break;
        case 'line': drawLine(ctx, width, height, params, style, trajectories); break;
        case 'plexus': drawPlexus(ctx, width, height, params, style, trajectories); break;
    }

    if (global.bw) {
        ctx.save(); ctx.globalCompositeOperation = 'saturation';
        ctx.fillStyle = 'black'; ctx.fillRect(0,0,width,height); ctx.restore();
    }
    if (global.invert) {
        ctx.save(); ctx.globalCompositeOperation = 'difference';
        ctx.fillStyle = 'white'; ctx.fillRect(0,0,width,height); ctx.restore();
    }
};

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef, TrajectoryPoint } from '../types';
import { renderFrame } from '../services/renderEngine';
import { PoseLandmarker, FilesetResolver } from '@mediapipe/tasks-vision';
import { GoogleGenAI, Type } from '@google/genai';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  onAiAnalyze?: (analysis: any) => void;
  isCleanFeed?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  onAiAnalyze,
  isCleanFeed = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const landmarkerRef = useRef<PoseLandmarker | null>(null);
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(Date.now());
  const trajectoriesRef = useRef<TrajectoryPoint[]>([]);

  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });

  useEffect(() => {
    async function initMediaPipe() {
      const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
      const landmarker = await PoseLandmarker.createFromOptions(vision, {
        baseOptions: {
          modelAssetPath: `https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/latest/pose_landmarker_lite.task`,
          delegate: "GPU"
        },
        runningMode: isVideo ? "VIDEO" : "IMAGE",
        numPoses: 1
      });
      landmarkerRef.current = landmarker;
    }
    initMediaPipe();
    return () => landmarkerRef.current?.close();
  }, [isVideo]);

  const performGeminiAnalysis = async (source: HTMLImageElement | HTMLVideoElement) => {
    if (!process.env.API_KEY) return;
    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const canvas = document.createElement('canvas');
      canvas.width = 400; canvas.height = 400;
      const ctx = canvas.getContext('2d');
      if (ctx) ctx.drawImage(source, 0, 0, 400, 400);
      const base64Image = canvas.toDataURL('image/jpeg').split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [
            { parts: [{ text: "Analyze this scene. Suggest JSON with hue (0-360), saturation (0-100), and effect name from ['PLEXUS', 'PIXEL', 'HALFTONE', 'MATRIX', 'LINE']." }, { inlineData: { mimeType: 'image/jpeg', data: base64Image } }] }
        ],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              hue: { type: Type.INTEGER },
              saturation: { type: Type.INTEGER },
              effect: { type: Type.STRING }
            }
          }
        }
      });
      if (response.text) onAiAnalyze?.(JSON.parse(response.text));
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const calculateSize = () => {
    if (!containerRef.current) return;
    setDimensions({ w: containerRef.current.clientWidth, h: containerRef.current.clientHeight });
  };

  useEffect(() => {
    window.addEventListener('resize', calculateSize);
    calculateSize();
    return () => window.removeEventListener('resize', calculateSize);
  }, []);

  const handleMediaLoad = (e: any) => {
    setMediaLoaded(true);
    performGeminiAnalysis(e.target);
  };

  const animate = () => {
    if (canvasRef.current && mediaLoaded && landmarkerRef.current) {
      const mainCtx = canvasRef.current.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (mainCtx && source && dimensions.w > 0) {
        const halfW = dimensions.w / 2;
        const h = dimensions.h;
        let result;
        if (isVideo) result = landmarkerRef.current.detectForVideo(source as HTMLVideoElement, performance.now());
        else result = landmarkerRef.current.detect(source as HTMLImageElement);

        if (result?.landmarks?.[0]) {
            const now = Date.now();
            [0, 15, 16, 27, 28].forEach(idx => {
                const lm = result.landmarks[0][idx];
                if (lm.visibility > 0.5) trajectoriesRef.current.push({ x: lm.x, y: lm.y, label: `j_${idx}`, timestamp: now });
            });
            if (trajectoriesRef.current.length > 300) trajectoriesRef.current.splice(0, trajectoriesRef.current.length - 300);
        }

        // Left: Original
        const sAspect = (source instanceof HTMLVideoElement ? source.videoWidth : source.naturalWidth) / (source instanceof HTMLVideoElement ? source.videoHeight : source.naturalHeight);
        const targetW = h * sAspect;
        const offsetX = (halfW - targetW) / 2;
        mainCtx.save();
        mainCtx.beginPath(); mainCtx.rect(0, 0, halfW, h); mainCtx.clip();
        mainCtx.drawImage(source, offsetX, 0, targetW, h);
        if (globalParams.autoTracking && result?.landmarks?.[0]) {
            mainCtx.fillStyle = '#fff';
            result.landmarks[0].forEach(lm => {
                if (lm.visibility > 0.5) {
                    mainCtx.beginPath(); mainCtx.arc(offsetX + lm.x * targetW, lm.y * h, 3, 0, Math.PI * 2); mainCtx.fill();
                }
            });
        }
        mainCtx.restore();

        // Right: Effect
        const offCanvas = document.createElement('canvas');
        offCanvas.width = halfW; offCanvas.height = h;
        const offCtx = offCanvas.getContext('2d');
        if (offCtx) {
          renderFrame(offCtx, source, activeEffect.id, effectParams, globalParams, (Date.now() - startTimeRef.current) / 1000, trajectoriesRef.current);
          mainCtx.drawImage(offCanvas, halfW, 0);
        }
        mainCtx.strokeStyle = 'white'; mainCtx.lineWidth = 1; mainCtx.beginPath(); mainCtx.moveTo(halfW, 0); mainCtx.lineTo(halfW, h); mainCtx.stroke();
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [mediaLoaded, activeEffect, effectParams, globalParams, dimensions]);

  useImperativeHandle(ref, () => ({
    startExport: () => {
      if (!canvasRef.current) return;
      const link = document.createElement('a');
      link.download = `VP_${Date.now()}.png`;
      link.href = canvasRef.current.toDataURL();
      link.click();
    }
  }));

  return (
    <div className="relative w-full h-full bg-white overflow-hidden" ref={containerRef}>
      {isAnalyzing && (
        <div className="absolute inset-0 z-[60] bg-white/60 backdrop-blur-3xl flex flex-col items-center justify-center text-zinc-900">
            <div className="w-12 h-12 border-2 border-t-zinc-900 border-zinc-100 rounded-full animate-spin mb-6"></div>
            <span className="text-[10px] font-black uppercase tracking-[0.6em] animate-pulse">Gemini Analysis Active</span>
        </div>
      )}
      {mediaSrc && (isVideo ? 
          <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={handleMediaLoad} /> :
          <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={handleMediaLoad} />
      )}
      <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className="w-full h-full block bg-black" />
      {!mediaSrc && !isCleanFeed && (
        <label className="absolute inset-0 flex flex-col items-center justify-center cursor-pointer bg-zinc-50/50 hover:bg-zinc-100/50 transition-colors">
          <input type="file" accept="image/*,video/*" className="hidden" onChange={e => e.target.files?.[0] && onUpload(e.target.files[0])} />
          <div className="w-20 h-20 bg-white rounded-3xl shadow-xl flex items-center justify-center mb-6">
             <div className="w-8 h-8 border-2 border-zinc-900 rounded-lg relative">
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-3 h-3 bg-zinc-900 rounded-sm"></div>
             </div>
          </div>
          <span className="text-[12px] font-black text-zinc-900 uppercase tracking-widest">Trace Reality</span>
        </label>
      )}
    </div>
  );
});

export default CanvasRenderer;

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef } from './types';
import { hslToHex } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  const handleAiAnalyze = (analysis: any) => {
    const newGlobal = { 
      ...globalParams, 
      hue: analysis.hue || 0, 
      saturation: analysis.saturation || 100,
      effectColor: hslToHex(analysis.hue || 0, analysis.saturation || 100, 50)
    };
    setGlobalParams(newGlobal);
    const target = EFFECTS.find(e => e.id.toLowerCase() === analysis.effect?.toLowerCase()) || EFFECTS[0];
    setActiveEffect(target);
    setEffectParams(target.defaultParams);
  };

  const handleUpload = (file: File) => {
    if (mediaSrc) URL.revokeObjectURL(mediaSrc);
    setMediaSrc(URL.createObjectURL(file));
    setIsVideo(file.type.startsWith('video'));
  };

  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black">
        <CanvasRenderer mediaSrc={mediaSrc} isVideo={isVideo} activeEffect={activeEffect} effectParams={effectParams} globalParams={globalParams} onUpload={() => {}} isCleanFeed={true} />
      </div>
    );
  }

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden">
      <div className="absolute inset-0 z-0">
        <CanvasRenderer ref={rendererRef} mediaSrc={mediaSrc} isVideo={isVideo} activeEffect={activeEffect} effectParams={effectParams} globalParams={globalParams} onUpload={handleUpload} onAiAnalyze={handleAiAnalyze} onExportStateChange={setIsExporting} />
      </div>
      <div className="relative z-10 h-full w-full pointer-events-none flex flex-col justify-between">
        <div className="pointer-events-auto bg-gradient-to-b from-white/90 to-transparent">
          <Header onExport={() => rendererRef.current?.startExport()} onAir={() => window.open(window.location.href + '?view=onair', '_blank')} isExporting={isExporting} />
        </div>
        <div className="w-full px-8 pb-10 pointer-events-auto">
          <div className="max-w-[1440px] mx-auto">
            <ControlPanel globalParams={globalParams} setGlobalParams={setGlobalParams} activeEffect={activeEffect} effectParams={effectParams} setEffectParams={setEffectParams} allEffects={EFFECTS} onSelectEffect={e => { setActiveEffect(e); setEffectParams(e.defaultParams); }} isVideo={isVideo} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

