    cn: '你好世界数字代码计算机数据',
    ar: 'ابجديةعربية١٢٣٤٥',
    numbers: '0123456789'
};

const getChar = (lang: string, onlyNumbers: boolean = false) => {
    let charset = CHAR_SETS.en;
    if (onlyNumbers) {
        charset = CHAR_SETS.numbers;
    } else if (lang === 'random') {
        const keys = Object.keys(CHAR_SETS).filter(k => k !== 'numbers');
        charset = CHAR_SETS[keys[Math.floor(Math.random() * keys.length)] as keyof typeof CHAR_SETS];
    } else {
        charset = CHAR_SETS[lang as keyof typeof CHAR_SETS] || CHAR_SETS.en;
    }
    return charset[Math.floor(Math.random() * charset.length)];
};

const getEffectStyle = (ctx: CanvasRenderingContext2D, width: number, height: number, color: string, presetIdx: number) => {
    if (presetIdx === 0) return color;
    const presets = [
        null,
        ['#ff00ff', '#00ffff'],
        ['#ff5f6d', '#ffc371'],
        ['#11998e', '#38ef7d'],
        ['#2193b0', '#6dd5ed'],
        ['#6441A5', '#2a0845']
    ];
    const colors = presets[presetIdx];
    if (!colors) return color;
    const grad = ctx.createLinearGradient(0, 0, width, height);
    grad.addColorStop(0, colors[0]);
    grad.addColorStop(1, colors[1]);
    return grad;
};

const drawPixel = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, trajectories: TrajectoryPoint[], source: any) => {
  const baseSize = params.pixelSize || 12;
  const w = Math.ceil(width / baseSize);
  const h = Math.ceil(height / baseSize);
  ctx.imageSmoothingEnabled = false;

  // Draw downscaled then upscaled to create pixel effect
  ctx.drawImage(source, 0, 0, width, height, 0, 0, w, h);
  ctx.drawImage(ctx.canvas, 0, 0, w, h, 0, 0, width, height);

  // Reaction to movement: Un-pixelate around joints
  if (trajectories.length > 0) {
      ctx.save();
      trajectories.slice(-5).forEach(p => {
          const px = p.x * width;
          const py = p.y * height;
          ctx.beginPath();
          ctx.arc(px, py, 60, 0, Math.PI * 2);
          ctx.clip();
          ctx.drawImage(source, 0, 0, width, height);
      });
      ctx.restore();
  }
};

const drawHalftone = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, trajectories: TrajectoryPoint[]) => {
  const dotSize = Math.max(4, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = style;

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (Math.floor(y) * width + Math.floor(x)) * 4;
      if (i < data.length) {
        const lum = (0.299 * data[i] + 0.587 * data[i+1] + 0.114 * data[i+2]) / 255;
        let movementBoost = 0;
        trajectories.slice(-10).forEach(p => {
            const dx = x - p.x * width;
            const dy = y - p.y * height;
            const d = dx*dx + dy*dy;
            if (d < 5000) movementBoost += (1 - d/5000) * 0.4;
        });

        const radius = (dotSize * 0.45) * (lum + movementBoost);
        if (radius > 0.4) {
          ctx.beginPath();
          ctx.arc(x + dotSize * 0.5, y + dotSize * 0.5, radius, 0, 6.28);
          ctx.fill();
        }
      }
    }
  }
};

const drawMatrix = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number, trajectories: TrajectoryPoint[]) => {
    ctx.fillStyle = style;
    const fSize = params.fontSize || 12;
    ctx.font = `bold ${fSize}px monospace`;
    const speed = params.fallSpeed * 15;
    const cols = Math.floor(width / (fSize * 0.8));

    for (let i = 0; i < cols; i++) {
        const cx = i * fSize * 0.8;
        let isMoving = false;
        trajectories.forEach(p => { if (Math.abs(cx - p.x * width) < 80) isMoving = true; });
        if (!isMoving && Math.random() > 0.1) continue;

        const offset = (i * 133.7) % height;
        const headY = (time * speed + offset) % height;
        for (let j = 0; j < 15; j++) {
            const y = (headY - j * fSize + height) % height;
            ctx.globalAlpha = Math.pow(0.85, j);
            ctx.fillText(getChar(params.language, params.showNumbers), cx, y);
        }
    }
    ctx.globalAlpha = 1;
};

const drawLine = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, trajectories: TrajectoryPoint[]) => {
    // 1. Draw persistent trails with fade
    ctx.save();
    ctx.globalAlpha = 0.05; 
    ctx.drawImage(ctx.canvas, 0, 0); 
    ctx.restore();

    ctx.strokeStyle = style;
    ctx.lineWidth = params.dotSize || 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Group trajectories by joint label
    const paths: Record<string, TrajectoryPoint[]> = {};
    trajectories.forEach(p => {
        if (!paths[p.label]) paths[p.label] = [];
        paths[p.label].push(p);
    });

    Object.values(paths).forEach(points => {
        if (points.length < 2) return;

        ctx.beginPath();
        const start = points[0];
        ctx.moveTo(start.x * width, start.y * height);

        for (let i = 1; i < points.length; i++) {
            const p = points[i];
            const age = Date.now() - p.timestamp;
            // Lines fade based on their age (3 seconds max)
            ctx.globalAlpha = Math.max(0, 1 - age / 3000);
            ctx.lineTo(p.x * width, p.y * height);

            // Draw a glowing head for the most recent point
            if (i === points.length - 1) {
                ctx.save();
                ctx.shadowBlur = 15;
                ctx.shadowColor = style as string;
                ctx.stroke();
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                ctx.arc(p.x * width, p.y * height, (params.dotSize || 3) * 1.5, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }
        ctx.stroke();
    });
    ctx.globalAlpha = 1;
};

const plexusParticles: any[] = [];
const drawPlexus = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, trajectories: TrajectoryPoint[]) => {
    const count = params.pointCount;
    if (plexusParticles.length !== count) {
        plexusParticles.length = 0;
        for(let i=0; i<count; i++) plexusParticles.push({ x: Math.random()*width, y: Math.random()*height, vx: (Math.random()-0.5)*params.speed, vy: (Math.random()-0.5)*params.speed });
    }

    ctx.fillStyle = style; ctx.strokeStyle = style;
    for(let i=0; i<count; i++) {
        const p = plexusParticles[i];

        // Attraction to tracked joints
        let ax = 0, ay = 0;
        trajectories.slice(-5).forEach(tp => {
            const dx = tp.x * width - p.x;
            const dy = tp.y * height - p.y;
            const d = Math.sqrt(dx*dx + dy*dy);
            if (d < 150) { ax += dx / 80; ay += dy / 80; }
        });

        p.x += p.vx + ax; p.y += p.vy + ay;
        if (p.x < 0 || p.x > width) p.vx *= -1; if (p.y < 0 || p.y > height) p.vy *= -1;

        ctx.beginPath(); ctx.arc(p.x, p.y, params.pointSize/2, 0, Math.PI*2); ctx.fill();

        for(let j=i+1; j<Math.min(i+15, count); j++) {
            const p2 = plexusParticles[j];
            const d = Math.hypot(p.x - p2.x, p.y - p2.y);
            if (d < params.linkDistance) {
                ctx.globalAlpha = 1 - d/params.linkDistance;
                ctx.lineWidth = params.lineWidth;
                ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();
            }
        }
    }
    ctx.globalAlpha = 1;
};

export const renderFrame = (
    ctx: CanvasRenderingContext2D, 
    source: HTMLImageElement | HTMLVideoElement, 
    effectId: EffectId, 
    params: any, 
    global: GlobalParams, 
    time: number, 
    trajectories: TrajectoryPoint[] = []
) => {
    const width = ctx.canvas.width; const height = ctx.canvas.height;
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, width, height);

    // Fit source to full frame
    const sw = source instanceof HTMLVideoElement ? source.videoWidth : source.naturalWidth;
    const sh = source instanceof HTMLVideoElement ? source.videoHeight : source.naturalHeight;
    const sAspect = sw / sh;
    const targetW = height * sAspect;
    const offsetX = (width - targetW) / 2;
    ctx.drawImage(source, offsetX, 0, targetW, height);

    const style = getEffectStyle(ctx, width, height, global.effectColor, global.gradientPreset);

    switch(effectId) {
        case 'pixel': drawPixel(ctx, width, height, params, trajectories, source); break;
        case 'halftone': drawHalftone(ctx, width, height, params, style, trajectories); break;
        case 'matrix': drawMatrix(ctx, width, height, params, style, time, trajectories); break;
        case 'line': drawLine(ctx, width, height, params, style, trajectories); break;
        case 'plexus': drawPlexus(ctx, width, height, params, style, trajectories); break;
    }

    if (global.bw) {
        ctx.save(); ctx.globalCompositeOperation = 'saturation';
        ctx.fillStyle = 'black'; ctx.fillRect(0,0,width,height); ctx.restore();
    }
    if (global.invert) {
        ctx.save(); ctx.globalCompositeOperation = 'difference';
        ctx.fillStyle = 'white'; ctx.fillRect(0,0,width,height); ctx.restore();
    }
};

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef } from './types';
import { hslToHex } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  const handleAiAnalyze = (analysis: any) => {
    const newGlobal = { 
      ...globalParams, 
      hue: analysis.hue || 0, 
      saturation: analysis.saturation || 100,
      effectColor: hslToHex(analysis.hue || 0, analysis.saturation || 100, 50)
    };
    setGlobalParams(newGlobal);
    const target = EFFECTS.find(e => e.id.toLowerCase() === analysis.effect?.toLowerCase()) || EFFECTS[0];
    setActiveEffect(target);
    setEffectParams(target.defaultParams);
  };

  const handleUpload = (file: File) => {
    if (mediaSrc) URL.revokeObjectURL(mediaSrc);
    setMediaSrc(URL.createObjectURL(file));
    setIsVideo(file.type.startsWith('video'));
  };

  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={() => {}} 
          isCleanFeed={true}
        />
      </div>
    );
  }

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden">
      <div className="absolute inset-0 z-0">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onAiAnalyze={handleAiAnalyze}
          onExportStateChange={setIsExporting}
        />
      </div>

      <div className="relative z-10 h-full w-full pointer-events-none flex flex-col justify-between">
        <div className="pointer-events-auto bg-gradient-to-b from-white/90 to-transparent">
          <Header onExport={() => rendererRef.current?.startExport()} onAir={() => window.open(window.location.href + '?view=onair', '_blank')} isExporting={isExporting} />
        </div>

        <div className="w-full px-8 pb-10 pointer-events-auto">
          <div className="max-w-[1440px] mx-auto">
            <ControlPanel globalParams={globalParams} setGlobalParams={setGlobalParams} activeEffect={activeEffect} effectParams={effectParams} setEffectParams={setEffectParams} allEffects={EFFECTS} onSelectEffect={e => { setActiveEffect(e); setEffectParams(e.defaultParams); }} isVideo={isVideo} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

export type EffectId = 'plexus' | 'pixel' | 'halftone' | 'matrix' | 'line';

export type ApplyMode = 'subject' | 'background' | 'both';

// Fix: Added missing TrajectoryPoint interface used for tracking movement history
export interface TrajectoryPoint {
  x: number;
  y: number;
  label: string;
  timestamp: number;
}

export interface GlobalParams {
  hue: number;
  saturation: number;
  lightness: number;
  effectColor: string;
  gradientPreset: number; // 0 for solid, 1-5 for presets
  bw: boolean;
  xray: boolean;
  thermal: boolean;
  invert: boolean;
  dramaticWarm: boolean;
  dramaticCool: boolean;
  mixMode: boolean;
  applyTo: ApplyMode;
  maskStrength: number;
  maskThreshold: number; 
  autoTracking: boolean; 
}

