const CHAR_SETS = {
    en: 'abcdefghijklmnopqrstuvwxyz0123456789',
    jp: 'あいうえおかきくけ코サシス세소12345',
    kr: '가나다라마바사아자차카타파하12345',
    cn: '你好世界数字代码计算机数据',
    ar: 'ابجديةعربية١٢٣٤٥',
    numbers: '0123456789'
};

const getChar = (lang: string, onlyNumbers: boolean = false) => {
    let charset = CHAR_SETS.en;
    if (onlyNumbers) {
        charset = CHAR_SETS.numbers;
    } else if (lang === 'random') {
        const keys = Object.keys(CHAR_SETS).filter(k => k !== 'numbers');
        charset = CHAR_SETS[keys[Math.floor(Math.random() * keys.length)] as keyof typeof CHAR_SETS];
    } else {
        charset = CHAR_SETS[lang as keyof typeof CHAR_SETS] || CHAR_SETS.en;
    }
    return charset[Math.floor(Math.random() * charset.length)];
};

// Utility to draw a vector-style mouse cursor
const drawArrowCursor = (ctx: CanvasRenderingContext2D, x: number, y: number, size: number) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(size / 10, size / 10);
    // Rotating slightly for the classic tilted mouse cursor look
    ctx.rotate(-Math.PI / 8); 

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, 15);
    ctx.lineTo(4, 11);
    ctx.lineTo(7, 17);
    ctx.lineTo(9, 16);
    ctx.lineTo(6, 10);
    ctx.lineTo(11, 10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
};

const getEffectStyle = (ctx: CanvasRenderingContext2D, width: number, height: number, color: string, presetIdx: number) => {
    if (presetIdx === 0) return color;
    const presets = [
        null,
        ['#ff00ff', '#00ffff'],
        ['#ff5f6d', '#ffc371'],
        ['#11998e', '#38ef7d'],
        ['#2193b0', '#6dd5ed'],
        ['#6441A5', '#2a0845']
    ];
    const colors = presets[presetIdx];
    if (!colors) return color;
    const grad = ctx.createLinearGradient(0, 0, width, height);
    grad.addColorStop(0, colors[0]);
    grad.addColorStop(1, colors[1]);
    return grad;
};

const drawPixel = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, time: number) => {
  const baseSize = params.pixelSize || 8;
  const variance = params.sizeVariance || 0;
  const wave = (Math.sin(time * 5.0) + Math.sin(time * 2.3) * 0.5) / 1.5;
  const maxSteps = 5;
  const currentStep = Math.round(wave * (variance * maxSteps));
  const offset = currentStep * 4;
  let size = baseSize + offset;
  size = Math.max(4, Math.round(size / 4) * 4);
  const w = Math.ceil(width / size);
  const h = Math.ceil(height / size);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(ctx.canvas, 0, 0, width, height, 0, 0, w, h);
  ctx.drawImage(ctx.canvas, 0, 0, w, h, 0, 0, width, height);
};

const drawHalftone = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient) => {
  const dotSize = Math.max(2, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;
  const len = data.length;
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = style;
  const rand = params.dotSizeRandom || 0;

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (Math.floor(y) * width + Math.floor(x)) * 4;
      if (i < len) {
        const lum = (0.299 * data[i] + 0.587 * data[i+1] + 0.114 * data[i+2]) / 255;
        const rFactor = 1 - Math.random() * rand;
        const radius = (dotSize * 0.5) * lum * rFactor;
        if (radius > 0.5) {
          ctx.beginPath();
          ctx.arc(x + dotSize * 0.5, y + dotSize * 0.5, radius, 0, 6.283);
          ctx.fill();
        }
      }
    }
  }
};

const drawMatrix = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number) => {
    ctx.fillStyle = style;
    const fSize = params.fontSize || 10;
    const charSpacingX = fSize * 0.7; 
    const charSpacingY = fSize * 0.8; 
    ctx.font = `bold ${fSize}px monospace`;
    const cols = Math.floor(width / charSpacingX);
    const speed = params.fallSpeed * 15;
    const tailLength = 12; 

    for (let i = 0; i < cols; i++) {
        const offset = (i * 157.31) % height; 
        const headY = (time * speed + offset) % height;

        if (Math.random() > (1 - params.density/450)) {
            for (let j = 0; j < tailLength; j++) {
                const y = (headY - j * charSpacingY + height) % height;
                const alpha = Math.pow(0.82, j); 

                ctx.globalAlpha = j === 0 ? 1 : alpha * 0.8;
                const char = getChar(params.language, params.showNumbers);
                ctx.fillText(char, i * charSpacingX, y);
            }
        }
    }
    ctx.globalAlpha = 1;
};

const plexusParticles: {x: number, y: number, vx: number, vy: number, noise: number, id: string, sizeFactor: number}[] = [];

const drawPlexus = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, mask: ImageData | null, time: number) => {
  const count = params.pointCount;
  const linkDistSq = params.linkDistance * params.linkDistance;

  const getSpawn = () => {
    for(let k=0; k<20; k++) {
        const rx = Math.random() * width; const ry = Math.random() * height;
        if (mask) {
            const mx = Math.floor((rx/width)*mask.width); const my = Math.floor((ry/height)*mask.height);
            const midx = (my * mask.width + mx) * 4;
            if (mask.data[midx] > 128) return {x: rx, y: ry};
        } else return {x: rx, y: ry};
    }
    return {x: Math.random() * width, y: Math.random() * height};
  };

  if (plexusParticles.length !== count) {
    plexusParticles.length = 0;
    for(let i=0; i<count; i++) {
        const p = getSpawn();
        plexusParticles.push({ 
            ...p, 
            vx: (Math.random()-0.5)*params.speed, 
            vy: (Math.random()-0.5)*params.speed, 
            noise: Math.random()*100, 
            id: Math.floor(Math.random() * 9999).toString().padStart(4, '0'),
            sizeFactor: 0.5 + Math.random() 
        });
    }
  }

  ctx.strokeStyle = style;
  ctx.fillStyle = style;

  for(let i=0; i<count; i++) {
    const p = plexusParticles[i];
    p.x += p.vx; p.y += p.vy;
    let needsReset = false;
    if (mask) {
        const mx = Math.floor((p.x/width)*mask.width); const my = Math.floor((p.y/height)*mask.height);
        const midx = (my * mask.width + mx) * 4;
        if (p.x < 0 || p.x > width || p.y < 0 || p.y > height || (mask.data && mask.data[midx] < 128)) needsReset = true;
    } else {
        if (p.x < 0 || p.x > width) p.vx *= -1; if (p.y < 0 || p.y > height) p.vy *= -1;
    }
    if (needsReset) { const s = getSpawn(); p.x = s.x; p.y = s.y; }

    const rx = p.x + Math.sin(time + p.noise)*params.jitter;
    const ry = p.y + Math.cos(time + p.noise)*params.jitter;

    // Vector Lines - Sharp and technical
    for(let j=i+1; j<Math.min(i+15, count); j++) {
        const p2 = plexusParticles[j];
        const p2rx = p2.x + Math.sin(time + p2.noise)*params.jitter;
        const p2ry = p2.y + Math.cos(time + p2.noise)*params.jitter;
        const dx = rx - p2rx; const dy = ry - p2ry;
        const d2 = dx*dx + dy*dy;
        if (d2 < linkDistSq) {
            const alpha = 1 - (d2/linkDistSq);
            ctx.globalAlpha = alpha * 0.7; // Higher visibility for sharp vector look
            ctx.lineWidth = params.lineWidth * (1.5 - (d2/linkDistSq));
            ctx.beginPath();
            ctx.moveTo(rx, ry);
            ctx.lineTo(p2rx, p2ry);
            ctx.stroke();
        }
    }

    // Vector Nodes (Squares)
    ctx.globalAlpha = 1.0;
    const pSize = params.pointSize * (1 + (p.sizeFactor - 1) * params.pointSizeRandom);

    ctx.fillRect(rx - pSize / 2, ry - pSize / 2, pSize, pSize);

    // Crosshair style for specific nodes (Technical feel)
    if (i % 12 === 0) {
        ctx.save();
        ctx.globalAlpha = 0.5;
        ctx.lineWidth = 0.5;
        const chSize = pSize * 5;
        ctx.beginPath();
        ctx.moveTo(rx - chSize, ry); ctx.lineTo(rx + chSize, ry);
        ctx.moveTo(rx, ry - chSize); ctx.lineTo(rx, ry + chSize);
        ctx.stroke();
        ctx.restore();
    }

    if (params.showNumbers) {
        ctx.save();
        ctx.font = 'bold 8px monospace';
        ctx.globalAlpha = 0.8;
        ctx.fillText(`ID:${p.id}`, rx + 8, ry - 8);
        ctx.restore();
    }
  }
  ctx.globalAlpha = 1.0;
};

const drawLine = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient) => {
    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;
    const bgData = new Uint8ClampedArray(data);

    // Invert snapshot for the background base
    for (let i = 0; i < bgData.length; i += 4) {
        bgData[i] = 255 - data[i];
        bgData[i+1] = 255 - data[i+1];
        bgData[i+2] = 255 - data[i+2];
    }
    ctx.putImageData(new ImageData(bgData, width, height), 0, 0);

    ctx.fillStyle = style;
    const r = params.dotRandom || 0;
    const step = 4; // Slightly larger step for clearer cursor distribution
    const threshold = params.threshold;
    const cSize = params.dotSize || 2.5;
    const shape = params.shapeType || 'arrow';

    for (let y = 0; y < height; y += step) {
        for (let x = 0; x < width; x += step) {
            const i = (y * width + x) * 4;
            const iNext = (y * width + (x+1)) * 4;
            if (iNext < data.length) {
                const l1 = (0.299 * data[i] + 0.587 * data[i+1] + 0.114 * data[i+2]);
                const l2 = (0.299 * data[iNext] + 0.587 * data[iNext+1] + 0.114 * data[iNext+2]);

                if (Math.abs(l1 - l2) > threshold) {
                    const finalSize = cSize * (4.5 - Math.random() * r * 4); // Scale up for visual impact
                    if (shape === 'dot') {
                        ctx.beginPath();
                        ctx.arc(x, y, finalSize / 2, 0, Math.PI * 2);
                        ctx.fill();
                    } else if (shape === 'square') {
                        ctx.fillRect(x - finalSize/2, y - finalSize/2, finalSize, finalSize);
                    } else {
                        drawArrowCursor(ctx, x, y, finalSize);
                    }
                }
            }
        }
    }
};

const applyPostFilters = (ctx: CanvasRenderingContext2D, width: number, height: number, global: GlobalParams) => {
    if (!global.bw && !global.xray && !global.thermal && !global.invert && !global.dramaticWarm && !global.dramaticCool) return;
    const img = ctx.getImageData(0, 0, width, height);
    const d = img.data;
    const len = d.length;
    for(let i=0; i < len; i+=4) {
        let r = d[i], g = d[i+1], b = d[i+2];
        if (global.bw) { const l = 0.299 * r + 0.587 * g + 0.114 * b; r=g=b=l; }
        if (global.xray) { r=255-r; g=255-g; b=255-b; }
        if (global.thermal) {
            const l = (0.299 * r + 0.587 * g + 0.114 * b)/255;
            if (l < 0.33) { r=0; g=0; b=l*765; }
            else if (l < 0.66) { r=(l-0.33)*765; g=255; b=255-(l-0.33)*765; }
            else { r=255; g=255-(l-0.66)*765; b=0; }
        }
        if (global.dramaticWarm) { r *= 1.2; b *= 0.8; }
        if (global.dramaticCool) { r *= 0.8; b *= 1.2; }
        if (global.invert) { r=255-r; g=255-g; b=255-b; }

        d[i]=Math.min(255, Math.max(0, r)); 
        d[i+1]=Math.min(255, Math.max(0, g)); 
        d[i+2]=Math.min(255, Math.max(0, b));
    }
    ctx.putImageData(img, 0, 0);
};

export const renderFrame = (ctx: CanvasRenderingContext2D, source: HTMLImageElement | HTMLVideoElement, effectId: EffectId, params: any, global: GlobalParams, time: number, aiMask?: ImageData | null) => {
    const width = ctx.canvas.width; const height = ctx.canvas.height;
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, width, height);

    const sw = source instanceof HTMLVideoElement ? source.videoWidth : source.naturalWidth;
    const sh = source instanceof HTMLVideoElement ? source.videoHeight : source.naturalHeight;
    const sAspect = sw / sh; const dAspect = width / height;
    let drawW, drawH, drawX, drawY;
    if (sAspect > dAspect) { drawH = height; drawW = height * sAspect; drawX = (width - drawW) / 2; drawY = 0; }
    else { drawW = width; drawH = width / sAspect; drawX = 0; drawY = (height - drawH) / 2; }

    ctx.drawImage(source, drawX, drawY, drawW, drawH);
    applyPostFilters(ctx, width, height, global);

    let filteredBgSnapshot: ImageData | null = null;
    if (global.applyTo !== 'both') {
        filteredBgSnapshot = ctx.getImageData(0, 0, width, height);
    }

    const effectCanvas = document.createElement('canvas');
    effectCanvas.width = width; effectCanvas.height = height;
    const effectCtx = effectCanvas.getContext('2d')!;
    effectCtx.drawImage(ctx.canvas, 0, 0);

    const style = getEffectStyle(effectCtx, width, height, global.effectColor, global.gradientPreset);

    switch(effectId) {
        case 'pixel': drawPixel(effectCtx, width, height, params, time); break;
        case 'halftone': drawHalftone(effectCtx, width, height, params, style); break;
        case 'matrix': drawMatrix(effectCtx, width, height, params, style, time); break;
        case 'plexus': drawPlexus(effectCtx, width, height, params, style, aiMask || null, time); break;
        case 'line': drawLine(effectCtx, width, height, params, style); break;
    }

    if (global.applyTo !== 'both' && aiMask && filteredBgSnapshot) {
        const effectImg = effectCtx.getImageData(0, 0, width, height);
        const out = ctx.createImageData(width, height);
        const ed = effectImg.data;
        const bd = filteredBgSnapshot.data;
        const od = out.data;
        const mw = aiMask.width; const mh = aiMask.height; const md = aiMask.data;

        for(let y=0; y<height; y++) {
            const rowIdx = y * width;
            const mRowIdx = Math.floor((y/height)*mh) * mw;
            for(let x=0; x<width; x++) {
                const i = (rowIdx + x) * 4;
                const mi = (mRowIdx + Math.floor((x/width)*mw)) * 4;
                const isSub = md[mi] > 128;
                const useEffect = global.applyTo === 'subject' ? isSub : !isSub;
                if (useEffect) { od[i]=ed[i]; od[i+1]=ed[i+1]; od[i+2]=ed[i+2]; od[i+3]=255; }
                else { od[i]=bd[i]; od[i+1]=bd[i+1]; od[i+2]=bd[i+2]; od[i+3]=255; }
            }
        }
        ctx.putImageData(out, 0, 0);
    } else {
        ctx.drawImage(effectCanvas, 0, 0);
    }
};

import React from 'react';
import { GlobalParams, EffectDef, ParamConfig } from '../types';
import { hslToHex } from '../services/utils';
import { CheckSquare, Square, Zap, Target, SlidersHorizontal } from 'lucide-react';

interface ControlPanelProps {
  globalParams: GlobalParams;
  setGlobalParams: (p: GlobalParams) => void;
  activeEffect: EffectDef;
  effectParams: any;
  setEffectParams: (p: any) => void;
  allEffects: EffectDef[];
  onSelectEffect: (e: EffectDef) => void;
  isVideo: boolean;
}

const ControlPanel: React.FC<ControlPanelProps> = ({
  globalParams, setGlobalParams, activeEffect, effectParams, setEffectParams, allEffects, onSelectEffect
}) => {
  const updateGlobal = (key: keyof GlobalParams, val: any) => setGlobalParams({ ...globalParams, [key]: val });
  const updateEffect = (key: string, val: any) => setEffectParams({ ...effectParams, [key]: val });

  const handleHSLChange = (key: 'hue' | 'saturation' | 'lightness', val: number) => {
      const nextParams = { ...globalParams, [key]: val };
      const hex = hslToHex(nextParams.hue, nextParams.saturation, nextParams.lightness);
      setGlobalParams({ ...nextParams, effectColor: hex, gradientPreset: 0 });
  };

  return (
    <div className="flex flex-col gap-3 w-full animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Parameters Panel */}
      <div className="bg-zinc-900/30 backdrop-blur-xl border border-white/10 rounded-[40px] p-8 px-10 flex flex-col gap-6 shadow-xl shadow-black/20">
         <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-1">
            {allEffects.map((eff) => (
                <button
                    key={eff.id} onClick={() => onSelectEffect(eff)}
                    className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeEffect.id === eff.id ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white hover:bg-white/20 border border-white/10'}`}
                >
                    {eff.name}
                </button>
            ))}
         </div>

         <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-x-10 gap-y-6">
             {(Object.entries(activeEffect.paramConfig) as [string, ParamConfig][]).map(([key, config]) => (
                 <div key={key} className="flex flex-col gap-2 min-w-[120px]">
                     <div className="flex justify-between text-[8px] font-black text-white/60 uppercase tracking-widest">
                         <span>{key}</span>
                         <span className="text-white">{typeof effectParams[key] === 'boolean' ? '' : effectParams[key]}</span>
                     </div>
                     {config.type === 'slider' ? (
                         <input type="range" min={config.min} max={config.max} step={config.step} value={effectParams[key]} onChange={(e) => updateEffect(key, parseFloat(e.target.value))} className="w-full h-1 bg-white/20 rounded-full appearance-none accent-white cursor-pointer" />
                     ) : config.type === 'select' ? (
                         <div className="flex gap-1 bg-black/40 p-0.5 rounded-lg border border-white/10 overflow-hidden">
                             {config.options?.map(o => (
                                 <button
                                     key={o}
                                     onClick={() => updateEffect(key, o)}
                                     className={`flex-1 px-2 py-1.5 rounded-md text-[8px] font-black uppercase transition-all ${effectParams[key] === o ? 'bg-white text-zinc-900' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
                                 >
                                     {o}
                                 </button>
                             ))}
                         </div>
                     ) : (
                         <button onClick={() => updateEffect(key, !effectParams[key])} className={`flex items-center gap-2 text-[9px] font-bold uppercase transition-all ${effectParams[key] ? 'text-white' : 'text-white/40 hover:text-white'}`}>
                             {effectParams[key] ? <CheckSquare size={14} className="fill-white text-zinc-900" /> : <Square size={14}/>} {key}
                         </button>
                     )}
                 </div>
             ))}
         </div>
      </div>

      {/* Global Toolbar */}
      <div className="bg-zinc-900/30 backdrop-blur-xl border border-white/10 rounded-full p-3 px-10 flex items-center justify-between gap-8 shadow-xl shadow-black/20">
            <div className="flex items-center gap-10">
                {/* HSL Slider Controls */}
                <div className="flex items-center gap-6">
                    <SlidersHorizontal size={14} className="text-white/40" />

                    {/* Hue */}
                    <div className="flex flex-col gap-1 w-32">
                        <div className="flex justify-between text-[7px] font-black text-white/40 uppercase tracking-widest">
                            <span>Hue</span>
                            <span className="text-white">{Math.round(globalParams.hue)}°</span>
                        </div>
                        <input 
                            type="range" min="0" max="360" value={globalParams.hue} 
                            onChange={(e) => handleHSLChange('hue', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer"
                            style={{ background: 'linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)' }}
                        />
                    </div>

                    {/* Saturation */}
                    <div className="flex flex-col gap-1 w-24">
                        <div className="flex justify-between text-[7px] font-black text-white/40 uppercase tracking-widest">
                            <span>Sat</span>
                            <span className="text-white">{Math.round(globalParams.saturation)}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" value={globalParams.saturation} 
                            onChange={(e) => handleHSLChange('saturation', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer bg-white/10"
                        />
                    </div>

                    {/* Lightness */}
                    <div className="flex flex-col gap-1 w-24">
                        <div className="flex justify-between text-[7px] font-black text-white/40 uppercase tracking-widest">
                            <span>Lum</span>
                            <span className="text-white">{Math.round(globalParams.lightness)}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" value={globalParams.lightness} 
                            onChange={(e) => handleHSLChange('lightness', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer bg-white/10"
                        />
                    </div>
                </div>

                <div className="h-6 w-px bg-white/10" />

                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1.5 border-r border-white/10 pr-3">
                        {[
                          { key: 'bw', label: 'B&W' },
                          { key: 'xray', label: 'X-Ray' },
                          { key: 'thermal', label: 'Thermal' },
                          { key: 'dramaticWarm', label: 'Warm' },
                          { key: 'dramaticCool', label: 'Cool' }
                        ].map((f) => (
                          <button 
                            key={f.key}
                            onClick={() => updateGlobal(f.key as keyof GlobalParams, !globalParams[f.key as keyof GlobalParams])} 
                            className={`px-5 py-2 rounded-full text-[9px] font-black transition-all border ${globalParams[f.key as keyof GlobalParams] ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white border-white/10 hover:border-white/40 hover:bg-white/20'}`}
                          >
                            {f.label}
                          </button>
                        ))}
                    </div>

                    <button 
                      onClick={() => updateGlobal('invert', !globalParams.invert)} 
                      className={`flex items-center gap-2 px-4 py-2 rounded-full text-[9px] font-black uppercase transition-all ${globalParams.invert ? 'text-white' : 'text-white/40 hover:text-white'}`}
                    >
                      {globalParams.invert ? <CheckSquare size={16} className="fill-white text-zinc-900" /> : <Square size={16}/>}
                      Invert
                    </button>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <button 
                  onClick={() => updateGlobal('autoTracking', !globalParams.autoTracking)} 
                  className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[9px] font-black uppercase transition-all border ${globalParams.autoTracking ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white border border-white/10 hover:bg-white/20'}`}
                >
                  <Target size={14} className={globalParams.autoTracking ? 'text-indigo-400 animate-pulse' : ''}/>
                  Tracking
                </button>

                <div className="flex bg-white/10 rounded-full p-1 border border-white/10">
                    {['subject', 'background', 'both'].map(m => (
                        <button key={m} onClick={() => updateGlobal('applyTo', m)} className={`px-6 py-2 rounded-full text-[8px] font-black uppercase transition-all ${globalParams.applyTo === m ? 'bg-white text-zinc-900 border border-white/10 shadow-sm' : 'text-white/60 hover:text-white'}`}>{m}</button>
                    ))}
                </div>
                <button 
                  onClick={() => updateGlobal('mixMode', !globalParams.mixMode)} 
                  className={`flex items-center gap-3 px-6 py-2.5 rounded-full text-[9px] font-black uppercase transition-all ${globalParams.mixMode ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white border border-white/10 hover:bg-white/20'}`}
                >
                  <Zap size={14} className={globalParams.mixMode ? 'animate-pulse text-yellow-400 fill-yellow-400' : ''}/>
                  Mix
                </button>
            </div>
      </div>
    </div>
  );
};

