import React from 'react';
import { GlobalParams, EffectDef, ParamConfig } from '../types';
import { hslToHex } from '../services/utils';
import { 
  CheckSquare, 
  Square, 
  Zap, 
  Target, 
  SlidersHorizontal, 
  MousePointer2, 
  Circle, 
  Square as SquareIcon,
  Hash,
  Type,
  Palette
} from 'lucide-react';

interface ControlPanelProps {
  globalParams: GlobalParams;
  setGlobalParams: (p: GlobalParams) => void;
  activeEffect: EffectDef;
  effectParams: any;
  setEffectParams: (p: any) => void;
  allEffects: EffectDef[];
  onSelectEffect: (e: EffectDef) => void;
  isVideo: boolean;
}

const ControlPanel: React.FC<ControlPanelProps> = ({
  globalParams, setGlobalParams, activeEffect, effectParams, setEffectParams, allEffects, onSelectEffect
}) => {
  const updateGlobal = (key: keyof GlobalParams, val: any) => setGlobalParams({ ...globalParams, [key]: val });
  const updateEffect = (key: string, val: any) => setEffectParams({ ...effectParams, [key]: val });

  const handleHSLChange = (key: 'hue' | 'saturation' | 'lightness', val: number) => {
      const nextParams = { ...globalParams, [key]: val };
      const hex = hslToHex(nextParams.hue, nextParams.saturation, nextParams.lightness);
      setGlobalParams({ ...nextParams, effectColor: hex, gradientPreset: 0 });
  };

  const renderOptionContent = (key: string, option: string) => {
    if (key === 'shapeType') {
      if (option === 'arrow') return <MousePointer2 size={12} />;
      if (option === 'dot') return <Circle size={8} className="fill-current" />;
      if (option === 'square') return <SquareIcon size={10} className="fill-current" />;
      if (option === 'number') return <Hash size={12} />;
      if (option === 'alphabet') return <Type size={12} />;
    }
    return option;
  };

  return (
    <div className="flex flex-col gap-3 w-full animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Parameters Panel */}
      <div className="bg-zinc-900/30 backdrop-blur-xl border border-white/10 rounded-[40px] p-8 px-10 flex flex-col gap-8 shadow-xl shadow-black/20">
         {/* Effect Selection Tabs - Left Aligned */}
         <div className="flex items-center justify-start gap-2 overflow-x-auto no-scrollbar">
            {allEffects.map((eff) => (
                <button
                    key={eff.id} onClick={() => onSelectEffect(eff)}
                    className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeEffect.id === eff.id ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white hover:bg-white/20 border border-white/10'}`}
                >
                    {eff.name}
                </button>
            ))}
         </div>

         {/* Parameters Horizontal Alignment - Left Aligned */}
         <div className="flex flex-row flex-wrap justify-start items-start gap-x-12 gap-y-8">
             {(Object.entries(activeEffect.paramConfig) as [string, ParamConfig][]).map(([key, config]) => {
                 const isShapeType = key === 'shapeType';
                 const isShowNumbers = key === 'showNumbers';
                 return (
                    <div key={key} className="relative flex flex-col items-start min-w-[140px]">
                        {/* Label Container - Left Aligned, hidden for showNumbers as requested */}
                        <div className="h-4 flex items-center justify-start mb-2 w-full">
                            {!isShapeType && !isShowNumbers && (
                                <div className="flex justify-start gap-2 text-[8px] font-black text-white/40 uppercase tracking-widest">
                                    <span>{key}</span>
                                    <span className="text-white/80">{typeof effectParams[key] === 'boolean' ? '' : effectParams[key]}</span>
                                </div>
                            )}
                        </div>

                        {/* Control Elements - Left Aligned */}
                        <div className="flex items-center justify-start w-full h-8">
                            {config.type === 'slider' ? (
                                <input 
                                    type="range" 
                                    min={config.min} 
                                    max={config.max} 
                                    step={config.step} 
                                    value={effectParams[key]} 
                                    onChange={(e) => updateEffect(key, parseFloat(e.target.value))} 
                                    className="w-full h-1 bg-white/20 rounded-full appearance-none accent-white cursor-pointer" 
                                />
                            ) : config.type === 'select' ? (
                                <div className="flex w-full gap-1 bg-black/40 p-1 rounded-full border border-white/10 overflow-hidden">
                                    {config.options?.map(o => (
                                        <button
                                            key={o}
                                            onClick={() => updateEffect(key, o)}
                                            className={`flex-1 flex items-center justify-center h-6 rounded-full text-[8px] font-black uppercase transition-all ${effectParams[key] === o ? 'bg-white text-zinc-900' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
                                        >
                                            {renderOptionContent(key, o)}
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                <button 
                                    onClick={() => updateEffect(key, !effectParams[key])} 
                                    className={`flex items-center justify-start gap-2 px-4 py-2 rounded-full text-[9px] font-bold uppercase transition-all border ${effectParams[key] ? 'bg-white/10 text-white border-white/20' : 'text-white/40 border-transparent hover:text-white'}`}
                                >
                                    {effectParams[key] ? <CheckSquare size={14} className="fill-white text-zinc-900" /> : <Square size={14}/>} 
                                    <span className="ml-1">{key}</span>
                                </button>
                            )}
                        </div>
                    </div>
                 );
             })}
         </div>
      </div>

      {/* Global Toolbar */}
      <div className="bg-zinc-900/30 backdrop-blur-xl border border-white/10 rounded-full p-3 px-10 flex items-center justify-between gap-8 shadow-xl shadow-black/20">
            <div className="flex items-center gap-10">
                <div className="flex items-center gap-6">
                    <SlidersHorizontal size={14} className="text-white/40" />

                    {/* Hue */}
                    <div className="flex flex-col gap-1 w-32">
                        <div className="flex justify-between text-[7px] font-black text-white/40 uppercase tracking-widest">
                            <span>Hue</span>
                            <span className="text-white">{Math.round(globalParams.hue)}°</span>
                        </div>
                        <input 
                            type="range" min="0" max="360" value={globalParams.hue} 
                            onChange={(e) => handleHSLChange('hue', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer"
                            style={{ background: 'linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)' }}
                        />
                    </div>

                    {/* Saturation */}
                    <div className="flex flex-col gap-1 w-24">
                        <div className="flex justify-between text-[7px] font-black text-white/40 uppercase tracking-widest">
                            <span>Sat</span>
                            <span className="text-white">{Math.round(globalParams.saturation)}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" value={globalParams.saturation} 
                            onChange={(e) => handleHSLChange('saturation', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer bg-white/10"
                        />
                    </div>

                    {/* Lightness */}
                    <div className="flex flex-col gap-1 w-24">
                        <div className="flex justify-between text-[7px] font-black text-white/40 uppercase tracking-widest">
                            <span>Lum</span>
                            <span className="text-white">{Math.round(globalParams.lightness)}%</span>
                        </div>
                        <input 
                            type="range" min="0" max="100" value={globalParams.lightness} 
                            onChange={(e) => handleHSLChange('lightness', parseInt(e.target.value))}
                            className="w-full h-1.5 rounded-full appearance-none cursor-pointer bg-white/10"
                        />
                    </div>

                    {/* Color MIX Button */}
                    <button 
                      onClick={() => updateGlobal('colorMix', !globalParams.colorMix)} 
                      className={`flex items-center gap-2 px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-wider transition-all border ${globalParams.colorMix ? 'bg-white text-zinc-900 border-white animate-pulse' : 'bg-white/10 text-white border-white/10 hover:bg-white/20'}`}
                    >
                      <Palette size={14} className={globalParams.colorMix ? 'text-indigo-500' : ''} />
                      Color MIX
                    </button>
                </div>

                <div className="h-6 w-px bg-white/10" />

                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1.5 border-r border-white/10 pr-3">
                        {[
                          { key: 'bw', label: 'B&W' },
                          { key: 'xray', label: 'X-Ray' },
                          { key: 'thermal', label: 'Thermal' },
                          { key: 'dramaticWarm', label: 'Warm' },
                          { key: 'dramaticCool', label: 'Cool' }
                        ].map((f) => (
                          <button 
                            key={f.key}
                            onClick={() => updateGlobal(f.key as keyof GlobalParams, !globalParams[f.key as keyof GlobalParams])} 
                            className={`px-5 py-2 rounded-full text-[9px] font-black transition-all border ${globalParams[f.key as keyof GlobalParams] ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white border-white/10 hover:border-white/40 hover:bg-white/20'}`}
                          >
                            {f.label}
                          </button>
                        ))}
                    </div>

                    <button 
                      onClick={() => updateGlobal('invert', !globalParams.invert)} 
                      className={`flex items-center gap-2 px-4 py-2 rounded-full text-[9px] font-black uppercase transition-all ${globalParams.invert ? 'text-white' : 'text-white/40 hover:text-white'}`}
                    >
                      {globalParams.invert ? <CheckSquare size={16} className="fill-white text-zinc-900" /> : <SquareIcon size={16}/>}
                      Invert
                    </button>
                </div>
            </div>

            <div className="flex items-center gap-6">
                <button 
                  onClick={() => updateGlobal('autoTracking', !globalParams.autoTracking)} 
                  className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-[9px] font-black uppercase transition-all border ${globalParams.autoTracking ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white border border-white/10 hover:bg-white/20'}`}
                >
                  <Target size={14} className={globalParams.autoTracking ? 'text-indigo-400 animate-pulse' : ''}/>
                  Tracking
                </button>

                <div className="flex bg-white/10 rounded-full p-1 border border-white/10">
                    {['subject', 'background', 'both'].map(m => (
                        <button key={m} onClick={() => updateGlobal('applyTo', m)} className={`px-6 py-2 rounded-full text-[8px] font-black uppercase transition-all ${globalParams.applyTo === m ? 'bg-white text-zinc-900 border border-white/10 shadow-sm' : 'text-white/60 hover:text-white'}`}>{m}</button>
                    ))}
                </div>
                <button 
                  onClick={() => updateGlobal('mixMode', !globalParams.mixMode)} 
                  className={`flex items-center gap-3 px-6 py-2.5 rounded-full text-[9px] font-black uppercase transition-all ${globalParams.mixMode ? 'bg-white text-zinc-900 border-white' : 'bg-white/10 text-white border border-white/10 hover:bg-white/20'}`}
                >
                  <Zap size={14} className={globalParams.mixMode ? 'animate-pulse text-yellow-400 fill-yellow-400' : ''}/>
                  Mix
                </button>
            </div>
      </div>
    </div>
  );
};

export default ControlPanel;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt, hslToHex } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const syncChannel = useMemo(() => new BroadcastChannel('visual-parameter-sync'), []);

  // Detect ON AIR mode from URL query parameters
  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  // 1. Broadcast state changes from the Main Window to all listening ON AIR windows
  useEffect(() => {
    if (!isOnAirView) {
      const state = {
        type: 'STATE_UPDATE',
        mediaSrc,
        isVideo,
        globalParams,
        activeEffectId: activeEffect.id,
        effectParams
      };
      syncChannel.postMessage(state);
    }
  }, [mediaSrc, isVideo, globalParams, activeEffect, effectParams, isOnAirView, syncChannel]);

  // 2. Handle Synchronization Logic (Handshake and Updates)
  useEffect(() => {
    const handleMessage = (e: MessageEvent) => {
      const data = e.data;

      if (isOnAirView) {
        // ON AIR Window: Listen for incoming state updates from the controller
        if (data.type === 'STATE_UPDATE') {
          if (data.mediaSrc !== undefined) setMediaSrc(data.mediaSrc);
          if (data.isVideo !== undefined) setIsVideo(data.isVideo);
          if (data.globalParams !== undefined) setGlobalParams(data.globalParams);
          if (data.activeEffectId !== undefined) {
            const effect = EFFECTS.find(eff => eff.id === data.activeEffectId);
            if (effect) setActiveEffect(effect);
          }
          if (data.effectParams !== undefined) setEffectParams(data.effectParams);
        }
      } else {
        // Main Window: Listen for "REQUEST_SYNC" from newly opened ON AIR windows
        if (data.type === 'REQUEST_SYNC') {
          syncChannel.postMessage({
            type: 'STATE_UPDATE',
            mediaSrc,
            isVideo,
            globalParams,
            activeEffectId: activeEffect.id,
            effectParams
          });
        }
      }
    };

    syncChannel.onmessage = handleMessage;

    // If this instance is the ON AIR view, request the initial state from the main window immediately
    if (isOnAirView) {
      syncChannel.postMessage({ type: 'REQUEST_SYNC' });
    }

    return () => { syncChannel.onmessage = null; };
  }, [isOnAirView, syncChannel, mediaSrc, isVideo, globalParams, activeEffect, effectParams]);

  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  const handleExport = () => {
    if (rendererRef.current) {
      rendererRef.current.startExport();
    }
  };

  const handleOnAir = () => {
    const url = new URL(window.location.href);
    url.searchParams.set('view', 'onair');
    // Open the clean output in a new independent browser window
    window.open(
      url.toString(), 
      'VisualParameterOnAir', 
      'width=1280,height=720,menubar=no,toolbar=no,location=no,status=no,resizable=yes'
    );
  };

  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic: Randomly changes effect and its parameters
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (globalParams.mixMode && !isOnAirView) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);
        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);
      };
      mix();
      interval = setInterval(mix, 2500);
    }
    return () => clearInterval(interval);
  }, [globalParams.mixMode, isOnAirView]);

  // Color MIX Logic: Smoothly changes HSL every 1 second
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (globalParams.colorMix && !isOnAirView) {
      const mixColor = () => {
        setGlobalParams(prev => {
          const nextHue = (prev.hue + randomInt(30, 90)) % 360;
          const nextSat = randomInt(40, 90);
          const nextLum = randomInt(40, 75);
          const nextHex = hslToHex(nextHue, nextSat, nextLum);
          return {
            ...prev,
            hue: nextHue,
            saturation: nextSat,
            lightness: nextLum,
            effectColor: nextHex,
            gradientPreset: 0 // Solid color during mix
          };
        });
      };
      mixColor(); // Immediate first call
      interval = setInterval(mixColor, 1000);
    }
    return () => clearInterval(interval);
  }, [globalParams.colorMix, isOnAirView]);

  // 독립적인 ON AIR 화면 레이아웃
  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black flex items-center justify-center overflow-hidden select-none cursor-none">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={() => {}} 
          isCleanFeed={true}
        />
        {!mediaSrc && (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-white/10 gap-4">
            <span className="text-[12px] font-black tracking-[1.5em] uppercase animate-pulse">Waiting for Signal</span>
            <div className="w-12 h-[1px] bg-white/10"></div>
          </div>
        )}
      </div>
    );
  }

  // 메인 컨트롤러 레이아웃
  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header 
          onExport={handleExport}
          onAir={handleOnAir}
          isExporting={isExporting}
        />
      </div>

      <main className="w-full h-full">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onExportStateChange={setIsExporting}
        />
      </main>

      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-[1600px] pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

export default App;

