      <div className="bg-zinc-900/40 backdrop-blur-2xl border border-white/10 rounded-full p-2.5 px-10 flex items-center justify-between gap-8 shadow-2xl shadow-black/40">
            <div className="flex items-center gap-10">
                <div className="flex items-center gap-6">
