import { EffectId, GlobalParams } from '../types';

const CHAR_SETS = {
    en: 'abcdefghijklmnopqrstuvwxyz0123456789',
    jp: 'あいうえおかきくけ코サシス세소12345',
    kr: '가나다라마바사아자차카타파하12345',
    cn: '你好世界数字代码计算机数据',
    ar: 'ابجديةعربية١٢٣٤٥',
    numbers: '0123456789'
};

const getChar = (lang: string, onlyNumbers: boolean = false) => {
    let charset = CHAR_SETS.en;
    if (onlyNumbers) {
        charset = CHAR_SETS.numbers;
    } else if (lang === 'random') {
        const keys = Object.keys(CHAR_SETS).filter(k => k !== 'numbers');
        charset = CHAR_SETS[keys[Math.floor(Math.random() * keys.length)] as keyof typeof CHAR_SETS];
    } else {
        charset = CHAR_SETS[lang as keyof typeof CHAR_SETS] || CHAR_SETS.en;
    }
    return charset[Math.floor(Math.random() * charset.length)];
};

const drawArrowCursor = (ctx: CanvasRenderingContext2D, x: number, y: number, size: number) => {
    ctx.save();
    ctx.imageSmoothingEnabled = true;
    ctx.translate(x, y);
    ctx.scale(size / 10, size / 10);
    ctx.rotate(-Math.PI / 8); 

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, 15);
    ctx.lineTo(4, 11);
    ctx.lineTo(7, 17);
    ctx.lineTo(9, 16);
    ctx.lineTo(6, 10);
    ctx.lineTo(11, 10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
};

const getEffectStyle = (ctx: CanvasRenderingContext2D, width: number, height: number, color: string, presetIdx: number) => {
    if (presetIdx === 0) return color;
    const presets = [
        null,
        ['#ff00ff', '#00ffff'],
        ['#ff5f6d', '#ffc371'],
        ['#11998e', '#38ef7d'],
        ['#2193b0', '#6dd5ed'],
        ['#6441A5', '#2a0845']
    ];
    const colors = presets[presetIdx];
    if (!colors) return color;
    const grad = ctx.createLinearGradient(0, 0, width, height);
    grad.addColorStop(0, colors[0]);
    grad.addColorStop(1, colors[1]);
    return grad;
};

const drawPixel = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, time: number) => {
  const baseSize = params.pixelSize || 8;
  const variance = params.sizeVariance || 0;
  const wave = (Math.sin(time * 5.0) + Math.sin(time * 2.3) * 0.5) / 1.5;
  const maxSteps = 5;
  const currentStep = Math.round(wave * (variance * maxSteps));
  const offset = currentStep * 4;
  let size = baseSize + offset;
  size = Math.max(4, Math.round(size / 4) * 4);
  const w = Math.ceil(width / size);
  const h = Math.ceil(height / size);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(ctx.canvas, 0, 0, width, height, 0, 0, w, h);
  ctx.drawImage(ctx.canvas, 0, 0, w, h, 0, 0, width, height);
};

const drawHalftone = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number) => {
  const dotSize = Math.max(2, params.dotSize);
  const imageData = ctx.getImageData(0, 0, width, height);
  const data = imageData.data;
  const len = data.length;
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = style;
  ctx.imageSmoothingEnabled = true;
  const randParam = params.dotSizeRandom || 0;
  const slowTime = time * 1.5; 

  for (let y = 0; y < height; y += dotSize) {
    for (let x = 0; x < width; x += dotSize) {
      const i = (Math.floor(y) * width + Math.floor(x)) * 4;
      if (i < len) {
        const lum = (0.299 * data[i] + 0.587 * data[i+1] + 0.114 * data[i+2]) / 255;
        const noise = Math.sin(slowTime + (x * 0.05) + (y * 0.03)) * 0.5 + 0.5;
        const rFactor = 1 - (noise * randParam);
        const radius = (dotSize * 0.5) * lum * rFactor;
        if (radius > 0.5) {
          ctx.beginPath();
          ctx.arc(x + dotSize * 0.5, y + dotSize * 0.5, radius, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
  }
};

const matrixCols: { x: number, y: number, speed: number, lastUpdate: number }[] = [];

const drawMatrix = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number) => {
    ctx.fillStyle = style;
    ctx.imageSmoothingEnabled = true;
    const fSize = params.fontSize || 10;
    const charSpacingX = fSize * 0.6; 
    const charSpacingY = fSize * 0.5; 
    ctx.font = `bold ${fSize}px monospace`;

    const requiredCols = Math.floor(width / charSpacingX) + 1;

    if (matrixCols.length !== requiredCols) {
        matrixCols.length = 0;
        for (let i = 0; i < requiredCols; i++) {
            matrixCols.push({
                x: i * charSpacingX,
                y: Math.random() * height,
                speed: (0.5 + Math.random()) * (params.fallSpeed * 5),
                lastUpdate: time
            });
        }
    }

    const tailLength = 15;
    const densityThreshold = 1 - (params.density / 500);

    matrixCols.forEach((col, i) => {
        const deltaTime = 0.016;
        col.y = (col.y + col.speed * deltaTime) % height;
        const columnSeed = (i * 123.456) % 1;
        if (columnSeed > densityThreshold) {
            for (let j = 0; j < tailLength; j++) {
                const charY = (col.y - j * charSpacingY + height) % height;
                const alpha = Math.pow(0.85, j); 
                ctx.globalAlpha = j === 0 ? 1 : alpha * 0.7;
                const char = getChar(params.language, params.showNumbers);
                ctx.fillText(char, col.x, charY);
            }
        }
    });
    ctx.globalAlpha = 1;
};

// 실시간 픽셀 소팅 글리치 로직 (두께 지원 강화 버전)
const drawGlitch = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number) => {
    const density = params.density || 45;
    const maxSize = params.size || 350;
    const thickness = Math.max(1, Math.floor(params.thickness || 8));
    const threshold = params.threshold || 80;

    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;

    const getLum = (idx: number) => (0.299 * data[idx] + 0.587 * data[idx+1] + 0.114 * data[idx+2]);

    for (let i = 0; i < density; i++) {
        // 무작위 기준 행 선택
        const startY = Math.floor(Math.random() * (height - thickness));
        let startX = Math.floor(Math.random() * (width * 0.7));
        const currentSize = Math.floor(Math.random() * maxSize) + 20;
        const endX = Math.min(startX + currentSize, width);

        // 두께(Thickness)만큼 반복하여 블록 단위 소팅 수행
        for (let t = 0; t < thickness; t++) {
            const y = startY + t;
            const pixels: {r: number, g: number, b: number, a: number, lum: number}[] = [];

            for (let targetX = startX; targetX < endX; targetX++) {
                const idx = (y * width + targetX) * 4;
                const lum = getLum(idx);

                if (lum > threshold) {
                    pixels.push({
                        r: data[idx],
                        g: data[idx+1],
                        b: data[idx+2],
                        a: data[idx+3],
                        lum: lum
                    });
                }
            }

            // 명도순 정렬
            pixels.sort((a, b) => b.lum - a.lum);

            // 데이터 갱신
            for (let j = 0; j < pixels.length; j++) {
                const idx = (y * width + startX + j) * 4;
                data[idx] = pixels[j].r;
                data[idx+1] = pixels[j].g;
                data[idx+2] = pixels[j].b;
                data[idx+3] = pixels[j].a;
            }
        }
    }

    ctx.putImageData(imgData, 0, 0);

    // 색수차 효과 (간헐적으로 발생시켜 긴장감 유지)
    if (time % 0.3 > 0.25) { 
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;
        const shift = 4 + Math.sin(time * 10) * 4;
        ctx.drawImage(ctx.canvas, shift, 0);
        ctx.restore();
    }
};

const plexusParticles: {x: number, y: number, vx: number, vy: number, noise: number, id: string, sizeFactor: number, char: string}[] = [];

const drawPlexus = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, mask: ImageData | null, time: number) => {
  const count = params.pointCount;
  const linkDistSq = params.linkDistance * params.linkDistance;
  const shape = params.shapeType || 'square';
  const alphabets = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  ctx.imageSmoothingEnabled = true;

  const getSpawn = () => {
    for(let k=0; k<20; k++) {
        const rx = Math.random() * width; const ry = Math.random() * height;
        if (mask) {
            const mx = Math.floor((rx/width)*mask.width); const my = Math.floor((ry/height)*mask.height);
            const midx = (my * mask.width + mx) * 4;
            if (mask.data[midx] > 128) return {x: rx, y: ry};
        } else return {x: rx, y: ry};
    }
    return {x: Math.random() * width, y: Math.random() * height};
  };

  if (plexusParticles.length !== count) {
    plexusParticles.length = 0;
    for(let i=0; i<count; i++) {
        const p = getSpawn();
        const baseSpeed = 0.5;
        plexusParticles.push({ 
            ...p, 
            vx: (Math.random()-0.5)*baseSpeed, 
            vy: (Math.random()-0.5)*baseSpeed, 
            noise: Math.random()*100, 
            id: Math.floor(Math.random() * 9999).toString().padStart(4, '0'),
            sizeFactor: 0.5 + Math.random(),
            char: alphabets[Math.floor(Math.random() * alphabets.length)]
        });
    }
  }

  ctx.strokeStyle = style;
  ctx.fillStyle = style;

  for(let i=0; i<count; i++) {
    const p = plexusParticles[i];
    p.x += p.vx; p.y += p.vy;
    let needsReset = false;
    if (mask) {
        const mx = Math.floor((p.x/width)*mask.width); const my = Math.floor((p.y/height)*mask.height);
        const midx = (my * mask.width + mx) * 4;
        if (p.x < 0 || p.x > width || p.y < 0 || p.y > height || (mask.data && mask.data[midx] < 128)) needsReset = true;
    } else {
        if (p.x < 0 || p.x > width) p.vx *= -1; if (p.y < 0 || p.y > height) p.vy *= -1;
    }
    if (needsReset) { const s = getSpawn(); p.x = s.x; p.y = s.y; }

    const rx = p.x + Math.sin(time + p.noise)*params.jitter;
    const ry = p.y + Math.cos(time + p.noise)*params.jitter;

    for(let j=i+1; j<Math.min(i+15, count); j++) {
        const p2 = plexusParticles[j];
        const p2rx = p2.x + Math.sin(time + p2.noise)*params.jitter;
        const p2ry = p2.y + Math.cos(time + p2.noise)*params.jitter;
        const dx = rx - p2rx; const dy = ry - p2ry;
        const d2 = dx*dx + dy*dy;
        if (d2 < linkDistSq) {
            const alpha = 1 - (d2/linkDistSq);
            ctx.globalAlpha = alpha * 0.7;
            ctx.lineWidth = params.lineWidth * (1.5 - (d2/linkDistSq));
            ctx.beginPath();
            ctx.moveTo(rx, ry);
            ctx.lineTo(p2rx, p2ry);
            ctx.stroke();
        }
    }

    ctx.globalAlpha = 1.0;
    const pSize = params.pointSize * (1 + (p.sizeFactor - 1) * params.pointSizeRandom);

    if (shape === 'dot') {
        ctx.beginPath();
        ctx.arc(rx, ry, pSize / 2, 0, Math.PI * 2);
        ctx.fill();
    } else if (shape === 'number') {
        ctx.font = `bold ${pSize * 1.5}px monospace`;
        ctx.fillText(p.id[0], rx - pSize/2, ry + pSize/2);
    } else if (shape === 'alphabet') {
        ctx.font = `bold ${pSize * 1.5}px monospace`;
        ctx.fillText(p.char, rx - pSize/2, ry + pSize/2);
    } else if (shape === 'arrow') {
        drawArrowCursor(ctx, rx, ry, pSize * 1.5);
    } else {
        ctx.fillRect(rx - pSize / 2, ry - pSize / 2, pSize, pSize);
    }

    if (i % 12 === 0) {
        ctx.save();
        ctx.globalAlpha = 0.5;
        ctx.lineWidth = 0.5;
        const chSize = pSize * 5;
        ctx.beginPath();
        ctx.moveTo(rx - chSize, ry); ctx.lineTo(rx + chSize, ry);
        ctx.moveTo(rx, ry - chSize); ctx.lineTo(rx, ry + chSize);
        ctx.stroke();
        ctx.restore();
    }

    if (params.showNumbers) {
        ctx.save();
        ctx.font = 'bold 8px monospace';
        ctx.globalAlpha = 0.8;
        ctx.fillText(`ID:${p.id}`, rx + 8, ry - 8);
        ctx.restore();
    }
  }
  ctx.globalAlpha = 1.0;
};

const drawLine = (ctx: CanvasRenderingContext2D, width: number, height: number, params: any, style: string | CanvasGradient, time: number) => {
    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;
    const bgData = new Uint8ClampedArray(data);
    ctx.imageSmoothingEnabled = true;

    for (let i = 0; i < bgData.length; i += 4) {
        bgData[i] = 255 - data[i];
        bgData[i+1] = 255 - data[i+1];
        bgData[i+2] = 255 - data[i+2];
    }
    ctx.putImageData(new ImageData(bgData, width, height), 0, 0);

    ctx.fillStyle = style;
    const r = params.dotRandom || 0;
    const step = 4; 
    const threshold = params.threshold;
    const cSize = params.dotSize || 2.5;
    const shape = params.shapeType || 'arrow';
    const alphabets = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    const slowTime = time * 0.8; 

    for (let y = 0; y < height; y += step) {
        for (let x = 0; x < width; x += step) {
            const i = (y * width + x) * 4;
            const iNext = (y * width + (x+1)) * 4;
            if (iNext < data.length) {
                const l1 = (0.299 * data[i] + 0.587 * data[i+1] + 0.114 * data[i+2]);
                const l2 = (0.299 * data[iNext] + 0.587 * data[iNext+1] + 0.114 * data[iNext+2]);

                if (Math.abs(l1 - l2) > threshold) {
                    const noise = Math.sin(slowTime + (x * 0.04) + (y * 0.04)) * 0.5 + 0.5;
                    const finalSize = cSize * (1.5 + noise * r * 4); 

                    if (shape === 'dot') {
                        ctx.beginPath();
                        ctx.arc(x, y, finalSize / 2, 0, Math.PI * 2);
                        ctx.fill();
                    } else if (shape === 'square') {
                        ctx.fillRect(x - finalSize/2, y - finalSize/2, finalSize, finalSize);
                    } else if (shape === 'number') {
                        ctx.font = `bold ${finalSize * 1.5}px monospace`;
                        const num = Math.floor((slowTime * 5 + x + y) % 10);
                        ctx.fillText(num.toString(), x, y);
                    } else if (shape === 'alphabet') {
                        ctx.font = `bold ${finalSize * 1.5}px monospace`;
                        const charIdx = Math.floor((slowTime * 4 + x + y) % alphabets.length);
                        ctx.fillText(alphabets[charIdx], x, y);
                    } else {
                        drawArrowCursor(ctx, x, y, finalSize);
                    }
                }
            }
        }
    }
};

const applyPostFilters = (ctx: CanvasRenderingContext2D, width: number, height: number, global: GlobalParams) => {
    if (!global.bw && !global.xray && !global.thermal && !global.invert && !global.dramaticWarm && !global.dramaticCool) return;
    const img = ctx.getImageData(0, 0, width, height);
    const d = img.data;
    const len = d.length;
    for(let i=0; i < len; i+=4) {
        let r = d[i], g = d[i+1], b = d[i+2];
        if (global.bw) { const l = 0.299 * r + 0.587 * g + 0.114 * b; r=g=b=l; }
        if (global.xray) { r=255-r; g=255-g; b=255-b; }
        if (global.thermal) {
            const l = (0.299 * r + 0.587 * g + 0.114 * b)/255;
            if (l < 0.33) { r=0; g=0; b=l*765; }
            else if (l < 0.66) { r=(l-0.33)*765; g=255; b=255-(l-0.33)*765; }
            else { r=255; g=255-(l-0.66)*765; b=0; }
        }
        if (global.dramaticWarm) { r *= 1.2; b *= 0.8; }
        if (global.dramaticCool) { r *= 0.8; b *= 1.2; }
        if (global.invert) { r=255-r; g=255-g; b=255-b; }

        d[i]=Math.min(255, Math.max(0, r)); 
        d[i+1]=Math.min(255, Math.max(0, g)); 
        d[i+2]=Math.min(255, Math.max(0, b));
    }
    ctx.putImageData(img, 0, 0);
};

export const renderFrame = (ctx: CanvasRenderingContext2D, source: HTMLImageElement | HTMLVideoElement, effectId: EffectId, params: any, global: GlobalParams, time: number, aiMask?: ImageData | null) => {
    const width = ctx.canvas.width; const height = ctx.canvas.height;
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, width, height);
    ctx.imageSmoothingEnabled = true;

    const sw = source instanceof HTMLVideoElement ? source.videoWidth : source.naturalWidth;
    const sh = source instanceof HTMLVideoElement ? source.videoHeight : source.naturalHeight;
    const sAspect = sw / sh; const dAspect = width / height;
    let drawW, drawH, drawX, drawY;
    if (sAspect > dAspect) { drawH = height; drawW = height * sAspect; drawX = (width - drawW) / 2; drawY = 0; }
    else { drawW = width; drawH = width / sAspect; drawX = 0; drawY = (height - drawH) / 2; }

    ctx.drawImage(source, drawX, drawY, drawW, drawH);
    applyPostFilters(ctx, width, height, global);

    if (effectId === 'none') return;

    let filteredBgSnapshot: ImageData | null = null;
    if (global.applyTo !== 'both') {
        filteredBgSnapshot = ctx.getImageData(0, 0, width, height);
    }

    const effectCanvas = document.createElement('canvas');
    effectCanvas.width = width; effectCanvas.height = height;
    const effectCtx = effectCanvas.getContext('2d')!;
    effectCtx.imageSmoothingEnabled = true;
    effectCtx.drawImage(ctx.canvas, 0, 0);

    const style = getEffectStyle(effectCtx, width, height, global.effectColor, global.gradientPreset);

    switch(effectId) {
        case 'pixel': drawPixel(effectCtx, width, height, params, time); break;
        case 'halftone': drawHalftone(effectCtx, width, height, params, style, time); break;
        case 'matrix': drawMatrix(effectCtx, width, height, params, style, time); break;
        case 'glitch': drawGlitch(effectCtx, width, height, params, style, time); break;
        case 'plexus': drawPlexus(effectCtx, width, height, params, style, aiMask || null, time); break;
        case 'line': drawLine(effectCtx, width, height, params, style, time); break;
    }

    if (global.applyTo !== 'both' && aiMask && filteredBgSnapshot) {
        const effectImg = effectCtx.getImageData(0, 0, width, height);
        const out = ctx.createImageData(width, height);
        const ed = effectImg.data;
        const bd = filteredBgSnapshot.data;
        const od = out.data;
        const mw = aiMask.width; const mh = aiMask.height; const md = aiMask.data;

        for(let y=0; y<height; y++) {
            const rowIdx = y * width;
            const mRowIdx = Math.floor((y/height)*mh) * mw;
            for(let x=0; x<width; x++) {
                const i = (rowIdx + x) * 4;
                const mi = (mRowIdx + Math.floor((x/width)*mw)) * 4;
                const isSub = md[mi] > 128;
                const useEffect = global.applyTo === 'subject' ? isSub : !isSub;
                if (useEffect) { od[i]=ed[i]; od[i+1]=ed[i+1]; od[i+2]=ed[i+2]; od[i+3]=255; }
                else { od[i]=bd[i]; od[i+1]=bd[i+1]; od[i+2]=bd[i+2]; od[i+3]=255; }
            }
        }
        ctx.putImageData(out, 0, 0);
    } else {
        ctx.drawImage(effectCanvas, 0, 0);
    }
};

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  isCleanFeed?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  isCleanFeed = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const internalCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  // Fix: Added explicit undefined as initial value to satisfy "Expected 1 arguments, but got 0" if strict types are enabled
  const requestRef = useRef<number | undefined>(undefined);
  const startTimeRef = useRef<number>(Date.now());
  const lastMaskRef = useRef<ImageData | null>(null);
  const frameCountRef = useRef<number>(0);

  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [exportEta, setExportEta] = useState(0);

  const trackingOffsetRef = useRef({ x: 0, y: 0, scale: 1.0 });
  const PROC_WIDTH = 800; 

  useImperativeHandle(ref, () => ({
    startExport: async () => {
      if (!canvasRef.current || !mediaSrc) return;
      const canvas = canvasRef.current;
      const chunks: Blob[] = [];
      // Use any cast for captureStream as it might not be in all lib.dom definitions
      const stream = (canvas as any).captureStream(60); 
      const mimeTypes = ['video/mp4;codecs=h264', 'video/mp4', 'video/webm;codecs=h264', 'video/webm'];
      const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || 'video/webm';
      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 12000000 });
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
        a.download = `visual-parameter-h264-${Date.now()}.${extension}`;
        a.click();
        setIsExporting(false); setExportProgress(0); setExportEta(0); onExportStateChange?.(false);
        if (sourceVideoRef.current) { sourceVideoRef.current.muted = true; sourceVideoRef.current.play(); }
      };
      setIsExporting(true); onExportStateChange?.(true);
      if (isVideo && sourceVideoRef.current) {
        const video = sourceVideoRef.current;
        video.currentTime = 0; video.play(); recorder.start();
        const progressInterval = setInterval(() => {
          if (!video.duration) return;
          setExportProgress((video.currentTime / video.duration) * 100);
          setExportEta(Math.max(0, video.duration - video.currentTime));
        }, 100);
        const handleVideoEnd = () => { recorder.stop(); clearInterval(progressInterval); video.removeEventListener('ended', handleVideoEnd); };
        video.addEventListener('ended', handleVideoEnd);
      } else {
        const duration = 3; recorder.start(); const start = Date.now();
        const progressInterval = setInterval(() => {
          const elapsed = (Date.now() - start) / 1000;
          setExportProgress((elapsed / duration) * 100);
          setExportEta(Math.max(0, duration - elapsed));
          if (elapsed >= duration) { recorder.stop(); clearInterval(progressInterval); }
        }, 100);
      }
    }
  }));

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) { segmenterRef.current = segmenter; setAiReady(true); } else { segmenter.close(); }
      } catch (err) {}
    }
    initAI();
    return () => { active = false; segmenterRef.current?.close(); };
  }, [isVideo]);

  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;

      // Calculate aspect-ratio correct dimensions for Clean Feed (ON AIR)
      if (isCleanFeed && mediaLoaded) {
        const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
        if (source) {
          const sw = isVideo ? (source as HTMLVideoElement).videoWidth : (source as HTMLImageElement).naturalWidth;
          const sh = isVideo ? (source as HTMLVideoElement).videoHeight : (source as HTMLImageElement).naturalHeight;
          const sAspect = sw / sh;

          const windowW = window.innerWidth;
          const windowH = window.innerHeight;
          const windowAspect = windowW / windowH;

          let targetW, targetH;
          if (sAspect > windowAspect) {
            targetW = windowW;
            targetH = windowW / sAspect;
          } else {
            targetH = windowH;
            targetW = windowH * sAspect;
          }
          setDimensions({ w: Math.floor(targetW), h: Math.floor(targetH) });
          return;
        }
      }

      // Default split-screen logic
      const w = isCleanFeed ? containerRef.current.clientWidth : Math.floor(window.innerWidth / 2);
      const h = isCleanFeed ? containerRef.current.clientHeight : window.innerHeight;
      setDimensions({ w, h });
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, [isCleanFeed, mediaLoaded, isVideo]);

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const displayCtx = canvasRef.current.getContext('2d');
      const internalCanvas = internalCanvasRef.current;
      const scale = PROC_WIDTH / dimensions.w;
      const procW = PROC_WIDTH;
      const procH = Math.floor(dimensions.h * scale);
      if (internalCanvas.width !== procW) { internalCanvas.width = procW; internalCanvas.height = procH; }
      const ctx = internalCanvas.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
      if (ctx && displayCtx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          frameCountRef.current++;
          const shouldUpdateMask = !isVideo || (frameCountRef.current % 3 === 0);
          if (shouldUpdateMask || !lastMaskRef.current) {
              try {
                // Ensure segmenter exists before calling segment methods
                const result = isVideo ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now()) : segmenterRef.current.segment(source as HTMLImageElement);
                if (result?.categoryMask) {
                   const maskData = result.categoryMask.getAsUint8Array();
                   const mw = result.categoryMask.width; const mh = result.categoryMask.height;
                   const rgba = new Uint8ClampedArray(mw * mh * 4);
                   let sumX = 0; let sumY = 0; let count = 0;
                   for (let i = 0; i < maskData.length; i++) {
                      const val = maskData[i] > 0 ? 255 : 0; const idx = i * 4;
                      rgba[idx] = rgba[idx+1] = rgba[idx+2] = val; rgba[idx+3] = 255;
                      if (val > 0) { sumX += i % mw; sumY += Math.floor(i / mw); count++; }
                   }
                   if (count > 100 && globalParams.autoTracking) {
                       const centerX = (sumX / count) / mw; const centerY = (sumY / count) / mh;
                       const targetX = (0.5 - centerX) * procW * 0.5; const targetY = (0.5 - centerY) * procH * 0.5;
                       const areaFraction = count / (mw * mh);
                       const targetScale = 1.1 + Math.max(0, (0.25 - areaFraction) * 1.5);
                       trackingOffsetRef.current.x += (targetX - trackingOffsetRef.current.x) * 0.08;
                       trackingOffsetRef.current.y += (targetY - trackingOffsetRef.current.y) * 0.08;
                       trackingOffsetRef.current.scale += (targetScale - trackingOffsetRef.current.scale) * 0.05;
                   } else if (!globalParams.autoTracking) {
                       trackingOffsetRef.current.x *= 0.9; trackingOffsetRef.current.y *= 0.9;
                       trackingOffsetRef.current.scale += (1.0 - trackingOffsetRef.current.scale) * 0.1;
                   }
                   lastMaskRef.current = new ImageData(rgba, mw, mh);
                   result.categoryMask.close();
                   result.confidenceMasks?.forEach(m => m.close());
                }
              } catch (e) {}
          }
          ctx.save();
          if (globalParams.autoTracking || trackingOffsetRef.current.scale > 1.01) {
            ctx.translate(trackingOffsetRef.current.x, trackingOffsetRef.current.y); ctx.translate(procW/2, procH/2);
            ctx.scale(trackingOffsetRef.current.scale, trackingOffsetRef.current.scale); ctx.translate(-procW/2, -procH/2);
          }
          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, lastMaskRef.current);
          ctx.restore();
          displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, 0, 0, dimensions.w, dimensions.h);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  if (isCleanFeed) {
    return (
      <div className="w-full h-full bg-black flex items-center justify-center overflow-hidden" ref={containerRef}>
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={() => setMediaLoaded(true)} />
        )}
        <canvas 
          ref={canvasRef} 
          width={dimensions.w} 
          height={dimensions.h} 
          style={{ width: dimensions.w, height: dimensions.h }}
          className="shadow-2xl"
        />
      </div>
    );
  }

  return (
    <div className="flex w-full h-screen overflow-hidden bg-white" ref={containerRef}>
      {isExporting && (
        <div className="absolute inset-0 z-[100] bg-black/80 backdrop-blur-xl flex flex-col items-center justify-center text-white p-10">
          <div className="relative w-24 h-24 mb-10 flex items-center justify-center">
            <div className="absolute inset-0 border-4 border-white/10 rounded-full"></div>
            <svg className="absolute inset-0 w-full h-full -rotate-90">
              <circle cx="48" cy="48" r="44" stroke="white" strokeWidth="4" fill="transparent" strokeDasharray={276} strokeDashoffset={276 - (276 * exportProgress) / 100} strokeLinecap="round" className="transition-all duration-300" />
            </svg>
            <span className="text-[14px] font-black">{Math.floor(exportProgress)}%</span>
          </div>
          <div className="flex flex-col items-center gap-2">
            <span className="text-[14px] font-black uppercase tracking-[0.5em] animate-pulse">Encoding H264 Video</span>
            <span className="text-[10px] font-bold text-white/60 tracking-widest uppercase">
              Estimated Remaining: <span className="text-white">{exportEta.toFixed(1)}s</span>
            </span>
          </div>
          <div className="mt-12 w-64 h-1 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-white transition-all duration-300" style={{ width: `${exportProgress}%` }}></div>
          </div>
          <p className="mt-6 text-[9px] font-bold text-white/40 uppercase tracking-[0.2em]">Do not close this tab until rendering is complete.</p>
        </div>
      )}

      <div 
        className={`relative w-1/2 h-full flex items-center justify-center transition-opacity duration-700 ${isDragging ? 'opacity-50' : 'opacity-100'}`}
        onDragOver={(e) => {e.preventDefault(); setIsDragging(true);}}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]);}}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-4 text-zinc-100 pointer-events-none">
             <span className="text-[9px] font-black uppercase tracking-[0.4em]">Initialize_Input (Drop File)</span>
          </div>
        )}
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="w-full h-full object-cover" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="w-full h-full object-cover" onLoad={() => setMediaLoaded(true)} />
        )}
      </div>

      <div className="relative w-1/2 h-full bg-white flex items-center justify-center">
        <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className={`w-full h-full transition-all duration-1000 ${mediaLoaded ? 'opacity-100' : 'opacity-0'}`} />
      </div>
    </div>
  );
});

export default CanvasRenderer;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt, hslToHex } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const syncChannel = useMemo(() => new BroadcastChannel('visual-parameter-sync'), []);

  // Detect ON AIR mode from URL query parameters
  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  // 1. Broadcast state changes from the Main Window to all listening ON AIR windows
  useEffect(() => {
    if (!isOnAirView) {
      const state = {
        type: 'STATE_UPDATE',
        mediaSrc,
        isVideo,
        globalParams,
        activeEffectId: activeEffect.id,
        effectParams
      };
      syncChannel.postMessage(state);
    }
  }, [mediaSrc, isVideo, globalParams, activeEffect, effectParams, isOnAirView, syncChannel]);

  // 2. Handle Synchronization Logic (Handshake and Updates)
  useEffect(() => {
    const handleMessage = (e: MessageEvent) => {
      const data = e.data;

      if (isOnAirView) {
        // ON AIR Window: Listen for incoming state updates from the controller
        if (data.type === 'STATE_UPDATE') {
          if (data.mediaSrc !== undefined) setMediaSrc(data.mediaSrc);
          if (data.isVideo !== undefined) setIsVideo(data.isVideo);
          if (data.globalParams !== undefined) setGlobalParams(data.globalParams);
          if (data.activeEffectId !== undefined) {
            const effect = EFFECTS.find(eff => eff.id === data.activeEffectId);
            if (effect) setActiveEffect(effect);
          }
          if (data.effectParams !== undefined) setEffectParams(data.effectParams);
        }
      } else {
        // Main Window: Listen for "REQUEST_SYNC" from newly opened ON AIR windows
        if (data.type === 'REQUEST_SYNC') {
          syncChannel.postMessage({
            type: 'STATE_UPDATE',
            mediaSrc,
            isVideo,
            globalParams,
            activeEffectId: activeEffect.id,
            effectParams
          });
        }
      }
    };

    syncChannel.onmessage = handleMessage;

    // If this instance is the ON AIR view, request the initial state from the main window immediately
    if (isOnAirView) {
      syncChannel.postMessage({ type: 'REQUEST_SYNC' });
    }

    return () => { syncChannel.onmessage = null; };
  }, [isOnAirView, syncChannel, mediaSrc, isVideo, globalParams, activeEffect, effectParams]);

  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  const handleExport = () => {
    if (rendererRef.current) {
      rendererRef.current.startExport();
    }
  };

  const handleOnAir = () => {
    const url = new URL(window.location.href);
    url.searchParams.set('view', 'onair');
    // Open the clean output in a new independent browser window
    window.open(
      url.toString(), 
      'VisualParameterOnAir', 
      'width=1280,height=720,menubar=no,toolbar=no,location=no,status=no,resizable=yes'
    );
  };

  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode Logic: Randomly changes effect and its parameters
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (globalParams.mixMode && !isOnAirView) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);
        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               if (config.step && config.step % 1 === 0) {
                    newParams[key] = randomInt(config.randomRange[0], config.randomRange[1]);
               } else {
                    newParams[key] = parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
               }
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);
      };
      mix();
      interval = setInterval(mix, 2500);
    }
    return () => clearInterval(interval);
  }, [globalParams.mixMode, isOnAirView]);

  // Color MIX Logic: Smooth interpolation for global colors
  useEffect(() => {
    let timer: ReturnType<typeof setInterval>;
    let lerpTimer: ReturnType<typeof setInterval>;

    if (globalParams.colorMix && !isOnAirView) {
      let targetHue = globalParams.hue;
      const pickNewTarget = () => {
        targetHue = (targetHue + randomInt(40, 120)) % 360; 
      };

      lerpTimer = setInterval(() => {
        setGlobalParams(prev => {
          const lerp = (start: number, end: number, amt: number) => start + (end - start) * amt;
          const nextHue = lerp(prev.hue, targetHue, 0.1);
          const nextHex = hslToHex(nextHue, prev.saturation, prev.lightness);
          return {
            ...prev,
            hue: nextHue,
            effectColor: nextHex,
            gradientPreset: 0
          };
        });
      }, 100);

      pickNewTarget();
      timer = setInterval(pickNewTarget, 3000);
    }

    return () => {
      clearInterval(timer);
      clearInterval(lerpTimer);
    };
  }, [globalParams.colorMix, isOnAirView]);

  // 독립적인 ON AIR 화면 레이아웃
  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black flex items-center justify-center overflow-hidden select-none cursor-none">
        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={() => {}} 
          isCleanFeed={true}
        />
        {!mediaSrc && (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-white/10 gap-4">
            <span className="text-[12px] font-black tracking-[1.5em] uppercase animate-pulse">Waiting for Signal</span>
            <div className="w-12 h-[1px] bg-white/10"></div>
          </div>
        )}
      </div>
    );
  }

  // 메인 컨트롤러 레이아웃
  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header 
          onExport={handleExport}
          onAir={handleOnAir}
          isExporting={isExporting}
        />
      </div>

      <main className="w-full h-full">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onExportStateChange={setIsExporting}
        />
      </main>

      <div className="absolute bottom-3 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-[1600px] pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  isCleanFeed?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  isCleanFeed = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const internalCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const startTimeRef = useRef<number>(Date.now());
  const lastMaskRef = useRef<ImageData | null>(null);
  const frameCountRef = useRef<number>(0);

  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [exportEta, setExportEta] = useState(0);

  const trackingOffsetRef = useRef({ x: 0, y: 0, scale: 1.0 });
  const PROC_WIDTH = 800; 

  useImperativeHandle(ref, () => ({
    startExport: async () => {
      if (!canvasRef.current || !mediaSrc) return;
      const canvas = canvasRef.current;
      const chunks: Blob[] = [];
      const stream = (canvas as any).captureStream(60); 
      const mimeTypes = ['video/mp4;codecs=h264', 'video/mp4', 'video/webm;codecs=h264', 'video/webm'];
      const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || 'video/webm';
      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 12000000 });
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
        a.download = `visual-parameter-h264-${Date.now()}.${extension}`;
        a.click();
        setIsExporting(false); setExportProgress(0); setExportEta(0); onExportStateChange?.(false);
        if (sourceVideoRef.current) { sourceVideoRef.current.muted = true; sourceVideoRef.current.play(); }
      };
      setIsExporting(true); onExportStateChange?.(true);
      if (isVideo && sourceVideoRef.current) {
        const video = sourceVideoRef.current;
        video.currentTime = 0; video.play(); recorder.start();
        const progressInterval = setInterval(() => {
          if (!video.duration) return;
          setExportProgress((video.currentTime / video.duration) * 100);
          setExportEta(Math.max(0, video.duration - video.currentTime));
        }, 100);
        const handleVideoEnd = () => { recorder.stop(); clearInterval(progressInterval); video.removeEventListener('ended', handleVideoEnd); };
        video.addEventListener('ended', handleVideoEnd);
      } else {
        const duration = 3; recorder.start(); const start = Date.now();
        const progressInterval = setInterval(() => {
          const elapsed = (Date.now() - start) / 1000;
          setExportProgress((elapsed / duration) * 100);
          setExportEta(Math.max(0, duration - elapsed));
          if (elapsed >= duration) { recorder.stop(); clearInterval(progressInterval); }
        }, 100);
      }
    }
  }));

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) { segmenterRef.current = segmenter; setAiReady(true); } else { segmenter.close(); }
      } catch (err) {}
    }
    initAI();
    return () => { active = false; segmenterRef.current?.close(); };
  }, [isVideo]);

  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;

      // Calculate aspect-ratio correct dimensions for Clean Feed (ON AIR)
      if (isCleanFeed && mediaLoaded) {
        const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
        if (source) {
          const sw = isVideo ? (source as HTMLVideoElement).videoWidth : (source as HTMLImageElement).naturalWidth;
          const sh = isVideo ? (source as HTMLVideoElement).videoHeight : (source as HTMLImageElement).naturalHeight;
          const sAspect = sw / sh;

          const windowW = window.innerWidth;
          const windowH = window.innerHeight;
          const windowAspect = windowW / windowH;

          let targetW, targetH;
          if (sAspect > windowAspect) {
            targetW = windowW;
            targetH = windowW / sAspect;
          } else {
            targetH = windowH;
            targetW = windowH * sAspect;
          }
          setDimensions({ w: Math.floor(targetW), h: Math.floor(targetH) });
          return;
        }
      }

      // Default split-screen logic for controller
      const w = isCleanFeed ? containerRef.current.clientWidth : Math.floor(window.innerWidth / 2);
      const h = isCleanFeed ? containerRef.current.clientHeight : window.innerHeight;
      setDimensions({ w, h });
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, [isCleanFeed, mediaLoaded, isVideo]);

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const displayCtx = canvasRef.current.getContext('2d');
      const internalCanvas = internalCanvasRef.current;
      const scale = PROC_WIDTH / dimensions.w;
      const procW = PROC_WIDTH;
      const procH = Math.floor(dimensions.h * scale);
      if (internalCanvas.width !== procW) { internalCanvas.width = procW; internalCanvas.height = procH; }
      const ctx = internalCanvas.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
      if (ctx && displayCtx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          frameCountRef.current++;
          const shouldUpdateMask = !isVideo || (frameCountRef.current % 3 === 0);
          if (shouldUpdateMask || !lastMaskRef.current) {
              try {
                const result = isVideo ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now()) : segmenterRef.current.segment(source as HTMLImageElement);
                if (result?.categoryMask) {
                   const maskData = result.categoryMask.getAsUint8Array();
                   const mw = result.categoryMask.width; const mh = result.categoryMask.height;
                   const rgba = new Uint8ClampedArray(mw * mh * 4);
                   let sumX = 0; let sumY = 0; let count = 0;
                   for (let i = 0; i < maskData.length; i++) {
                      const val = maskData[i] > 0 ? 255 : 0; const idx = i * 4;
                      rgba[idx] = rgba[idx+1] = rgba[idx+2] = val; rgba[idx+3] = 255;
                      if (val > 0) { sumX += i % mw; sumY += Math.floor(i / mw); count++; }
                   }
                   if (count > 100 && globalParams.autoTracking) {
                       const centerX = (sumX / count) / mw; const centerY = (sumY / count) / mh;
                       const targetX = (0.5 - centerX) * procW * 0.5; const targetY = (0.5 - centerY) * procH * 0.5;
                       const areaFraction = count / (mw * mh);
                       const targetScale = 1.1 + Math.max(0, (0.25 - areaFraction) * 1.5);
                       trackingOffsetRef.current.x += (targetX - trackingOffsetRef.current.x) * 0.08;
                       trackingOffsetRef.current.y += (targetY - trackingOffsetRef.current.y) * 0.08;
                       trackingOffsetRef.current.scale += (targetScale - trackingOffsetRef.current.scale) * 0.05;
                   } else if (!globalParams.autoTracking) {
                       trackingOffsetRef.current.x *= 0.9; trackingOffsetRef.current.y *= 0.9;
                       trackingOffsetRef.current.scale += (1.0 - trackingOffsetRef.current.scale) * 0.1;
                   }
                   lastMaskRef.current = new ImageData(rgba, mw, mh);
                   result.categoryMask.close();
                }
              } catch (e) {}
          }
          ctx.save();
          if (globalParams.autoTracking || trackingOffsetRef.current.scale > 1.01) {
            ctx.translate(trackingOffsetRef.current.x, trackingOffsetRef.current.y); ctx.translate(procW/2, procH/2);
            ctx.scale(trackingOffsetRef.current.scale, trackingOffsetRef.current.scale); ctx.translate(-procW/2, -procH/2);
          }
          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, lastMaskRef.current);
          ctx.restore();
          displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, 0, 0, dimensions.w, dimensions.h);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  if (isCleanFeed) {
    return (
      <div className="w-full h-full bg-black flex items-center justify-center overflow-hidden" ref={containerRef}>
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={() => setMediaLoaded(true)} />
        )}
        <canvas 
          ref={canvasRef} 
          width={dimensions.w} 
          height={dimensions.h} 
          style={{ width: dimensions.w, height: dimensions.h }}
          className="shadow-2xl"
        />
      </div>
    );
  }

  return (
    <div className="flex w-full h-screen overflow-hidden bg-white" ref={containerRef}>
      {isExporting && (
        <div className="absolute inset-0 z-[100] bg-black/80 backdrop-blur-xl flex flex-col items-center justify-center text-white p-10">
          <div className="relative w-24 h-24 mb-10 flex items-center justify-center">
            <div className="absolute inset-0 border-4 border-white/10 rounded-full"></div>
            <svg className="absolute inset-0 w-full h-full -rotate-90">
              <circle cx="48" cy="48" r="44" stroke="white" strokeWidth="4" fill="transparent" strokeDasharray={276} strokeDashoffset={276 - (276 * exportProgress) / 100} strokeLinecap="round" className="transition-all duration-300" />
            </svg>
            <span className="text-[14px] font-black">{Math.floor(exportProgress)}%</span>
          </div>
          <div className="flex flex-col items-center gap-2">
            <span className="text-[14px] font-black uppercase tracking-[0.5em] animate-pulse">Encoding H264 Video</span>
            <span className="text-[10px] font-bold text-white/60 tracking-widest uppercase">
              Estimated Remaining: <span className="text-white">{exportEta.toFixed(1)}s</span>
            </span>
          </div>
          <div className="mt-12 w-64 h-1 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-white transition-all duration-300" style={{ width: `${exportProgress}%` }}></div>
          </div>
          <p className="mt-6 text-[9px] font-bold text-white/40 uppercase tracking-[0.2em]">Do not close this tab until rendering is complete.</p>
        </div>
      )}

      <div 
        className={`relative w-1/2 h-full flex items-center justify-center transition-opacity duration-700 ${isDragging ? 'opacity-50' : 'opacity-100'}`}
        onDragOver={(e) => {e.preventDefault(); setIsDragging(true);}}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]);}}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-4 text-zinc-100 pointer-events-none">
             <span className="text-[9px] font-black uppercase tracking-[0.4em]">Initialize_Input (Drop File)</span>
          </div>
        )}
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="w-full h-full object-cover" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="w-full h-full object-cover" onLoad={() => setMediaLoaded(true)} />
        )}
      </div>

      <div className="relative w-1/2 h-full bg-white flex items-center justify-center">
        <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className={`w-full h-full transition-all duration-1000 ${mediaLoaded ? 'opacity-100' : 'opacity-0'}`} />
      </div>
    </div>
  );
});

export default CanvasRenderer;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Header from './components/Header';
import CanvasRenderer, { CanvasRendererHandle } from './components/CanvasRenderer';
import ControlPanel from './components/ControlPanel';
import { EFFECTS, INITIAL_GLOBAL_PARAMS } from './constants';
import { GlobalParams, EffectDef, ParamConfig } from './types';
import { randomFloat, randomInt, hslToHex } from './services/utils';

const App: React.FC = () => {
  const [mediaSrc, setMediaSrc] = useState<string | null>(null);
  const [isVideo, setIsVideo] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const [globalParams, setGlobalParams] = useState<GlobalParams>(INITIAL_GLOBAL_PARAMS);
  const [activeEffect, setActiveEffect] = useState<EffectDef>(EFFECTS[0]);
  const [effectParams, setEffectParams] = useState<any>(EFFECTS[0].defaultParams);

  // ON AIR 전용 상태
  const [isOnAirActive, setIsOnAirActive] = useState(false);

  const rendererRef = useRef<CanvasRendererHandle>(null);
  const syncChannel = useMemo(() => new BroadcastChannel('visual-parameter-sync'), []);

  const isOnAirView = new URLSearchParams(window.location.search).get('view') === 'onair';

  // 1. 메인 창 -> 온에어 창 상태 전송
  useEffect(() => {
    if (!isOnAirView) {
      const state = {
        type: 'STATE_UPDATE',
        mediaSrc,
        isVideo,
        globalParams,
        activeEffectId: activeEffect.id,
        effectParams
      };
      syncChannel.postMessage(state);
    }
  }, [mediaSrc, isVideo, globalParams, activeEffect, effectParams, isOnAirView, syncChannel]);

  // 2. 메시지 수신 및 초기 동기화 요청
  useEffect(() => {
    const handleMessage = (e: MessageEvent) => {
      const data = e.data;
      if (isOnAirView) {
        if (data.type === 'STATE_UPDATE') {
          if (data.mediaSrc !== undefined) setMediaSrc(data.mediaSrc);
          if (data.isVideo !== undefined) setIsVideo(data.isVideo);
          if (data.globalParams !== undefined) setGlobalParams(data.globalParams);
          if (data.activeEffectId !== undefined) {
            const effect = EFFECTS.find(eff => eff.id === data.activeEffectId);
            if (effect) setActiveEffect(effect);
          }
          if (data.effectParams !== undefined) setEffectParams(data.effectParams);
        }
      } else if (data.type === 'REQUEST_SYNC') {
        syncChannel.postMessage({
          type: 'STATE_UPDATE',
          mediaSrc,
          isVideo,
          globalParams,
          activeEffectId: activeEffect.id,
          effectParams
        });
      }
    };

    syncChannel.onmessage = handleMessage;
    if (isOnAirView) syncChannel.postMessage({ type: 'REQUEST_SYNC' });

    return () => { syncChannel.onmessage = null; };
  }, [isOnAirView, syncChannel, mediaSrc, isVideo, globalParams, activeEffect, effectParams]);

  const handleUpload = (file: File) => {
    const url = URL.createObjectURL(file);
    setMediaSrc(url);
    setIsVideo(file.type.startsWith('video'));
  };

  const handleExport = () => {
    if (rendererRef.current) rendererRef.current.startExport();
  };

  const handleOnAir = () => {
    const url = new URL(window.location.href);
    url.searchParams.set('view', 'onair');
    window.open(
      url.toString(), 
      'VisualParameterOnAir', 
      'width=1280,height=720,menubar=no,toolbar=no,location=no,status=no,resizable=yes'
    );
  };

  const handleEffectSelect = (effect: EffectDef) => {
    setActiveEffect(effect);
    setEffectParams(effect.defaultParams);
  };

  // Mix Mode
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (globalParams.mixMode && !isOnAirView) {
      const mix = () => {
        const randomEffect = EFFECTS[Math.floor(Math.random() * EFFECTS.length)];
        setActiveEffect(randomEffect);
        const newParams: any = {};
        (Object.entries(randomEffect.paramConfig) as [string, ParamConfig][]).forEach(([key, config]) => {
           if (config.randomRange) {
               newParams[key] = config.step && config.step % 1 === 0 
                ? randomInt(config.randomRange[0], config.randomRange[1])
                : parseFloat(randomFloat(config.randomRange[0], config.randomRange[1]).toFixed(2));
           } else {
               newParams[key] = randomEffect.defaultParams[key];
           }
        });
        setEffectParams(newParams);
      };
      mix();
      interval = setInterval(mix, 2500);
    }
    return () => clearInterval(interval);
  }, [globalParams.mixMode, isOnAirView]);

  // Color Mix
  useEffect(() => {
    let timer: ReturnType<typeof setInterval>;
    let lerpTimer: ReturnType<typeof setInterval>;
    if (globalParams.colorMix && !isOnAirView) {
      let targetHue = globalParams.hue;
      const pickNewTarget = () => { targetHue = (targetHue + randomInt(40, 120)) % 360; };
      lerpTimer = setInterval(() => {
        setGlobalParams(prev => {
          const nextHue = prev.hue + (targetHue - prev.hue) * 0.1;
          return { ...prev, hue: nextHue, effectColor: hslToHex(nextHue, prev.saturation, prev.lightness), gradientPreset: 0 };
        });
      }, 100);
      pickNewTarget();
      timer = setInterval(pickNewTarget, 3000);
    }
    return () => { clearInterval(timer); clearInterval(lerpTimer); };
  }, [globalParams.colorMix, isOnAirView]);

  // 온에어 뷰 렌더링
  if (isOnAirView) {
    return (
      <div className="fixed inset-0 bg-black flex items-center justify-center overflow-hidden">
        {!isOnAirActive && (
          <div 
            className="absolute inset-0 z-[200] bg-zinc-900 flex flex-col items-center justify-center cursor-pointer group"
            onClick={() => setIsOnAirActive(true)}
          >
            <div className="w-24 h-24 rounded-full border border-white/20 flex items-center justify-center transition-all group-hover:scale-110 group-hover:border-red-500">
               <div className="w-4 h-4 rounded-full bg-red-500 animate-pulse"></div>
            </div>
            <span className="mt-8 text-[12px] font-black tracking-[1em] text-white/40 uppercase group-hover:text-white transition-colors">Click to Start Sync</span>
            <span className="mt-4 text-[9px] font-bold text-white/20 uppercase tracking-widest">Enable Autoplay & AI Engine</span>
          </div>
        )}

        <CanvasRenderer 
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={() => {}} 
          isCleanFeed={true}
        />

        {isOnAirActive && !mediaSrc && (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-white/10 gap-4">
            <span className="text-[12px] font-black tracking-[1.5em] uppercase animate-pulse">Waiting for Signal</span>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="relative h-screen w-full bg-white font-sans overflow-hidden text-zinc-900">
      <div className="absolute top-0 left-0 right-0 z-50 pointer-events-none">
        <Header onExport={handleExport} onAir={handleOnAir} isExporting={isExporting} />
      </div>
      <main className="w-full h-full">
        <CanvasRenderer 
          ref={rendererRef}
          mediaSrc={mediaSrc} 
          isVideo={isVideo}
          activeEffect={activeEffect}
          effectParams={effectParams}
          globalParams={globalParams}
          onUpload={handleUpload}
          onExportStateChange={setIsExporting}
        />
      </main>
      <div className="absolute bottom-3 left-1/2 -translate-x-1/2 z-50 w-full px-6 max-w-[1600px] pointer-events-none">
         <div className="pointer-events-auto">
            <ControlPanel 
              globalParams={globalParams}
              setGlobalParams={setGlobalParams}
              activeEffect={activeEffect}
              effectParams={effectParams}
              setEffectParams={setEffectParams}
              allEffects={EFFECTS}
              onSelectEffect={handleEffectSelect}
              isVideo={isVideo}
            />
         </div>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  isCleanFeed?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  isCleanFeed = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const internalCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const startTimeRef = useRef<number>(Date.now());
  const lastMaskRef = useRef<ImageData | null>(null);
  const frameCountRef = useRef<number>(0);

  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [exportEta, setExportEta] = useState(0);

  const trackingOffsetRef = useRef({ x: 0, y: 0, scale: 1.0 });
  const PROC_WIDTH = 800; 

  // 비디오 강제 재생 및 루프 유지 로직
  useEffect(() => {
    if (isVideo && mediaLoaded && sourceVideoRef.current) {
        const playVideo = async () => {
            try {
                sourceVideoRef.current!.muted = true;
                await sourceVideoRef.current!.play();
            } catch (err) {
                console.warn("Autoplay blocked. Waiting for user interaction.");
            }
        };
        playVideo();
    }
  }, [mediaSrc, mediaLoaded, isVideo]);

  useImperativeHandle(ref, () => ({
    startExport: async () => {
      if (!canvasRef.current || !mediaSrc) return;
      const canvas = canvasRef.current;
      const chunks: Blob[] = [];
      const stream = (canvas as any).captureStream(60); 
      const mimeTypes = ['video/mp4;codecs=h264', 'video/mp4', 'video/webm;codecs=h264', 'video/webm'];
      const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || 'video/webm';
      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 12000000 });
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
        a.download = `visual-parameter-h264-${Date.now()}.${extension}`;
        a.click();
        setIsExporting(false); setExportProgress(0); setExportEta(0); onExportStateChange?.(false);
        if (sourceVideoRef.current) { sourceVideoRef.current.muted = true; sourceVideoRef.current.play(); }
      };
      setIsExporting(true); onExportStateChange?.(true);
      if (isVideo && sourceVideoRef.current) {
        const video = sourceVideoRef.current;
        video.currentTime = 0; video.play(); recorder.start();
        const progressInterval = setInterval(() => {
          if (!video.duration) return;
          setExportProgress((video.currentTime / video.duration) * 100);
          setExportEta(Math.max(0, video.duration - video.currentTime));
        }, 100);
        const handleVideoEnd = () => { recorder.stop(); clearInterval(progressInterval); video.removeEventListener('ended', handleVideoEnd); };
        video.addEventListener('ended', handleVideoEnd);
      } else {
        const duration = 3; recorder.start(); const start = Date.now();
        const progressInterval = setInterval(() => {
          const elapsed = (Date.now() - start) / 1000;
          setExportProgress((elapsed / duration) * 100);
          setExportEta(Math.max(0, duration - elapsed));
          if (elapsed >= duration) { recorder.stop(); clearInterval(progressInterval); }
        }, 100);
      }
    }
  }));

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) { segmenterRef.current = segmenter; setAiReady(true); } else { segmenter.close(); }
      } catch (err) {}
    }
    initAI();
    return () => { active = false; segmenterRef.current?.close(); };
  }, [isVideo]);

  useEffect(() => {
    const handleResize = () => {
      if (!containerRef.current) return;
      if (isCleanFeed && mediaLoaded) {
        const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;
        if (source) {
          const sw = isVideo ? (source as HTMLVideoElement).videoWidth : (source as HTMLImageElement).naturalWidth;
          const sh = isVideo ? (source as HTMLVideoElement).videoHeight : (source as HTMLImageElement).naturalHeight;
          if (sw === 0) return; // 미처 로드되지 않은 경우 스킵
          const sAspect = sw / sh;
          const windowW = window.innerWidth;
          const windowH = window.innerHeight;
          const windowAspect = windowW / windowH;
          let targetW, targetH;
          if (sAspect > windowAspect) { targetW = windowW; targetH = windowW / sAspect; } 
          else { targetH = windowH; targetW = windowH * sAspect; }
          setDimensions({ w: Math.floor(targetW), h: Math.floor(targetH) });
          return;
        }
      }
      const w = isCleanFeed ? containerRef.current.clientWidth : Math.floor(window.innerWidth / 2);
      const h = isCleanFeed ? containerRef.current.clientHeight : window.innerHeight;
      setDimensions({ w, h });
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, [isCleanFeed, mediaLoaded, isVideo, mediaSrc]);

  const animate = () => {
    if (canvasRef.current && mediaLoaded && dimensions.w > 0 && segmenterRef.current) {
      const displayCtx = canvasRef.current.getContext('2d');
      const internalCanvas = internalCanvasRef.current;
      const scale = PROC_WIDTH / dimensions.w;
      const procW = PROC_WIDTH;
      const procH = Math.floor(dimensions.h * scale);
      if (internalCanvas.width !== procW) { internalCanvas.width = procW; internalCanvas.height = procH; }
      const ctx = internalCanvas.getContext('2d', { willReadFrequently: true });
      const source = isVideo ? sourceVideoRef.current : sourceImageRef.current;

      if (ctx && displayCtx && source) {
          const elapsed = (Date.now() - startTimeRef.current) / 1000;
          frameCountRef.current++;

          // 성능을 위해 3프레임마다 마스크 업데이트 (비디오일 때)
          const shouldUpdateMask = !isVideo || (frameCountRef.current % 3 === 0);

          if (shouldUpdateMask || !lastMaskRef.current) {
              try {
                const result = isVideo 
                  ? segmenterRef.current.segmentForVideo(source as HTMLVideoElement, Date.now()) 
                  : segmenterRef.current.segment(source as HTMLImageElement);
                if (result?.categoryMask) {
                   const maskData = result.categoryMask.getAsUint8Array();
                   const mw = result.categoryMask.width; const mh = result.categoryMask.height;
                   const rgba = new Uint8ClampedArray(mw * mh * 4);
                   let sumX = 0; let sumY = 0; let count = 0;
                   for (let i = 0; i < maskData.length; i++) {
                      const val = maskData[i] > 0 ? 255 : 0; const idx = i * 4;
                      rgba[idx] = rgba[idx+1] = rgba[idx+2] = val; rgba[idx+3] = 255;
                      if (val > 0) { sumX += i % mw; sumY += Math.floor(i / mw); count++; }
                   }
                   if (count > 100 && globalParams.autoTracking) {
                       const centerX = (sumX / count) / mw; const centerY = (sumY / count) / mh;
                       const targetX = (0.5 - centerX) * procW * 0.5; const targetY = (0.5 - centerY) * procH * 0.5;
                       const areaFraction = count / (mw * mh);
                       const targetScale = 1.1 + Math.max(0, (0.25 - areaFraction) * 1.5);
                       trackingOffsetRef.current.x += (targetX - trackingOffsetRef.current.x) * 0.08;
                       trackingOffsetRef.current.y += (targetY - trackingOffsetRef.current.y) * 0.08;
                       trackingOffsetRef.current.scale += (targetScale - trackingOffsetRef.current.scale) * 0.05;
                   } else if (!globalParams.autoTracking) {
                       trackingOffsetRef.current.x *= 0.9; trackingOffsetRef.current.y *= 0.9;
                       trackingOffsetRef.current.scale += (1.0 - trackingOffsetRef.current.scale) * 0.1;
                   }
                   lastMaskRef.current = new ImageData(rgba, mw, mh);
                   result.categoryMask.close();
                }
              } catch (e) {}
          }
          ctx.save();
          if (globalParams.autoTracking || trackingOffsetRef.current.scale > 1.01) {
            ctx.translate(trackingOffsetRef.current.x, trackingOffsetRef.current.y); ctx.translate(procW/2, procH/2);
            ctx.scale(trackingOffsetRef.current.scale, trackingOffsetRef.current.scale); ctx.translate(-procW/2, -procH/2);
          }
          renderFrame(ctx, source, activeEffect.id, effectParams, globalParams, elapsed, lastMaskRef.current);
          ctx.restore();
          displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, 0, 0, dimensions.w, dimensions.h);
      }
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeEffect, effectParams, globalParams, mediaLoaded, dimensions, aiReady]);

  if (isCleanFeed) {
    return (
      <div className="w-full h-full bg-black flex items-center justify-center overflow-hidden" ref={containerRef}>
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="hidden" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="hidden" onLoad={() => setMediaLoaded(true)} />
        )}
        <canvas 
          ref={canvasRef} 
          width={dimensions.w} 
          height={dimensions.h} 
          style={{ width: dimensions.w, height: dimensions.h }}
          className="shadow-2xl"
        />
      </div>
    );
  }

  return (
    <div className="flex w-full h-screen overflow-hidden bg-white" ref={containerRef}>
      {isExporting && (
        <div className="absolute inset-0 z-[100] bg-black/80 backdrop-blur-xl flex flex-col items-center justify-center text-white p-10">
          <div className="relative w-24 h-24 mb-10 flex items-center justify-center">
            <div className="absolute inset-0 border-4 border-white/10 rounded-full"></div>
            <svg className="absolute inset-0 w-full h-full -rotate-90">
              <circle cx="48" cy="48" r="44" stroke="white" strokeWidth="4" fill="transparent" strokeDasharray={276} strokeDashoffset={276 - (276 * exportProgress) / 100} strokeLinecap="round" className="transition-all duration-300" />
            </svg>
            <span className="text-[14px] font-black">{Math.floor(exportProgress)}%</span>
          </div>
          <div className="flex flex-col items-center gap-2">
            <span className="text-[14px] font-black uppercase tracking-[0.5em] animate-pulse">Encoding H264 Video</span>
            <span className="text-[10px] font-bold text-white/60 tracking-widest uppercase">
              Estimated Remaining: <span className="text-white">{exportEta.toFixed(1)}s</span>
            </span>
          </div>
          <div className="mt-12 w-64 h-1 bg-white/10 rounded-full overflow-hidden">
            <div className="h-full bg-white transition-all duration-300" style={{ width: `${exportProgress}%` }}></div>
          </div>
          <p className="mt-6 text-[9px] font-bold text-white/40 uppercase tracking-[0.2em]">Do not close this tab until rendering is complete.</p>
        </div>
      )}

      <div 
        className={`relative w-1/2 h-full flex items-center justify-center transition-opacity duration-700 ${isDragging ? 'opacity-50' : 'opacity-100'}`}
        onDragOver={(e) => {e.preventDefault(); setIsDragging(true);}}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {e.preventDefault(); setIsDragging(false); if(e.dataTransfer.files[0]) onUpload(e.dataTransfer.files[0]);}}
      >
        {!mediaSrc && (
          <div className="flex flex-col items-center gap-4 text-zinc-100 pointer-events-none">
             <span className="text-[9px] font-black uppercase tracking-[0.4em]">Initialize_Input (Drop File)</span>
          </div>
        )}
        {mediaSrc && isVideo && (
            <video ref={sourceVideoRef} src={mediaSrc} className="w-full h-full object-cover" muted loop playsInline autoPlay onLoadedMetadata={() => setMediaLoaded(true)} />
        )}
        {mediaSrc && !isVideo && (
            <img ref={sourceImageRef} src={mediaSrc} className="w-full h-full object-cover" onLoad={() => setMediaLoaded(true)} />
        )}
      </div>

      <div className="relative w-1/2 h-full bg-white flex items-center justify-center">
        <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className={`w-full h-full transition-all duration-1000 ${mediaLoaded ? 'opacity-100' : 'opacity-0'}`} />
      </div>
    </div>
  );
});

export default CanvasRenderer;

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { GlobalParams, EffectDef } from '../types';
import { renderFrame } from '../services/renderEngine';
import { ImageSegmenter, FilesetResolver } from '@mediapipe/tasks-vision';

interface CanvasRendererProps {
  mediaSrc: string | null;
  isVideo: boolean;
  activeEffect: EffectDef;
  effectParams: any;
  globalParams: GlobalParams;
  onUpload: (file: File) => void;
  onExportStateChange?: (isExporting: boolean) => void;
  isCleanFeed?: boolean;
}

export interface CanvasRendererHandle {
  startExport: () => void;
}

const CanvasRenderer = forwardRef<CanvasRendererHandle, CanvasRendererProps>(({
  mediaSrc,
  isVideo,
  activeEffect,
  effectParams,
  globalParams,
  onUpload,
  onExportStateChange,
  isCleanFeed = false
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const internalCanvasRef = useRef<HTMLCanvasElement>(document.createElement('canvas'));
  const containerRef = useRef<HTMLDivElement>(null);
  const sourceVideoRef = useRef<HTMLVideoElement>(null);
  const sourceImageRef = useRef<HTMLImageElement>(null);
  const segmenterRef = useRef<ImageSegmenter | null>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const startTimeRef = useRef<number>(Date.now());
  const lastMaskRef = useRef<ImageData | null>(null);
  const frameCountRef = useRef<number>(0);

  // unitSize: 패턴 한 칸의 크기, canvasSize: 실제 렌더링될 캔버스의 전체 크기
  const [unitSize, setUnitSize] = useState({ w: 0, h: 0 });
  const [canvasSize, setCanvasSize] = useState({ w: 0, h: 0 });

  const [mediaLoaded, setMediaLoaded] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [exportEta, setExportEta] = useState(0);

  const trackingOffsetRef = useRef({ x: 0, y: 0, scale: 1.0 });
  const PROC_WIDTH = 800; 

  useEffect(() => {
    if (isVideo && mediaLoaded && sourceVideoRef.current) {
        const playVideo = async () => {
            try {
                sourceVideoRef.current!.muted = true;
                await sourceVideoRef.current!.play();
            } catch (err) {
                console.warn("Autoplay blocked. Waiting for user interaction.");
            }
        };
        playVideo();
    }
  }, [mediaSrc, mediaLoaded, isVideo]);

  useImperativeHandle(ref, () => ({
    startExport: async () => {
      if (!canvasRef.current || !mediaSrc) return;
      const canvas = canvasRef.current;
      const chunks: Blob[] = [];
      const stream = (canvas as any).captureStream(60); 
      const mimeTypes = ['video/mp4;codecs=h264', 'video/mp4', 'video/webm;codecs=h264', 'video/webm'];
      const mimeType = mimeTypes.find(type => MediaRecorder.isTypeSupported(type)) || 'video/webm';
      const recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 12000000 });
      recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
        a.download = `visual-parameter-h264-${Date.now()}.${extension}`;
        a.click();
        setIsExporting(false); setExportProgress(0); setExportEta(0); onExportStateChange?.(false);
        if (sourceVideoRef.current) { sourceVideoRef.current.muted = true; sourceVideoRef.current.play(); }
      };
      setIsExporting(true); onExportStateChange?.(true);
      if (isVideo && sourceVideoRef.current) {
        const video = sourceVideoRef.current;
        video.currentTime = 0; video.play(); recorder.start();
        const progressInterval = setInterval(() => {
          if (!video.duration) return;
          setExportProgress((video.currentTime / video.duration) * 100);
          setExportEta(Math.max(0, video.duration - video.currentTime));
        }, 100);
        const handleVideoEnd = () => { recorder.stop(); clearInterval(progressInterval); video.removeEventListener('ended', handleVideoEnd); };
        video.addEventListener('ended', handleVideoEnd);
      } else {
        const duration = 3; recorder.start(); const start = Date.now();
        const progressInterval = setInterval(() => {
          const elapsed = (Date.now() - start) / 1000;
          setExportProgress((elapsed / duration) * 100);
          setExportEta(Math.max(0, duration - elapsed));
          if (elapsed >= duration) { recorder.stop(); clearInterval(progressInterval); }
        }, 100);
      }
    }
  }));

  useEffect(() => {
    let active = true;
    async function initAI() {
      try {
        const vision = await FilesetResolver.forVisionTasks("https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm");
        const segmenter = await ImageSegmenter.createFromOptions(vision, {
          baseOptions: {
            modelAssetPath: "https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16/latest/selfie_segmenter.tflite",
            delegate: "GPU"
          },
          runningMode: isVideo ? "VIDEO" : "IMAGE",
          outputCategoryMask: true
        });
        if (active) { segmenterRef.current = segmenter; setAiReady(true); } else { segmenter.close(); }
      } catch (err) {}
