            displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, centralStartX, 0, unitW, unitH);
          } else {
            displayCtx.drawImage(internalCanvas, 0, 0, procW, procH, 0, 0, unitSize.w, unitSize.h);
          }
      }
    }
