            <div className="flex flex-col items-center">
               <span className="text-[32px] font-black leading-none">{Math.floor(exportProgress)}%</span>
               <span className="text-[10px] font-bold text-white/40 mt-2 tracking-widest uppercase">Rendering</span>
            </div>
          </div>

          <div className="flex flex-col items-center gap-3 text-center">
            <span className="text-[16px] font-black uppercase tracking-[0.4em] animate-pulse">Encoding H.264 Master</span>
            <div className="flex items-center gap-4 text-white/60">
                <div className="flex flex-col items-center">
                  <span className="text-[9px] font-bold uppercase tracking-widest text-white/30 mb-1">Estimated Remaining</span>
                  <span className="text-[14px] font-mono font-bold text-white tracking-wider">{exportEta.toFixed(1)}s</span>
