          <div className="mt-16 max-w-md w-full">
            <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                <div className="h-full bg-white transition-all duration-300 shadow-[0_0_15px_rgba(255,255,255,0.5)]" style={{ width: `${exportProgress}%` }}></div>
            </div>
