import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing.");
  return new GoogleGenAI({ apiKey });
};

export async function analyzeImage(base64Data: string, type: string): Promise<string> {
  const ai = getAIClient();
  const mimeType = base64Data.split(';')[0].split(':')[1];
  const base64 = base64Data.split(',')[1];

  const prompt = `Describe this fashion item or person reference for a high-end AI styling engine. Focus on textures, colors, fit, and distinctive details. Type: ${type}`;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts: [{ inlineData: { mimeType, data: base64 } }, { text: prompt }] },
    config: { temperature: 0.1 }
  });

  return response.text || "No description.";
}

/**
 * Stage 1: Analyze user intent and synthesize all inputs into a master editorial vision.
 */
async function synthesizeEditorialVision(params: {
  userPrompt: string;
  faceDesc?: string;
  poseDesc?: string;
  clothingItems: { description: string; type: string }[];
}): Promise<string> {
  const ai = getAIClient();

  const analysisPrompt = `
    Act as a World-Class Fashion Creative Director. 
    Analyze the following inputs and synthesize a single, cohesive, and extremely detailed high-end fashion editorial prompt.

    USER INTENT: "${params.userPrompt || 'High-end studio fashion editorial'}"
    FACE REFERENCE: ${params.faceDesc || 'Maintain natural identity'}
    POSE REFERENCE: ${params.poseDesc || 'Dynamic professional model pose'}
    CLOTHING CONTEXT: ${params.clothingItems.map(c => `[${c.type}: ${c.description}]`).join(', ')}

    Your task:
    1. Interpret the "USER INTENT" deeply. If it's brief, expand it into a full atmosphere (lighting, camera lens, background, mood).
    2. Seamlessly integrate the clothing items into the scene.
    3. Ensure the result is a professional prompt for an image generation model. 
    4. Focus on high-end textures (silk, leather, grain), realistic studio lighting (Rembrandt, softbox, or cinematic), and editorial composition.

    Return ONLY the final expanded prompt text.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: analysisPrompt,
    config: { temperature: 0.7 }
  });

  return response.text || params.userPrompt;
}

export async function generateMidjourneyPromptFromImage(imageUrl: string): Promise<{ positive: string, negative: string }> {
  const ai = getAIClient();
  const mimeType = imageUrl.split(';')[0].split(':')[1];
  const base64 = imageUrl.split(',')[1];

  const prompt = `Act as a world-class Midjourney Prompt Engineer. Analyze this fashion image and create a perfect MJ V7 prompt. Return as JSON with "positive" and "negative" keys. Include --ar 3:4 --v 7.0 --stylize 300.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: { parts: [{ inlineData: { mimeType, data: base64 } }, { text: prompt }] },
    config: { responseMimeType: "application/json", temperature: 0.7 }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    return { positive: "High-end fashion editorial --ar 3:4 --v 7.0", negative: "low quality" };
  }
}

export async function generateFashionMix(params: {
  faceImage?: string;
  faceDesc?: string;
  poseImage?: string;
  poseDesc?: string;
  clothingImages: { data: string; description: string; type: string }[];
  additionalPrompt: string;
  onStatusUpdate?: (status: string) => void;
}): Promise<string> {
  const ai = getAIClient();

  // Step 1: Synthesize Vision using Gemini 3 Flash
  if (params.onStatusUpdate) params.onStatusUpdate("Analyzing Prompt Intent...");
  const masterVision = await synthesizeEditorialVision({
    userPrompt: params.additionalPrompt,
    faceDesc: params.faceDesc,
    poseDesc: params.poseDesc,
    clothingItems: params.clothingImages.map(c => ({ description: c.description, type: c.type }))
  });

  // Step 2: Generate Image using Gemini 3 Pro
  if (params.onStatusUpdate) params.onStatusUpdate("Synthesizing Editorial...");

  const parts: any[] = [{ text: `System Directive: You are a high-end image synthesis engine. Execute the following Creative Director Vision with absolute fidelity to the provided image references. VISION: ${masterVision}` }];

  if (params.faceImage) parts.push({ inlineData: { mimeType: 'image/png', data: params.faceImage.split(',')[1] } });
  if (params.poseImage) parts.push({ inlineData: { mimeType: 'image/png', data: params.poseImage.split(',')[1] } });

  params.clothingImages.forEach(img => {
    parts.push({ inlineData: { mimeType: 'image/png', data: img.data.split(',')[1] } });
  });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts },
    config: { imageConfig: { aspectRatio: "3:4", imageSize: "2K" } }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
  }
  throw new Error("Generation failed.");
}

