export async function generateFashionMix(params: {
  faceImage?: string;
  faceDesc?: string;
  poseImage?: string;
  poseDesc?: string;
  clothingImages: { data: string; description: string; type: string }[];
  additionalPrompt: string;
  onStatusUpdate?: (status: string) => void;
}): Promise<string> {
  const ai = getAIClient();

  // Step 1: Deep Vision Synthesis
  if (params.onStatusUpdate) params.onStatusUpdate("Analyzing Style Intent...");
  const masterVision = await synthesizeEditorialVision({
    userPrompt: params.additionalPrompt,
    faceDesc: params.faceDesc,
    poseDesc: params.poseDesc,
    clothingItems: params.clothingImages.map(c => ({ description: c.description, type: c.type }))
  });

  // Step 2: High-Fidelity Generation
  if (params.onStatusUpdate) params.onStatusUpdate("Synthesizing 2K Editorial...");

  const parts: any[] = [
    { text: `Strict Directive: You must synthesize the final image based on this precise creative vision. VISION: ${masterVision}. Ensure the visual identity of the provided images is strictly maintained while adhering to the atmosphere described.` }
  ];

  if (params.faceImage) parts.push({ inlineData: { mimeType: 'image/png', data: params.faceImage.split(',')[1] } });
  if (params.poseImage) parts.push({ inlineData: { mimeType: 'image/png', data: params.poseImage.split(',')[1] } });

  params.clothingImages.forEach(img => {
    parts.push({ inlineData: { mimeType: 'image/png', data: img.data.split(',')[1] } });
  });

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts },
    config: { 
      imageConfig: { 
        aspectRatio: "3:4", 
        imageSize: "2K" 
      } 
    }
  });

  if (!response.candidates?.[0]?.content?.parts) throw new Error("Synthesis aborted.");

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
  }
  throw new Error("Generation failed.");
}

